/* ============================================================
   TOAST & LOADER
   ============================================================ */
.lbcc .toast {
    position: fixed;
    bottom: 24px;
    left: 50%;
    transform: translateX(-50%) translateY(20px);
    background: var(--g800);
    color: #fff;
    padding: 11px 20px;
    border-radius: 99px;
    font-size: 12.5px;
    font-weight: 600;
    display: flex;
    gap: 9px;
    align-items: center;
    opacity: 0;
    pointer-events: none;
    transition: .22s;
    z-index: 1200;
}

.lbcc .toast.on {
    opacity: 1;
    transform: translateX(-50%);
}

.lbcc .tk {
    background: var(--g500);
    width: 18px;
    height: 18px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 11px;
}

.lbcc .loader {
    position: fixed;
    inset: 0;
    background: rgba(243, 250, 244, .75);
    display: none;
    align-items: center;
    justify-content: center;
    z-index: 500;
    pointer-events: none;
}

.lbcc .loader.on {
    display: flex;
}

.lbcc .spin {
    width: 34px;
    height: 34px;
    border: 3px solid var(--g100);
    border-top-color: var(--g600);
    border-radius: 50%;
    animation: lbcc-sp .8s linear infinite;
}

@keyframes lbcc-sp {
    to { transform: rotate(360deg); }
}

.lbcc .err {
    background: #FDECEA;
    color: #C62828;
    border: 1px solid #F5C6C2;
    padding: 10px 14px;
    border-radius: 10px;
