/* ============================================================
   v16 ADDITIONS — native date range bar + roster branch tag
   ============================================================ */

/* --- Global date range bar (injected by injectGlobalRangeUI) --- */
.lbcc #globalRangeCard input[type="date"] {
    font-family: inherit;
    color: #1B5E20;
    cursor: pointer;
    line-height: 1.2;
    min-height: 32px;
    -webkit-appearance: none;
    appearance: none;
}

.lbcc #globalRangeCard input[type="date"]:focus {
    outline: none;
    border-color: #2E7D32;
    box-shadow: 0 0 0 3px rgba(46, 125, 50, 0.15);
}

/* Make the native calendar icon green and obviously clickable */
.lbcc #globalRangeCard input[type="date"]::-webkit-calendar-picker-indicator {
    cursor: pointer;
    opacity: 0.65;
    padding: 2px;
    filter: invert(28%) sepia(52%) saturate(668%) hue-rotate(73deg) brightness(93%) contrast(89%);
}

.lbcc #globalRangeCard input[type="date"]::-webkit-calendar-picker-indicator:hover {
    opacity: 1;
}

/* Firefox / Safari fallback so the box does not collapse */
.lbcc #globalRangeCard input[type="date"]::-webkit-datetime-edit {
    padding: 0;
}

.lbcc #globalRangeCard .wbtn:hover {
    filter: brightness(1.08);
}

.lbcc #globalRangeCard .wbtn:active {
    transform: translateY(1px);
}

/* --- Roster branch tag (replaces the now-hidden duplicate dropdown) --- */
.lscc-rp-branch-tag {
    display: inline-block;
    padding: 6px 12px;
    border: 1px solid var(--line);
    border-radius: 6px;
    background: #F1F8E9;
    color: #1B5E20;
    font-size: 0.85rem;
    font-weight: 700;
    white-space: nowrap;
}

.lscc-rp-branch-tag:empty {
    display: none;
}

/* --- Source Wise / CC Leads drawer tables --- */
.lbcc .mx .tbl td.a,
.lbcc .tbl td.a {
    color: #E65100;
}

/* Keep the wider GST tables readable inside the drawer */
.lbcc #mBody .tbl th,
.lbcc #mBody .tbl td {
    white-space: nowrap;
}

@media (max-width: 900px) {
    .lbcc #globalRangeCard input[type="date"] {
        width: 100% !important;
    }
    .lbcc #globalRangeCard > div {
        gap: 8px;
    }
}

/* --- v16: walk-in recorded reason --- */
.lbcc .wkreason {
    flex-basis: 100%;
    margin-top: 5px;
    padding: 3px 8px;
    border-left: 3px solid #E74C3C;
    border-radius: 4px;
    background: #FDECEA;
    color: #C0392B;
    font-size: 11px;
    font-weight: 600;
    line-height: 1.4;
    max-width: 240px;
