}

/* ============================================================
   v16 — portal-safe reason modal (no frappe.ui.Dialog dependency)
   ============================================================ */
.lbcc-reason-overlay {
    position: fixed;
    inset: 0;
    z-index: 99999;
    background: rgba(12, 32, 16, 0.55);
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 20px;
    animation: lbccReasonFade 0.14s ease-out;
}

@keyframes lbccReasonFade {
    from { opacity: 0; }
    to   { opacity: 1; }
}

.lbcc-reason-box {
    width: 100%;
    max-width: 460px;
    background: #fff;
    border-radius: 14px;
    box-shadow: 0 18px 50px rgba(0, 0, 0, 0.3);
    overflow: hidden;
    font-family: inherit;
    animation: lbccReasonPop 0.16s ease-out;
}

@keyframes lbccReasonPop {
    from { transform: translateY(10px) scale(0.98); opacity: 0; }
    to   { transform: none; opacity: 1; }
}

.lbcc-reason-hd {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    padding: 14px 18px;
    background: linear-gradient(135deg, #2E7D32 0%, #1B5E20 100%);
    color: #fff;
    font-size: 14px;
    font-weight: 700;
}

.lbcc-reason-x {
    background: rgba(255, 255, 255, 0.18);
    border: none;
    color: #fff;
    width: 26px;
    height: 26px;
    border-radius: 6px;
    cursor: pointer;
    font-size: 13px;
    line-height: 1;
    flex-shrink: 0;
}

.lbcc-reason-x:hover { background: rgba(255, 255, 255, 0.32); }

.lbcc-reason-bd { padding: 16px 18px 6px; }

.lbcc-reason-bd label {
    display: block;
    font-size: 12px;
    font-weight: 700;
    color: #33475B;
    margin-bottom: 6px;
}

.lbcc-reason-bd textarea {
    width: 100%;
    padding: 9px 11px;
    border: 2px solid #c8d6c8;
    border-radius: 8px;
    font-size: 13px;
    font-family: inherit;
    color: #1a1a1a;
    resize: vertical;
    min-height: 74px;
    background: #fff;
}

.lbcc-reason-bd textarea:focus {
