}

.lbcc-reason-err {
    min-height: 16px;
    margin-top: 5px;
    font-size: 11.5px;
    font-weight: 700;
    color: #C62828;
}

.lbcc-reason-hint {
    font-size: 11px;
    color: #5F6F63;
    line-height: 1.45;
    margin-bottom: 4px;
}

.lbcc-reason-ft {
    display: flex;
    justify-content: flex-end;
    gap: 8px;
    padding: 12px 18px 16px;
}

.lbcc-reason-btn {
    padding: 8px 18px;
    border-radius: 7px;
    border: 1px solid #d6e0d6;
    background: #fff;
    color: #33475B;
    font-size: 12.5px;
    font-weight: 700;
    cursor: pointer;
    font-family: inherit;
}

.lbcc-reason-btn:hover { background: #f2f7f2; }

.lbcc-reason-btn.primary {
    background: #2E7D32;
    border-color: #2E7D32;
    color: #fff;
}

.lbcc-reason-btn.primary:hover { background: #256b28; }

@media (max-width: 520px) {
    .lbcc-reason-box { max-width: 100%; }
}

/* --- v16: walk-in date grouping (range view) --- */
.lbcc .wkdate {
    display: flex;
