.lbcc .wbtn.i {
    background: #FFF8E1;
    border-color: #FFB300;
    color: #E65100;
    font-weight: 800;
}
.lbcc .wbtn.i:hover { background: #FFECB3; }

.lbcc .wbtn.u {
    background: #F5F5F5;
    border-color: #BDBDBD;
    color: #555;
}
.lbcc .wbtn.u:hover { background: #EEEEEE; }

/* ============================================================
   v17 — Quick date preset chips
   ============================================================ */
.lbcc .gr-presets {
    display: flex;
    align-items: center;
    gap: 6px;
    flex-wrap: wrap;
    margin-top: 10px;
    padding-top: 10px;
    border-top: 1px dashed #c8d6c8;
}

.lbcc .gr-presets-l {
    font-size: 10px;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: #7A8B7E;
    margin-right: 2px;
}

.lbcc .gr-chip {
