/* ============================================================
   BRANCH COMMAND CENTER · PREMIUM COMPACT PRESENTATION
   Appended after the original CSS to preserve modal/ERP styling.
   ============================================================ */
.lbcc {
  --g900:#103e31; --g800:#15503f; --g700:#216348; --g600:#287452;
  --g100:#e7f3ec; --g50:#f4f7f6; --ink:#172d26; --mut:#60746b;
  --line:#dce5df; --r:12px; --bcc-header-height:112px;
  --shadow:0 2px 8px rgba(18,53,39,.035),0 1px 2px rgba(18,53,39,.04);
  font-size:13px; background:#f2f5f4; line-height:1.45;
}
.lbcc .wrap {max-width:1680px;margin:0 auto;padding:14px 22px 36px;}
.lbcc .hdr {padding:14px 24px 0 62px;background:linear-gradient(115deg,#0d342a,#15533d);box-shadow:0 4px 16px #173d2520;}
.lbcc .hdr-in {max-width:1636px;gap:12px;min-height:44px;}
.lbcc .logo h1 {font-size:22px;font-weight:750;letter-spacing:-.6px;line-height:1.25;}
.lbcc .logo small {font-size:9px;letter-spacing:1.5px;margin-bottom:3px;color:#b4d9c7;}
.lbcc .hdr-center {flex:0 1 auto;justify-content:flex-end;gap:12px;}
.lbcc .hdr-center .live-chip {font-size:11px;padding:6px 10px;}
.lbcc .br-filter {border-radius:9px;padding:5px 7px 5px 10px;gap:10px;}
.lbcc .br-filter .br-label {font-size:10px;color:#d4e9dd;}
.lbcc .br-filter select {max-width:240px;min-width:160px;padding:5px 24px 5px 10px;font-size:12px;border-radius:6px;}
.lbcc .bcc-nav {display:flex;align-items:center;gap:4px;max-width:1636px;margin:10px auto 0;padding:0 0 10px;overflow-x:auto;scrollbar-width:thin;}
.lbcc .bcc-nav button,.lbcc .bcc-roster-nav button {flex:0 0 auto;border:1px solid transparent;border-radius:7px;padding:7px 12px;font-size:11px;font-weight:650;white-space:nowrap;line-height:1.4;}
.lbcc .bcc-nav button {background:#ffffff0b;color:#d6e9df;}
.lbcc .bcc-nav button:hover {background:#ffffff1d;color:white;}
.lbcc .bcc-nav button.bcc-active {background:#e7f3eb;color:#154b35;border-color:#ffffff40;}
.lbcc .bcc-nav .bcc-reset-layout {margin-left:auto;font-size:10px;color:#b6d3c3;border-color:#ffffff24;}
.lbcc .bcc-panel-stack {display:flex;flex-direction:column;gap:14px;min-width:0;}
.lbcc .bcc-panel {--accent:#248359;--tint:#edf6f0;background:#fff;border:1px solid var(--line);border-radius:12px;box-shadow:var(--shadow);min-width:0;scroll-margin-top:calc(var(--bcc-header-height) + 14px);}
.lbcc .bcc-gold {--accent:#b08a38;--tint:#faf7ed;}
.lbcc .bcc-blue {--accent:#3577b7;--tint:#eef4fb;}
.lbcc .bcc-teal {--accent:#21878a;--tint:#edf7f7;}
.lbcc .bcc-purple {--accent:#7a60ac;--tint:#f4f0fa;}
.lbcc .bcc-slate {--accent:#647a87;--tint:#f0f4f6;}
.lbcc .bcc-panel-head {border-radius:11px 11px 0 0;border-top:3px solid var(--accent);border-bottom:1px solid var(--line);background:linear-gradient(100deg,var(--tint),#fff);padding:11px 16px;display:flex;align-items:center;justify-content:space-between;gap:12px;}
.lbcc .bcc-panel-head h2 {font-size:16px;font-weight:750;letter-spacing:-.2px;color:#20392d;line-height:1.3;}
.lbcc .bcc-panel-head p {font-size:11px;color:#65776d;margin-top:2px;}
.lbcc .bcc-panel-actions {display:flex;align-items:center;gap:5px;flex-shrink:0;}
.lbcc .bcc-panel-actions button {height:28px;min-width:28px;background:#fff;border:1px solid #dce4de;color:#476254;border-radius:6px;font-size:12px;font-weight:650;padding:3px 7px;}
.lbcc .bcc-panel-actions [data-bcc-toggle] {min-width:72px;font-size:10px;}
.lbcc .bcc-panel-actions button:hover:not(:disabled) {background:var(--tint);border-color:var(--accent);color:var(--accent);}
.lbcc .bcc-panel-actions button:disabled {opacity:.3;cursor:default;}
.lbcc .bcc-panel-body {padding:12px 14px;min-width:0;}
.lbcc .bcc-panel-body[hidden] {display:none!important;}
.lbcc .bcc-collapsed > .bcc-panel-head {border-bottom:0;border-radius:11px;}
.lbcc .card {padding:10px 12px;margin-bottom:0;border-radius:9px;box-shadow:none;}
.lbcc .bcc-panel-body > .card {padding:0;border:0;background:transparent;}
.lbcc .card h3 {font-size:12px;letter-spacing:.2px;text-transform:none;font-weight:700;flex-wrap:wrap;margin-bottom:8px;}
.lbcc .wk-pend {font-size:11px;padding:3px 9px;letter-spacing:0;}
.lbcc .bcc-att-card .wk-pend {font-size:12px;background:#176447;color:white;}
.lbcc .grid {gap:10px;}
.lbcc .grid.r1,.lbcc .grid.r3 {grid-template-columns:repeat(3,minmax(0,1fr));}
.lbcc .grid.r2 {grid-template-columns:repeat(4,minmax(0,1fr));}
.lbcc .cols {grid-template-columns:minmax(0,1fr) 290px;gap:10px;}
.lbcc .tile {padding:13px 14px 12px 17px;gap:7px;min-width:0;border-radius:10px;box-shadow:none;}
.lbcc .tile::before {width:3px;background:var(--accent,#287452);}
.lbcc .tile:hover,.lbcc .tile:focus-visible {transform:translateY(-2px);box-shadow:0 5px 12px #153d2512;}
.lbcc .tile-top > div:first-child {min-width:0;}
.lbcc .tile-name {font-size:10px;letter-spacing:.6px;color:#526d5d;}
.lbcc .tile-big {font-size:25px;line-height:1.15;margin:3px 0;overflow-wrap:anywhere;}
.lbcc .tile-big small {font-size:11px;line-height:1.5;}
.lbcc .tile-sub {font-size:11px;overflow-wrap:anywhere;}
.lbcc .tile-ico {width:31px;height:31px;border-radius:8px;background:var(--tint,#e7f3ec);color:var(--accent,#287452);}
.lbcc .tile-ico svg {width:17px;height:17px;}
.lbcc .tile-stats {gap:8px 14px;padding-top:7px;margin-top:auto;}
.lbcc .ts b {font-size:13px;}
.lbcc .ts span {font-size:9px;letter-spacing:.15px;}
.lbcc .ts {min-width:0;}
.lbcc .badge {top:10px;right:52px;height:22px;min-width:22px;font-size:10px;animation:none;}
.lbcc .tile-hint {display:none;}
.lbcc .hbar {height:5px;}
.lbcc .tgt-mini {font-size:10px;margin-top:2px;}
.lbcc .strip {padding:0;margin:10px 0;display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:8px;}
.lbcc .strip-card {min-width:0;padding:9px 12px;border-radius:8px;box-shadow:none;border-top:2px solid #cadad0;background:#f9fbf9;}
.lbcc .strip-card .lbl {font-size:9px;letter-spacing:.5px;}
.lbcc .strip-card .val {font-size:21px;margin:2px 0;}
.lbcc .strip-card .sub {font-size:10px;overflow-wrap:anywhere;}
.lbcc .bcc-range {display:flex;flex-direction:row;align-items:center;flex-wrap:wrap;gap:12px;padding:10px 12px!important;background:#f7f9f7!important;border:1px solid #e0e7e1!important;}
.lbcc .bcc-range-caption b {font-size:12px;display:block;}
.lbcc .bcc-range-caption span {font-size:10px;color:#64776a;}
.lbcc .bcc-filter-fields {display:flex;align-items:flex-end;gap:7px;flex-wrap:wrap;}
.lbcc .bcc-filter-fields label {display:block;font-size:10px;font-weight:650;color:#64776a;margin-bottom:3px;}
.lbcc .bcc-filter-fields input {height:32px;width:145px;border:1px solid #cedbd0;border-radius:6px;padding:5px 8px;background:#fff;color:#234533;font-size:12px;font-weight:600;font-family:inherit;}
.lbcc .bcc-filter-fields .wbtn {height:32px;font-size:11px;padding:5px 13px;border-radius:6px;}
.lbcc .bcc-primary {background:#226b4b;color:#fff;border-color:#226b4b;}
.lbcc .gr-presets {gap:4px;margin:0;padding:0;border:0;}
.lbcc .gr-chip {padding:6px 9px;border:1px solid #d2ddd4;font-size:10px;border-radius:6px;}
.lbcc .bcc-wk-filter {display:flex;align-items:center;gap:12px;flex-wrap:wrap;padding:8px 10px;margin-bottom:8px;border:1px solid #e0e8e2;background:#f6f8f7;border-radius:7px;}
.lbcc .bcc-filter-note {font-size:10px;color:#697d70;}
.lbcc .wk-next {letter-spacing:0;font-size:10px;}
.lbcc .wk-datebar {margin:8px 0 4px;padding:6px 9px;font-size:11px;border-left-width:3px;}
.lbcc .wk-table {table-layout:auto;min-width:1080px;font-size:11px;}
.lbcc .wk-table th {padding:8px;text-transform:none;font-size:10px;background:#eff4f8;color:#476079;}
.lbcc .wk-table td {padding:8px;}
.lbcc .wk-table td small {font-size:10px;}
.lbcc .wk-table th:nth-child(1),.lbcc .wk-table td:nth-child(1) {min-width:165px;max-width:220px;overflow-wrap:anywhere;}
.lbcc .wk-table th:nth-child(2) {width:75px;}
.lbcc .wk-table th:nth-child(3) {width:120px;}
.lbcc .wk-table th:nth-child(4) {width:90px;}
.lbcc .wk-table th:nth-child(5) {width:110px;}
.lbcc .wk-table td:nth-child(6),.lbcc .wk-table td:nth-child(7) {min-width:150px;max-width:230px;overflow-wrap:anywhere;}
.lbcc .wk-table th:nth-child(8) {width:150px;}
.lbcc .wk-table th:nth-child(9) {width:108px;}
.lbcc .wk-status,.lbcc .wk-cat {font-size:10px;padding:4px 8px;}
.lbcc .wk-table tr.wk-booked td {background:#f4faf5;}
.lbcc .wk-table tr.wk-not-booked td {background:#fff7f7;}
.lbcc .wk-table tr.wk-pending td {background:#fafbfc;}
.lbcc .wk-table tbody tr:hover td {filter:brightness(.98);}
.lbcc .att-scroll,.lbcc .lscc-rp-tablewrap {border:1px solid #dbe5df;border-radius:8px;overflow:auto;scrollbar-width:thin;}
.lbcc table.att {width:max-content;min-width:100%;table-layout:auto;background:#fff;font-size:11px;}
.lbcc table.att th,.lbcc table.att td {padding:8px 10px;min-width:125px;border-color:#e1e9e4;}
.lbcc table.att .rowlab {min-width:125px;background:#e8f0eb;color:#3e5b49;}
.lbcc table.att .enm {font-size:11px;margin-top:3px;}
.lbcc table.att .edg {font-size:9px;white-space:normal;max-width:175px;}
.lbcc [data-bcc-status="present"] {background:#e9f7ef!important;color:#176344!important;}
.lbcc [data-bcc-status="late"],.lbcc [data-bcc-status="partial"] {background:#fff3d6!important;color:#8a5a00!important;}
.lbcc [data-bcc-status="absent"] {background:#fdecee!important;color:#ab3045!important;}
.lbcc [data-bcc-status="leave"] {background:#eaf2fe!important;color:#235e9e!important;}
.lbcc [data-bcc-status="off"] {background:#edf1f4!important;color:#53636f!important;}
.lbcc [data-bcc-status="training"] {background:#f2eafa!important;color:#73509c!important;}
.lbcc [data-bcc-status="neutral"] {background:#f5f7f6!important;color:#6b7b71!important;}
.lbcc table.att th[data-bcc-status] {background:#fafcfb!important;color:#233e2e!important;border-top:3px solid #cddbd2;}
.lbcc table.att th[data-bcc-status="present"] {border-top-color:#2b9669;}
.lbcc table.att th[data-bcc-status="absent"] {border-top-color:#d65e71;}
.lbcc table.att th[data-bcc-status="late"],.lbcc table.att th[data-bcc-status="partial"] {border-top-color:#d9a231;}
.lbcc table.att th[data-bcc-status="leave"] {border-top-color:#548bc7;}
.lbcc table.att th[data-bcc-status="training"] {border-top-color:#9470bc;}
.lbcc .lscc-roster-root {margin:0;padding:0;border:0;}
.lbcc .lscc-rp-page-title {display:none;}
.lbcc .bcc-roster-nav {display:flex;gap:6px;flex-wrap:wrap;margin-bottom:10px;}
.lbcc .bcc-roster-nav button {border-color:#d8e3db;color:#2a684b;background:#f3f8f4;}
.lbcc .bcc-roster-nav button:nth-child(2) {background:#edf4fc;border-color:#d7e4f2;color:#356b9b;}
.lbcc .bcc-panel-stack[data-bcc-stack="roster"] {gap:10px;}
.lbcc .bcc-panel-stack[data-bcc-stack="roster"] .bcc-panel {box-shadow:none;border-radius:9px;}
.lbcc .bcc-panel-stack[data-bcc-stack="roster"] .bcc-panel-head {padding:8px 12px;}
.lbcc .bcc-panel-stack[data-bcc-stack="roster"] h2 {font-size:14px;}
.lbcc .lscc-rp-status-section {margin:0;}
.lbcc .lscc-rp-status-title {display:none;}
