    flex-wrap: wrap;
    margin: 8px 0 12px;
}

.lscc-year-btn {
    padding: 4px 12px;
    border: 1px solid var(--line);
    border-radius: 4px;
    background: #fff;
    font-size: 0.8rem;
    cursor: pointer;
}

.lscc-year-btn:hover:not(:disabled) {
    background: var(--g100);
}
.lscc-year-btn:disabled {
    opacity: 0.4;
    cursor: not-allowed;
}

.lscc-year-label {
    font-weight: 700;
    font-size: 0.9rem;
    color: var(--g800);
    min-width: 60px;
    text-align: center;
}

.lscc-month-btns {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
}

.lscc-month-btns button {
    padding: 4px 10px;
    border: 1px solid var(--line);
    border-radius: 4px;
    background: #fff;
    font-size: 0.7rem;
    cursor: pointer;
    transition: all 0.2s;
}

.lscc-month-btns button:hover:not(:disabled) {
    background: var(--g100);
}

.lscc-month-btns button.active {
    background: var(--g600);
    color: #fff;
    border-color: var(--g600);
}

.lscc-month-btns button:disabled {
    opacity: 0.4;
    cursor: not-allowed;
}

.lscc-monthly-info {
    font-size: 0.75rem;
    color: var(--mut);
    margin: 6px 0 12px;
    padding: 8px 12px;
    background: var(--g50);
    border-radius: 6px;
}

.lscc-monthly-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.75rem;
}

.lscc-monthly-table th {
    background: var(--g50);
    border: 1px solid var(--line);
    padding: 8px 6px;
    text-align: center;
    font-weight: 700;
    color: var(--g800);
}

.lscc-monthly-table td {
    border: 1px solid var(--line);
    padding: 6px;
    text-align: center;
}

.lscc-m-empcol {
    min-width: 180px;
    text-align: left;
}

.lscc-m-empcell {
    text-align: left;
}

.lscc-m-val-zero { color: var(--mut); }
.lscc-m-val-green { color: #2E7D32; font-weight: 700; }
.lscc-m-val-yellow { color: #E65100; font-weight: 700; }
.lscc-m-val-red { color: #C62828; font-weight: 700; }
.lscc-m-val-blue { color: #1565C0; font-weight: 700; }
.lscc-m-val-gray { color: #9E9E9E; font-weight: 700; }
.lscc-m-val-orange { color: #E65100; font-weight: 700; }

