/* ============================================================
   v16 ADDITIONS — native date range bar + roster branch tag
   ============================================================ */

/* --- Global date range bar (injected by injectGlobalRangeUI) --- */
.lbcc #globalRangeCard input[type="date"] {
    font-family: inherit;
    color: #1B5E20;
    cursor: pointer;
    line-height: 1.2;
    min-height: 32px;
    -webkit-appearance: none;
    appearance: none;
}

.lbcc #globalRangeCard input[type="date"]:focus {
    outline: none;
    border-color: #2E7D32;
    box-shadow: 0 0 0 3px rgba(46, 125, 50, 0.15);
}

/* Make the native calendar icon green and obviously clickable */
.lbcc #globalRangeCard input[type="date"]::-webkit-calendar-picker-indicator {
    cursor: pointer;
    opacity: 0.65;
    padding: 2px;
    filter: invert(28%) sepia(52%) saturate(668%) hue-rotate(73deg) brightness(93%) contrast(89%);
}

.lbcc #globalRangeCard input[type="date"]::-webkit-calendar-picker-indicator:hover {
    opacity: 1;
}

/* Firefox / Safari fallback so the box does not collapse */
.lbcc #globalRangeCard input[type="date"]::-webkit-datetime-edit {
    padding: 0;
}

.lbcc #globalRangeCard .wbtn:hover {
    filter: brightness(1.08);
}

.lbcc #globalRangeCard .wbtn:active {
    transform: translateY(1px);
}

/* --- Roster branch tag (replaces the now-hidden duplicate dropdown) --- */
.lscc-rp-branch-tag {
    display: inline-block;
    padding: 6px 12px;
    border: 1px solid var(--line);
    border-radius: 6px;
    background: #F1F8E9;
    color: #1B5E20;
    font-size: 0.85rem;
    font-weight: 700;
    white-space: nowrap;
}

.lscc-rp-branch-tag:empty {
    display: none;
}

/* --- Source Wise / CC Leads drawer tables --- */
.lbcc .mx .tbl td.a,
.lbcc .tbl td.a {
    color: #E65100;
}

/* Keep the wider GST tables readable inside the drawer */
.lbcc #mBody .tbl th,
.lbcc #mBody .tbl td {
    white-space: nowrap;
}

@media (max-width: 900px) {
    .lbcc #globalRangeCard input[type="date"] {
        width: 100% !important;
    }
    .lbcc #globalRangeCard > div {
        gap: 8px;
    }
}

/* --- v16: walk-in recorded reason --- */
.lbcc .wkreason {
    flex-basis: 100%;
    margin-top: 5px;
    padding: 3px 8px;
    border-left: 3px solid #E74C3C;
    border-radius: 4px;
    background: #FDECEA;
    color: #C0392B;
    font-size: 11px;
    font-weight: 600;
    line-height: 1.4;
    max-width: 240px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

/* ============================================================
   v16 — portal-safe reason modal (no frappe.ui.Dialog dependency)
   ============================================================ */
.lbcc-reason-overlay {
    position: fixed;
    inset: 0;
    z-index: 99999;
    background: rgba(12, 32, 16, 0.55);
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 20px;
    animation: lbccReasonFade 0.14s ease-out;
}

@keyframes lbccReasonFade {
    from { opacity: 0; }
    to   { opacity: 1; }
}

.lbcc-reason-box {
    width: 100%;
    max-width: 460px;
    background: #fff;
    border-radius: 14px;
    box-shadow: 0 18px 50px rgba(0, 0, 0, 0.3);
    overflow: hidden;
    font-family: inherit;
    animation: lbccReasonPop 0.16s ease-out;
}

@keyframes lbccReasonPop {
    from { transform: translateY(10px) scale(0.98); opacity: 0; }
    to   { transform: none; opacity: 1; }
}

.lbcc-reason-hd {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    padding: 14px 18px;
    background: linear-gradient(135deg, #2E7D32 0%, #1B5E20 100%);
    color: #fff;
    font-size: 14px;
    font-weight: 700;
}

.lbcc-reason-x {
    background: rgba(255, 255, 255, 0.18);
    border: none;
    color: #fff;
    width: 26px;
    height: 26px;
    border-radius: 6px;
    cursor: pointer;
    font-size: 13px;
    line-height: 1;
    flex-shrink: 0;
}

.lbcc-reason-x:hover { background: rgba(255, 255, 255, 0.32); }

.lbcc-reason-bd { padding: 16px 18px 6px; }

.lbcc-reason-bd label {
    display: block;
    font-size: 12px;
    font-weight: 700;
    color: #33475B;
    margin-bottom: 6px;
}

.lbcc-reason-bd textarea {
    width: 100%;
    padding: 9px 11px;
    border: 2px solid #c8d6c8;
    border-radius: 8px;
    font-size: 13px;
    font-family: inherit;
    color: #1a1a1a;
    resize: vertical;
    min-height: 74px;
    background: #fff;
}

.lbcc-reason-bd textarea:focus {
    outline: none;
    border-color: #2E7D32;
    box-shadow: 0 0 0 3px rgba(46, 125, 50, 0.15);
}

.lbcc-reason-err {
    min-height: 16px;
    margin-top: 5px;
    font-size: 11.5px;
    font-weight: 700;
    color: #C62828;
}

.lbcc-reason-hint {
    font-size: 11px;
    color: #5F6F63;
    line-height: 1.45;
    margin-bottom: 4px;
}

.lbcc-reason-ft {
    display: flex;
    justify-content: flex-end;
    gap: 8px;
    padding: 12px 18px 16px;
}

.lbcc-reason-btn {
    padding: 8px 18px;
    border-radius: 7px;
    border: 1px solid #d6e0d6;
    background: #fff;
    color: #33475B;
    font-size: 12.5px;
    font-weight: 700;
    cursor: pointer;
    font-family: inherit;
}

.lbcc-reason-btn:hover { background: #f2f7f2; }

.lbcc-reason-btn.primary {
    background: #2E7D32;
    border-color: #2E7D32;
    color: #fff;
}

.lbcc-reason-btn.primary:hover { background: #256b28; }

@media (max-width: 520px) {
    .lbcc-reason-box { max-width: 100%; }
}

/* --- v16: walk-in date grouping (range view) --- */
.lbcc .wkdate {
