}

/* ============================================================
   v16 — Daily target tracker (deficit method)
   ============================================================ */
.lbcc .tgt-mini {
    margin-top: 6px;
    display: inline-block;
    padding: 2px 9px;
    border-radius: 10px;
    font-size: 10px;
    font-weight: 800;
    letter-spacing: 0.03em;
}
.lbcc .tgt-mini.ok   { background: #E8F5E9; color: #1B5E20; }
.lbcc .tgt-mini.warn { background: #FDECEA; color: #C62828; }

.lbcc .tgt-need {
    padding: 16px 18px;
    border-radius: 12px;
    margin-bottom: 14px;
    border-left: 5px solid #C62828;
    background: linear-gradient(135deg, #FFF5F5 0%, #FDECEA 100%);
}
.lbcc .tgt-need.ok {
    border-left-color: #2E7D32;
    background: linear-gradient(135deg, #F4FBF5 0%, #E8F5E9 100%);
}
.lbcc .tgt-need-l {
    font-size: 11px;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: #5F6F63;
}
.lbcc .tgt-need-v {
    font-size: 34px;
    font-weight: 800;
    line-height: 1.15;
    margin: 4px 0 2px;
    color: #C62828;
}
.lbcc .tgt-need.ok .tgt-need-v { color: #1B5E20; }
.lbcc .tgt-need-v span {
    font-size: 15px;
    font-weight: 700;
    color: #5F6F63;
    margin-left: 4px;
}
.lbcc .tgt-need-s { font-size: 12px; color: #5F6F63; }

.lbcc .tgt-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
    gap: 8px;
}
.lbcc .tgt-cell {
    padding: 9px 12px;
    border: 1px solid #E3EEE5;
    border-radius: 8px;
    background: #FAFCFA;
}
.lbcc .tgt-cell span {
    display: block;
    font-size: 10px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.04em;
    color: #7A8B7E;
    margin-bottom: 3px;
}
.lbcc .tgt-cell b { font-size: 14px; font-weight: 800; color: #1B5E20; }
.lbcc .tgt-cell b.r { color: #C62828; }

/* Day-by-day bar strip */
.lbcc .tgt-strip {
    display: flex;
    align-items: flex-end;
    gap: 3px;
    overflow-x: auto;
    padding: 6px 2px 0;
}
.lbcc .tgt-bar {
    flex: 1 0 22px;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 3px;
}
.lbcc .tgt-bar-wrap {
    position: relative;
    width: 100%;
    height: 96px;
    background: #F1F6F2;
    border-radius: 4px;
    overflow: hidden;
}
.lbcc .tgt-bar-wrap i {
    position: absolute;
    left: 0;
    bottom: 0;
    width: 100%;
    display: block;
    border-radius: 4px 4px 0 0;
}
.lbcc .tgt-bar-wrap i.ok { background: linear-gradient(180deg, #43A047, #1B5E20); }
.lbcc .tgt-bar-wrap i.no { background: linear-gradient(180deg, #EF9A9A, #C62828); }
.lbcc .tgt-bar-wrap u {
    position: absolute;
    left: 0;
    width: 100%;
    height: 0;
    border-top: 2px dashed #33475B;
    opacity: 0.55;
}
.lbcc .tgt-bar span {
    font-size: 9px;
    font-weight: 700;
    color: #7A8B7E;
}

.lbcc .tgt-legend {
    display: flex;
    gap: 14px;
    margin-top: 10px;
    font-size: 11px;
    font-weight: 600;
    color: #5F6F63;
}
.lbcc .tgt-legend span { display: flex; align-items: center; gap: 5px; }
.lbcc .tgt-legend i.sw {
    width: 11px;
    height: 11px;
    border-radius: 3px;
    display: inline-block;
}
.lbcc .tgt-legend i.sw.ok { background: #2E7D32; }
.lbcc .tgt-legend i.sw.no { background: #C62828; }
.lbcc .tgt-legend i.sw.line {
    height: 0;
    border-top: 2px dashed #33475B;
    border-radius: 0;
    width: 16px;
}

.lbcc .tgt-tbl tr.tgt-hit  td { background: #F6FBF7; }
.lbcc .tgt-tbl tr.tgt-miss td { background: #FFFAFA; }

/* --- v16: walk-in "updated by" badge --- */
.lbcc .wkupd {
    flex-basis: 100%;
    margin-top: 4px;
    font-size: 10.5px;
    font-weight: 700;
    color: #1B5E20;
    background: #E8F5E9;
    border-radius: 4px;
    padding: 2px 8px;
    display: inline-block;
    max-width: 240px;
