.lbcc-reason-bd select {
    width: 100%;
    padding: 9px 11px;
    border: 2px solid #c8d6c8;
    border-radius: 8px;
    font-size: 13px;
    font-family: inherit;
    color: #1a1a1a;
    background: #fff;
    margin-bottom: 12px;
    cursor: pointer;
}

.lbcc-reason-bd select:focus {
    outline: none;
    border-color: #2E7D32;
    box-shadow: 0 0 0 3px rgba(46, 125, 50, 0.15);
}

/* --- v17: interim "Visited" status button + amber pending pill --- */
.lbcc .wbtn.i {
    background: #FFF8E1;
    border-color: #FFB300;
    color: #E65100;
    font-weight: 800;
}
.lbcc .wbtn.i:hover { background: #FFECB3; }

.lbcc .wbtn.u {
    background: #F5F5F5;
    border-color: #BDBDBD;
    color: #555;
}
.lbcc .wbtn.u:hover { background: #EEEEEE; }

/* ============================================================
   v17 — Quick date preset chips
   ============================================================ */
.lbcc .gr-presets {
    display: flex;
    align-items: center;
    gap: 6px;
    flex-wrap: wrap;
    margin-top: 10px;
    padding-top: 10px;
    border-top: 1px dashed #c8d6c8;
}

.lbcc .gr-presets-l {
    font-size: 10px;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: #7A8B7E;
    margin-right: 2px;
}

.lbcc .gr-chip {
    padding: 5px 13px;
    border: 1.5px solid #c8d6c8;
    border-radius: 14px;
    background: #fff;
    color: #33475B;
    font-size: 11.5px;
    font-weight: 700;
    font-family: inherit;
    cursor: pointer;
    white-space: nowrap;
    transition: background 0.15s, border-color 0.15s, color 0.15s;
