.lbcc .gr-chip:hover {
    background: #F1F8E9;
    border-color: #2E7D32;
    color: #1B5E20;
}

.lbcc .gr-chip:active { transform: translateY(1px); }

.lbcc .gr-chip.on {
    background: #2E7D32;
    border-color: #2E7D32;
    color: #fff;
    box-shadow: 0 2px 6px rgba(46, 125, 50, 0.28);
}

.lbcc .gr-chip.on:hover { background: #256b28; }

@media (max-width: 640px) {
    .lbcc .gr-presets { gap: 5px; }
    .lbcc .gr-chip { padding: 5px 10px; font-size: 11px; }
    .lbcc .gr-presets-l { width: 100%; margin-bottom: 2px; }
}

