/* ==========================================================================
   LIFE STAFF ATTENDANCE EDGE PANEL  v4  -  ONE BLOCK, BOTH PAGES
   Paste this SAME block at the end of the Style / CSS field of BOTH:
     /app/web-page/life-coo-dashboard
     /app/web-page/branch-command-center
   On the branch page it also hides the old attendance drawer it replaces.
   REPLACES v3: delete the whole v3 CSS block first, then paste this.
   ========================================================================== */

/* the branch page's previous attendance drawer is replaced by this panel */
#bcc3-att-drawer,#bcc3-att-backdrop{display:none!important}

#att4{--ink:#16332600;--ink:#163326;--ink2:#3c5a49;--ink3:#5b7566;--cream:#fbf9f1;--card:#fffefa;
  --gold:#b9964a;--gold2:#e0cb98;--hair:#e2d7ba;--forest:#0f3326;--forest2:#215139;
  --on:#1f7042;--out:#4d7f63;--miss:#96670c;--abs:#9e3b2b;--leave:#39539a;--wo:#8a6410;
  --w:336px;
  position:fixed;inset:0;z-index:1200;display:none;font:12px/1.4 Inter,system-ui,sans-serif;color:var(--ink);
  -webkit-font-smoothing:antialiased}
#att4.open{display:block}
#att4.wide{--w:660px}
#att4 *{box-sizing:border-box}
#att4 button{font:inherit;cursor:pointer}
#att4 .a-scrim{position:absolute;inset:0;background:#0d2a1f4d}
#att4 .a-drawer{position:absolute;top:0;right:0;height:100%;width:min(var(--w),97vw);display:flex;flex-direction:column;
  background:var(--cream);border-left:1px solid var(--gold);box-shadow:-18px 0 60px #08231a4d;
  transition:width .18s ease;animation:aIn4 .2s ease-out}
@keyframes aIn4{from{transform:translateX(100%)}to{transform:translateX(0)}}

/* header ---------------------------------------------------------------------- */
#att4 .a-head{display:flex;align-items:center;gap:5px;padding:9px 10px;color:#fdf6e2;
  background:linear-gradient(112deg,var(--forest),var(--forest2));border-bottom:1px solid var(--gold)}
#att4 .a-mark{font-size:8px;font-weight:800;letter-spacing:2px;color:#f2e1ad;border:1px solid #c2a25988;border-radius:4px;padding:4px 5px;flex-shrink:0}
#att4 .a-title{margin-right:auto;min-width:0}
#att4 .a-title b{display:block;font-size:13px;font-weight:600;color:#fff8e6;white-space:nowrap}
#att4 .a-title small{display:block;font-size:10px;color:#d3e4d8;margin-top:1px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#att4 .a-head button{width:23px;height:23px;display:grid;place-content:center;border:1px solid #c2a25977;background:#ffffff1a;
  color:#f7ead0;border-radius:5px;font-size:11px;line-height:1;padding:0;flex-shrink:0}
#att4 .a-head button:hover{background:#ffffff2e;border-color:var(--gold2)}
#att4.wide [data-a-wide]{background:#c2a25945;border-color:var(--gold2)}

/* filters ---------------------------------------------------------------------- */
#att4 .a-bar{display:flex;align-items:center;gap:5px;padding:7px 9px;background:#fffdf6;border-bottom:1px solid var(--hair)}
#att4 .a-bar input,#att4 .a-bar select{font:inherit;font-size:11.5px;border:1px solid var(--hair);background:#fff;border-radius:5px;
  padding:4px 6px;color:var(--ink);min-width:0;height:27px}
#att4 .a-bar input[type=date]{width:120px;flex-shrink:0}
#att4 .a-bar select{max-width:120px}
#att4 #a-q{flex:1;min-width:60px}
#att4 .a-lock{font-size:11px;font-weight:700;color:#5c4d1f;background:#fdf6e4;border:1px solid var(--gold2);
  border-radius:5px;padding:5px 9px;white-space:nowrap;max-width:150px;overflow:hidden;text-overflow:ellipsis}
#att4 .a-bar input:focus,#att4 .a-bar select:focus{outline:none;border-color:var(--gold);box-shadow:0 0 0 2px #b9964a2e}
#att4 .a-chips,#att4 .a-subs{display:flex;flex-wrap:wrap;gap:3px;padding:6px 9px;background:#fffdf6;border-bottom:1px solid var(--hair)}
#att4 .a-subs{background:#fcf5e3}
#att4 .a-chip,#att4 .a-sub{font-size:10.5px;font-weight:600;border:1px solid var(--hair);background:#fff;color:var(--ink2);
  border-radius:14px;padding:3px 9px;white-space:nowrap}
#att4 .a-chip:hover,#att4 .a-sub:hover{border-color:var(--gold);color:var(--ink)}
#att4 .a-chip.on,#att4 .a-sub.on{background:var(--forest);border-color:var(--gold);color:#fff3d6}
#att4 .a-chip.c-ON_FLOOR{color:var(--on)}#att4 .a-chip.c-OUT_MISSING{color:var(--miss)}
#att4 .a-chip.c-ABSENT{color:var(--abs)}#att4 .a-chip.c-LEAVE{color:var(--leave)}
#att4 .a-chip.c-WEEK_OFF{color:var(--wo)}#att4 .a-chip.c-FLAG{color:var(--miss);border-color:var(--gold2)}
#att4 .a-chip.on[class*="c-"]{color:#fff3d6}
#att4 .a-sub{border-color:var(--gold2);color:#7a5a10}

/* rows -------------------------------------------------------------------------- */
#att4 .a-body{flex:1;overflow:auto;padding:7px 9px;display:flex;flex-direction:column;gap:4px;scrollbar-width:thin}
#att4 .a-pr{display:none}
#att4 .a-row{position:relative;display:flex;align-items:center;gap:8px;width:100%;text-align:left;padding:7px 9px 7px 11px;
  background:var(--card);border:1px solid var(--hair);border-radius:8px}
#att4 .a-row::before{content:"";position:absolute;left:0;top:7px;bottom:7px;width:2.5px;border-radius:0 3px 3px 0;background:var(--ink3)}
#att4 .a-row:hover{border-color:var(--gold);box-shadow:0 3px 12px #1633260f}

#att4 .a-av{position:relative;flex-shrink:0;width:32px;height:32px;border-radius:50%;background:linear-gradient(145deg,#f6f1e0,#e6dcc0);
  border:1.5px solid var(--gold);box-shadow:0 0 0 1px #fff inset;display:grid;place-content:center}
#att4 .a-av::after{content:attr(data-ini);font-size:11px;font-weight:700;color:#725c22}
#att4 .a-av img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;border-radius:50%;background:#fff;z-index:1}
#att4 .a-av.g-m{border-color:#6f92bd}#att4 .a-av.g-m::after{color:#2f5f95}
#att4 .a-av.g-f{border-color:#cf95aa}#att4 .a-av.g-f::after{color:#a04568}
#att4 .a-sex{position:absolute;right:-3px;bottom:-3px;z-index:2;width:13px;height:13px;border-radius:50%;background:#fff;
  border:1px solid var(--hair);font-size:8px;line-height:11px;text-align:center;text-decoration:none;color:var(--ink2)}
#att4 .a-av.g-m .a-sex{color:#2f5f95;border-color:#b0c6de}
#att4 .a-av.g-f .a-sex{color:#a04568;border-color:#e0b8c6}

#att4 .a-id{flex:1;min-width:0;display:flex;flex-direction:column;gap:0}
#att4 .a-id b{display:flex;align-items:center;gap:4px;font-size:12px;font-weight:600;color:var(--ink);line-height:1.35;min-width:0}
#att4 .a-id b>:first-child{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
#att4 .a-id small{font-size:10.5px;color:var(--ink2);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;line-height:1.35}
#att4 .a-ja{color:var(--ink3)!important;font-weight:500}
#att4 .a-bg{font-style:normal;flex-shrink:0;font-size:8.5px;font-weight:800;letter-spacing:.4px;padding:1px 5px;border-radius:4px;border:1px solid}
#att4 .a-bg.b-x{color:#5d4407;background:#fbeec6;border-color:#d8bd6e}
#att4 .a-bg.b-a{color:#1f5c3c;background:#dff0e3;border-color:#a9cdb4}
#att4 .a-bg.b-b{color:#2f5f95;background:#e4edf9;border-color:#adc6e2}
#att4 .a-bg.b-h{color:#6a4088;background:#efe6f6;border-color:#cdb8dd}
#att4 .a-ph{font-style:normal;flex-shrink:0;font-size:10px;color:#2f5f95;cursor:help}
#att4 .a-ph2{color:var(--ink2)!important;font-weight:600;margin-top:3px}
#att4 .a-mtd{display:flex;flex-wrap:wrap;align-items:center;gap:2px;margin-top:2px}
#att4 .a-mtd u{text-decoration:none;font-size:9px;color:var(--ink3);font-weight:600;margin-right:1px}
#att4 .a-mtd i{font-style:normal;font-size:9.5px;font-weight:800;padding:1px 5px;border-radius:8px;border:1px solid}
#att4 .a-mtd i.p{color:var(--on);background:#e2f1e5;border-color:#b6d6bf}
#att4 .a-mtd i.a{color:var(--abs);background:#fae7e3;border-color:#e5bcb2}
#att4 .a-mtd i.w{color:var(--wo);background:#faefd9;border-color:#e0cb98}
#att4 .a-mtd i.l{color:var(--leave);background:#e8edfa;border-color:#bccae8}
#att4 .a-mtd i.e{color:#6b5a26;background:#fcf6e6;border-color:var(--gold2)}
#att4 .a-mtd i.sk{width:70px;height:11px;border:0;border-radius:6px;background:linear-gradient(90deg,#ece7d6,#f8f6ec,#ece7d6);
  background-size:200% 100%;animation:aSk4 1.1s linear infinite}

#att4 .a-when{flex-shrink:0;text-align:right;display:flex;flex-direction:column;gap:0;align-items:flex-end;max-width:46%}
#att4 .a-t{font-size:13px;font-weight:700;color:var(--ink);font-variant-numeric:tabular-nums;white-space:nowrap}
#att4 .a-t i{font-style:normal;color:var(--gold);margin:0 2px;font-size:10px}
#att4 .a-t em{font-style:normal;color:var(--ink3);letter-spacing:.5px}
#att4 .a-st{font-size:9px;font-weight:800;letter-spacing:.5px;text-transform:uppercase;color:var(--ink2);white-space:nowrap}
#att4 .a-st u{text-decoration:none;font-weight:600;letter-spacing:0;text-transform:none;color:var(--ink3)}
#att4 .a-hr{font-size:9.5px;color:var(--ink2);font-variant-numeric:tabular-nums;white-space:nowrap}
#att4 .a-fl{font-size:9px;font-weight:800;color:var(--miss);white-space:nowrap}
#att4 .a-tick{position:absolute;top:4px;right:6px;font-size:10px;font-weight:700;color:var(--on)}

/* status colour codes ----------------------------------------------------------- */
#att4 .s-on{background:linear-gradient(100deg,#e9f5eb,#fffefa 62%)}
#att4 .s-on::before{background:var(--on)}#att4 .s-on .a-st{color:var(--on)}
#att4 .s-out{background:#fbfdfa}
#att4 .s-out::before{background:var(--out)}#att4 .s-out .a-st{color:var(--out)}
#att4 .s-miss{background:linear-gradient(100deg,#fcf3dd,#fffefa 62%)}
#att4 .s-miss::before{background:var(--miss)}#att4 .s-miss .a-st{color:var(--miss)}
#att4 .s-abs{background:linear-gradient(100deg,#fae9e5,#fffefa 62%)}
#att4 .s-abs::before{background:var(--abs)}
#att4 .s-abs .a-st,#att4 .s-abs .a-id b{color:var(--abs)}
#att4 .s-leave{background:linear-gradient(100deg,#eaeffa,#fffefa 62%)}
#att4 .s-leave::before{background:var(--leave)}#att4 .s-leave .a-st{color:var(--leave)}
#att4 .s-wo{background:linear-gradient(100deg,#faf1de,#fffefa 62%)}
#att4 .s-wo::before{background:var(--wo)}#att4 .s-wo .a-st{color:var(--wo)}

/* skeleton / notes -------------------------------------------------------------- */
#att4 .a-sk{display:flex;flex-direction:column;gap:4px}
#att4 .a-sk i{height:54px;border-radius:8px;border:1px solid var(--hair);
  background:linear-gradient(90deg,#f5f1e3,#fdfbf3,#f5f1e3);background-size:200% 100%;animation:aSk4 1.1s linear infinite}
@keyframes aSk4{from{background-position:200% 0}to{background-position:-200% 0}}
#att4 .a-note{padding:16px;border-radius:8px;background:#fdfcf5;color:var(--ink2);font-size:11.5px;text-align:center}
#att4 .a-err{padding:12px;border-radius:8px;background:#fdf0ed;border:1px solid #e5bcb2;color:#8a3325;font-size:11.5px}
#att4 .a-err button{margin-top:7px;border:1px solid #e5bcb2;background:#fff;border-radius:5px;padding:4px 9px}

/* month view --------------------------------------------------------------------- */
#att4 .a-mo{display:flex;flex-direction:column;gap:9px}
#att4 .a-moh{display:flex;flex-direction:column;align-items:center;gap:1px;text-align:center;padding-bottom:9px;border-bottom:1px solid var(--hair)}
#att4 .a-moh>button:first-child{align-self:flex-start;font-size:10.5px;border:1px solid var(--hair);background:#fff;border-radius:5px;padding:3px 9px;color:var(--ink2)}
#att4 .a-av.big{width:58px;height:58px;border-width:2px;margin:6px 0 4px}
#att4 .a-av.big::after{font-size:19px}
#att4 .a-moh b{display:flex;align-items:center;gap:5px;font-size:14.5px;color:var(--ink)}
#att4 .a-moh small{font-size:10.5px;color:var(--ink2)}
#att4 .a-leave{margin-top:9px;font-size:11px;font-weight:700;border:1px solid var(--gold2);background:linear-gradient(120deg,#fffdf4,#f4ead2);
  color:#6b5a26;border-radius:16px;padding:5px 14px}
#att4 .a-leave:hover{border-color:var(--gold);color:var(--ink)}
#att4 .a-mnav{display:flex;align-items:center;justify-content:center;gap:12px}
#att4 .a-mnav span{font-size:12.5px;font-weight:700;color:var(--ink);min-width:125px;text-align:center}
#att4 .a-mnav button{width:24px;height:24px;border:1px solid var(--hair);background:#fff;border-radius:5px;color:var(--ink2);padding:0}
#att4 .a-grid{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:3px}
#att4 .a-dow{font-style:normal;font-size:9px;font-weight:700;text-align:center;color:var(--ink2);padding-bottom:2px}
#att4 .a-day{font-style:normal;display:flex;flex-direction:column;align-items:center;justify-content:center;
  min-height:38px;border:1px solid var(--hair);border-radius:6px;background:#fff}
#att4 .a-day b{font-size:12px;font-weight:700}
#att4 .a-day u{text-decoration:none;font-size:8.5px;font-weight:800}
#att4 .a-day.kP{background:#e2f1e5;border-color:#b6d6bf;color:var(--on)}
#att4 .a-day.kHD{background:#f0e8f7;border-color:#d3c0e2;color:#5e3679}
#att4 .a-day.kA{background:#fae7e3;border-color:#e5bcb2;color:var(--abs)}
#att4 .a-day.kWO{background:#faefd9;border-color:#e0cb98;color:var(--wo)}
#att4 .a-day.kL{background:#e8edfa;border-color:#bccae8;color:var(--leave)}
#att4 .a-day.kU{background:#faf9f2;color:#7c8c80}
#att4 .a-day.kF,#att4 .a-day.kN{background:#fdfdf9;border-style:dashed;color:#aab6ac}
#att4 .a-day.now{border-color:var(--gold);box-shadow:0 0 0 1.5px #b9964a66}
#att4 .a-tot{display:flex;flex-wrap:wrap;gap:4px}
#att4 .a-tot i{font-style:normal;font-size:11px;font-weight:800;padding:3px 9px;border-radius:12px;border:1px solid}
#att4 .a-tot i.p{color:var(--on);background:#e2f1e5;border-color:#b6d6bf}
#att4 .a-tot i.a{color:var(--abs);background:#fae7e3;border-color:#e5bcb2}
#att4 .a-tot i.w{color:var(--wo);background:#faefd9;border-color:#e0cb98}
#att4 .a-tot i.l{color:var(--leave);background:#e8edfa;border-color:#bccae8}
#att4 .a-tot i.e{color:#6b5a26;background:#fcf6e6;border-color:var(--gold2)}
#att4 .a-tot i.v{color:var(--ink);background:#fff;border-color:var(--gold)}
#att4 .a-leg{font-size:10px;color:var(--ink2);line-height:1.55}

/* footer -------------------------------------------------------------------------- */
#att4 .a-foot{border-top:1px solid var(--hair);background:#fffdf6;padding:6px 9px;display:flex;flex-direction:column;gap:2px;
  font-size:9.5px;color:var(--ink2);line-height:1.45}
#att4 .a-ok{color:var(--on);font-weight:800}
#att4 .a-warn{color:var(--miss);font-weight:800}

/* wide mode ----------------------------------------------------------------------- */
#att4.wide .a-row{padding:8px 11px 8px 13px;gap:10px}
#att4.wide .a-av{width:38px;height:38px}
#att4.wide .a-av::after{font-size:12.5px}
#att4.wide .a-id b{font-size:13px}
#att4.wide .a-id small,#att4.wide .a-mtd i{font-size:11px}
#att4.wide .a-t{font-size:14.5px}
#att4.wide .a-st,#att4.wide .a-hr,#att4.wide .a-fl{font-size:10px}
#att4.wide .a-day{min-height:44px}

@media(max-width:680px){#att4 .a-drawer{width:100vw;border-left:0}#att4 .a-bar{flex-wrap:wrap}}
@media(prefers-reduced-motion:reduce){#att4 .a-drawer,#att4 .a-sk i,#att4 .a-mtd i.sk{animation:none;transition:none}}

/* print: fills the sheet, two columns on wide paper, no wasted margin ------------- */
@page{size:auto;margin:8mm 7mm}
@media print{
  body.a-printing>*:not(#att4){display:none!important}
  body.a-printing #att4{position:static;display:block;font-size:8.5pt}
  body.a-printing #att4 .a-scrim,body.a-printing #att4 .a-head,body.a-printing #att4 .a-bar,
  body.a-printing #att4 .a-chips,body.a-printing #att4 .a-subs,body.a-printing #att4 .a-foot{display:none!important}
  body.a-printing #att4 .a-drawer{position:static;width:100%;height:auto;box-shadow:none;border:0;background:#fff;animation:none}
  body.a-printing #att4 .a-body{display:block;overflow:visible;height:auto;padding:0;
    column-count:2;column-gap:6mm;column-fill:balance}
  body.a-printing #att4 .a-pr{display:block;column-span:all;font-size:10pt;font-weight:800;color:#163326;
    border-bottom:1.2pt solid #b9964a;padding-bottom:2mm;margin-bottom:3mm}
  body.a-printing #att4 .a-row{break-inside:avoid;page-break-inside:avoid;display:flex;width:100%;margin:0 0 1.2mm;
    padding:1.4mm 2mm;border:.4pt solid #ccc;border-radius:1.5mm;background:#fff!important;box-shadow:none}
  body.a-printing #att4 .a-row::before{width:1.2mm;top:1mm;bottom:1mm}
  body.a-printing #att4 .a-av{width:7mm;height:7mm;border-width:.4pt}
  body.a-printing #att4 .a-av::after{font-size:6pt}
  body.a-printing #att4 .a-sex,body.a-printing #att4 .a-tick{display:none}
  body.a-printing #att4 .a-id b{font-size:8.5pt}
  body.a-printing #att4 .a-id small,body.a-printing #att4 .a-mtd i,body.a-printing #att4 .a-mtd u{font-size:6.5pt}
  body.a-printing #att4 .a-t{font-size:9pt}
  body.a-printing #att4 .a-st,body.a-printing #att4 .a-hr,body.a-printing #att4 .a-fl{font-size:6.5pt}
  body.a-printing #att4 .a-mo{column-span:all}
  body.a-printing #att4 .a-leave,body.a-printing #att4 .a-mnav button,
  body.a-printing #att4 .a-moh>button:first-child{display:none}
  body.a-printing #att4 *{-webkit-print-color-adjust:exact;print-color-adjust:exact}
}
/* ===================== END OF ATTENDANCE PANEL CSS v4 ===================== */


/* ===== LIFE BRANCH HOME UX + SALES SUMMARY v1 ===== */
#life-home-menu{position:relative;display:inline-flex;align-self:center;margin-right:14px;z-index:110}
.life-home-btn{height:42px;min-width:94px;padding:0 14px;display:flex;gap:8px;align-items:center;justify-content:center;border:1px solid rgba(231,199,112,.75);border-radius:12px;background:rgba(255,255,255,.1);color:#fff!important;font-size:13px;font-weight:900;letter-spacing:.08em;text-decoration:none!important;box-shadow:inset 0 0 0 1px rgba(255,255,255,.05);transition:.25s ease}
.life-home-btn:hover,.life-home-btn:focus{background:#fff8df;color:#123f2e!important;transform:translateY(-1px)}
.life-home-drop{position:absolute;left:0;top:calc(100% + 7px);width:220px;padding:8px;background:#fffdf5;border:1px solid #d9bd6f;border-radius:12px;box-shadow:0 16px 40px rgba(5,44,30,.24);opacity:0;visibility:hidden;transform:translateY(-7px);transition:.22s ease}
#life-home-menu:hover .life-home-drop,#life-home-menu:focus-within .life-home-drop{opacity:1;visibility:visible;transform:none}
.life-home-drop a{display:block;padding:9px 11px;border-radius:8px;color:#173e2e!important;font-size:13px;font-weight:750;text-decoration:none!important}.life-home-drop a:hover{background:#eaf5ec;color:#0d6a3d!important}
#life-branch-home-title{position:relative;color:#fff!important;letter-spacing:.018em;overflow:hidden}
#life-branch-home-title:after{content:'';position:absolute;inset:-25% auto -25% -35%;width:22%;background:linear-gradient(100deg,transparent,rgba(255,255,255,.68),transparent);transform:skewX(-18deg);animation:lifeTitleShine 30s ease-in-out infinite;pointer-events:none}
@keyframes lifeTitleShine{0%,88%{left:-35%;opacity:0}90%{opacity:1}98%{left:120%;opacity:.9}100%{left:120%;opacity:0}}
.bcc-section-nav button,.bcc-nav button,[aria-label="Page sections"] button{border:1px solid rgba(222,190,105,.48)!important;border-radius:10px!important;box-shadow:inset 0 0 0 1px rgba(255,255,255,.025)!important;transition:background .2s ease,border-color .2s ease,transform .2s ease!important}
.bcc-section-nav button:hover,.bcc-nav button:hover,[aria-label="Page sections"] button:hover{border-color:#e5c46e!important;transform:translateY(-1px)}
.bcc-panel-head{cursor:pointer}.bcc-panel-head:hover{background-image:linear-gradient(90deg,rgba(231,199,112,.08),transparent 48%)}
#life-sales-summary{display:grid;grid-template-columns:minmax(260px,.8fr) minmax(620px,2.2fr);border:1px solid #d6c17e;border-radius:16px;background:linear-gradient(135deg,#fffdf7 0%,#f2f8ee 100%);box-shadow:0 9px 28px rgba(18,67,47,.08);overflow:hidden;margin:0 0 14px;color:#163d2d}
.life-sales-primary{display:grid;grid-template-columns:1fr 1fr;background:linear-gradient(145deg,#0b3c2b,#17613d);color:#fff}.life-sales-primary>div{padding:20px 18px;display:flex;flex-direction:column;justify-content:center;min-height:148px;border-right:1px solid rgba(229,197,108,.38)}
