(function () {
  var LOGIN = '/login?redirect-to=' + encodeURIComponent(location.pathname + location.search);
  var bounced = false, _fetch = window.fetch;
  function bounce(){ if(!bounced){ bounced = true; location.href = LOGIN; } }

  window.fetch = function () {
    return _fetch.apply(this, arguments).then(function (r) {
      if (r.status === 401 || r.status === 403) bounce();
      return r;
    });
  };
  if (window.jQuery) jQuery(document).ajaxError(function (e, xhr) {
    if (xhr.status === 401 || xhr.status === 403) bounce();
  });

  setInterval(function () {
    _fetch('/api/method/frappe.auth.get_logged_user', { credentials: 'same-origin' })
      .then(function (r) { if (r.status === 401 || r.status === 403) bounce(); })
      .catch(function () {});
  }, 5 * 60 * 1000);
})();



function maskMobile(value) {
    var original = String(value || "").trim();

    if (!original) {
        return "—";
    }

    var digits = original.replace(/\D/g, "");

    if (digits.length > 10) {
        digits = digits.slice(-10);
    }

    if (digits.length >= 7) {
        return (
            digits.slice(0, 3) +
            "*".repeat(Math.max(1, digits.length - 6)) +
            digits.slice(-3)
        );
    }

    if (digits.length > 4) {
        return (
            digits.slice(0, 2) +
            "*".repeat(digits.length - 4) +
            digits.slice(-2)
        );
    }

    return "*".repeat(digits.length);
}

