                  : n >= 1e5 ? "\u20B9"+(n/1e5).toFixed(2)+" L" : inr(n); };
// v17 FIX: quotes were NOT escaped, yet esc() is used inside HTML
// attributes (title="...", value="..."). A staff-typed remark containing a
// double quote broke the attribute, and a crafted one could inject an
// event handler. Now escapes " and ' as well.
const esc  = s => String(s==null?"":s).replace(/[<>&"']/g,c=>({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&#39;'}[c]));
// ---------------------------------------------------------------------
// Consultation Employee list — extra designations
// The server's emp_list (branch_command_center / cc_walkins_range) does
// not include DIETICIAN staff. Pull them separately and merge into
