// ---------------------------------------------------------------------
const WK_EXTRA_DESIGNATIONS = ["DIETICIAN"];
let _wkExtraEmpPromise = null;
let _wkExtraEmpBranch  = "";

function wkLoadExtraConsultEmployees(){
  if(!curBranch) return Promise.resolve([]);
  if(_wkExtraEmpPromise && _wkExtraEmpBranch === curBranch){
    return _wkExtraEmpPromise;
  }
  _wkExtraEmpBranch = curBranch;
  _wkExtraEmpPromise = frappe.call({
    method: "frappe.client.get_list",
    args: {
      doctype: "Employee",
      filters: [
        ["status", "=", "Active"],
        ["branch", "=", curBranch],
        ["designation", "in", WK_EXTRA_DESIGNATIONS]
      ],
      fields: ["name", "employee_name", "designation"],
      limit_page_length: 0,
      order_by: "employee_name asc"
    }
  }).then(function(r){
    return (r.message || []).map(function(e){
      return { id: e.name, n: e.employee_name || e.name, dg: e.designation || "" };
    });
  }).catch(function(e){
    ("Extra consultation employees lookup failed:", e, void 0);
    return [];
  });
  return _wkExtraEmpPromise;
}

function wkMergeExtraConsultEmployees(extras){
  if(!extras || !extras.length) return;
  if(!D) D = {};
  if(!Array.isArray(D.empList)) D.empList = [];
  var seen = {};
  D.empList.forEach(function(e){ if(e && e.id) seen[e.id] = 1; });
  extras.forEach(function(e){
    if(e && e.id && !seen[e.id]){ D.empList.push(e); seen[e.id] = 1; }
  });
}
