    '<text x="'+(x+bw/2)+'" y="'+(h-12)+'" text-anchor="middle" font-size="9.5" font-weight="600" fill="#5F6F63">'+esc(d.n)+'</text></g>';}).join("");
  return '<div class="mx-wrap"><svg width="'+w+'" height="'+h+'" viewBox="0 0 '+w+' '+h+'">'+g+bars+
