// Final walk-in status choices.
// "Cancelled" is intentionally NOT available anywhere in this page.
const WSTATES=[
  ["Visited","i"],
  ["Visited Booked","v"],
  ["Visited Not Booked","p"],
  ["Not Visited","n"]
];

// During the configurable correction window, already-updated rows can still
// be corrected to these states. After the window expires, strict forward-only
// mapping is applied by wkAllowedStatesFor().
const WSTATES_ALL=[
  ["Visited","i"],
  ["Visited Booked","v"],
  ["Visited Not Booked","p"],
  ["Not Visited","n"],
  ["Not Booked","u"],
  ["Booked","b"]
];

// ============================================================
// 1-HOUR CORRECTION WINDOW
// ============================================================
const WK_CORRECTION_MINUTES = 60;
const WK_CORRECTION_MS = WK_CORRECTION_MINUTES * 60 * 1000;

// Normal forward-only flow (always allowed).
const WK_NORMAL_NEXT = {
  "":                    ["Visited", "Not Visited"],
  "Booked":              ["Visited", "Not Visited"],
  "Not Booked":          ["Visited", "Not Visited"],
  "Not Visited":         ["Visited", "Visited Booked", "Visited Not Booked"],
  "Visited":             ["Visited Booked", "Visited Not Booked"],
  "Visited Not Booked":  ["Visited Booked"],
  "Visited Booked":      []
};

// Extra options available ONLY inside the 60-minute window.
const WK_CORRECTION_NEXT = {
  "Visited":             ["Not Visited"],
  "Visited Not Booked":  ["Visited", "Not Visited"],
  "Visited Booked":      ["Visited", "Visited Not Booked", "Not Visited"]
};

// Statuses that have already been touched; used when the anchor is missing.
const WK_UPDATED_STATUSES = ["Visited", "Visited Booked", "Visited Not Booked", "Not Visited"];

function wkParseDT(v){
  if(!v) return null;
  var s = String(v).trim().replace(" ", "T");
  var d = new Date(s);
  return isNaN(d.getTime()) ? null : d;
}

function wkAnchor(w){
  if(!w) return null;
  return wkParseDT(
    w.first_upd_on || w.first_status_updated_on || w.first_updated_on || ""
  );
}

function wkCorrectionOpen(w){
  var first = wkAnchor(w);
  // No anchor yet → first update has not happened → window is open.
  if(!first){
    if(w && WK_UPDATED_STATUSES.indexOf(w.st || "") !== -1) return false;
    return true;
  }
  return (Date.now() - first.getTime()) < WK_CORRECTION_MS;
}

function wkCorrectionWindowRemaining(w){
  var first = wkAnchor(w);
  if(!first) return null;
  return Math.max(0, WK_CORRECTION_MS - (Date.now() - first.getTime()));
}

function wkStatusWindowExpired(w){
  return !wkCorrectionOpen(w);
}

// ============================================================
// STATUS-TRANSITION POLICY
// ============================================================
//
// Inside the 1-hour window:
//   Pending / Booked / Not Booked  → Visited | Not Visited
//   Not Visited                    → Visited | Visited Booked | Visited Not Booked
//   Visited                        → Visited Booked | Visited Not Booked | Not Visited
//   Visited Not Booked             → Visited Booked | Visited | Not Visited
//   Visited Booked                 → Visited | Visited Not Booked | Not Visited
//
// After the window:
//   Pending / Booked / Not Booked  → Visited | Not Visited
//   Not Visited                    → Visited | Visited Booked | Visited Not Booked
//   Visited                        → Visited Booked | Visited Not Booked
//   Visited Not Booked             → Visited Booked
//   Visited Booked                 → LOCKED
//
// Cancelled is never allowed.
function wkAllowedStatesFor(w, states){
  states = states || WSTATES_ALL;

  var clean = states.filter(function(x){
    return x && x[0] && x[0] !== "Cancelled";
  });

  if(!w) return clean;

  var current = String(w.st || "");
  var open = wkCorrectionOpen(w);

  // Pending family — normal flow, same inside and outside window.
  if(current === "" || current === "Booked" || current === "Not Booked"){
    return clean.filter(function(x){
      return x[0] === "Visited" || x[0] === "Not Visited";
    });
  }

  // Not Visited — same three options always.
  if(current === "Not Visited"){
    return clean.filter(function(x){
      return x[0] === "Visited"
          || x[0] === "Visited Booked"
          || x[0] === "Visited Not Booked";
    });
  }

  // Visited — normal two options; add Not Visited during window.
  if(current === "Visited"){
    var list = ["Visited Booked", "Visited Not Booked"];
    if(open) list.push("Not Visited");
    return clean.filter(function(x){ return list.indexOf(x[0]) !== -1; });
  }

  // Visited Not Booked — normally only Visited Booked; full correction during window.
  if(current === "Visited Not Booked"){
    var list2 = ["Visited Booked"];
    if(open) list2 = list2.concat(["Visited", "Not Visited"]);
    return clean.filter(function(x){ return list2.indexOf(x[0]) !== -1; });
  }

  // Visited Booked — normally locked; fully correctable during window.
  if(current === "Visited Booked"){
    if(!open) return [];
    var list3 = ["Visited", "Visited Not Booked", "Not Visited"];
    return clean.filter(function(x){ return list3.indexOf(x[0]) !== -1; });
  }

  return [];
}

function wkCanChangeTo(w, newStatus){
  if(!newStatus || newStatus === "Cancelled") return false;
  return wkNextStatuses(w).indexOf(newStatus) > -1;
}

function wkLockedMessage(w){
  if(w && w.st === "Visited Booked" && wkStatusWindowExpired(w)){
    return "Visited Booked is locked. The "
      + WK_CORRECTION_MINUTES
      + "-minute correction window from the first status update has expired.";
  }
  return "This status change is no longer allowed.";
}

