function loadBranches(){
  return frappe.call({ method:"frappe.client.get_list",
    args:{ doctype:"Branch", fields:["name"], limit_page_length:0, order_by:"name" }})
    .then(r=>{
      BRANCHES = (r.message||[]).map(b=>b.name)
        .filter(n => n!=="Head Office" && n!=="Testing Branch").map(n=>[n,n]);
      if(!BRANCHES.length) throw new Error("No branches visible for your user permissions.");
      curBranch = BRANCHES[0][0];
      $("branchSel").innerHTML = BRANCHES.map(b=>'<option value="'+esc(b[0])+'">'+esc(b[1])+'</option>').join("");
      $("branchSel").value = curBranch;
    });
}

function getCycleDates(){
    const today = new Date();
    const d = today.getDate();
    const m = today.getMonth();
    const y = today.getFullYear();

    let cycleStart, cycleEnd;
    if(d >= 6){
        cycleStart = new Date(y, m, 6);
    } else {
        cycleStart = new Date(y, m-1, 6);
    }
    cycleEnd = new Date(cycleStart);
    cycleEnd.setMonth(cycleEnd.getMonth() + 1);
    cycleEnd.setDate(5);

    return { start: cycleStart, end: cycleEnd };
}

function formatDateDDMMYY(date){
    const dd = String(date.getDate()).padStart(2, '0');
    const mm = String(date.getMonth() + 1).padStart(2, '0');
    const yy = String(date.getFullYear()).slice(-2);
    return dd + '-' + mm + '-' + yy;
}

function isoToday(){
  var d = new Date();
  return d.getFullYear() + '-' + String(d.getMonth()+1).padStart(2,'0') + '-' + String(d.getDate()).padStart(2,'0');
}

function fmtDateShortDMY(v){
  if(!v) return "";
  var s = String(v).slice(0,10);
  var p = s.split("-");
  if(p.length !== 3) return s;

  var y = p[0];
  var m = parseInt(p[1],10);
  var d = p[2];

  var mons = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
  if(m < 1 || m > 12) return s;

  return d + "-" + mons[m-1] + "-" + y.slice(-2);
}
function isoOf(d){
  return d.getFullYear() + '-' + String(d.getMonth()+1).padStart(2,'0') + '-' + String(d.getDate()).padStart(2,'0');
}
// v16: default window = THIS MONTH's billing cycle (6th -> 5th), capped at
// today so the dashboard never opens showing future dates.
function defaultFrom(){
  return isoOf(getCycleDates().start);
}
function defaultTo(){
  return isoToday();
}
function winLabel(){
  if(!ACTIVE_FROM || !ACTIVE_TO) return "";
  if(ACTIVE_FROM === ACTIVE_TO) return frappe.datetime.str_to_user(ACTIVE_FROM);
  return frappe.datetime.str_to_user(ACTIVE_FROM)+" \u2192 "+frappe.datetime.str_to_user(ACTIVE_TO);
}
function parseDDMMYY(str) {
  const parts = str.split('-');
  if (parts.length === 3) {
    const d = parseInt(parts[0]);
    const m = parseInt(parts[1]);
    const y = parseInt(parts[2]);
    const year = y < 50 ? 2000 + y : 1900 + y;
    return year + '-' + String(m).padStart(2, '0') + '-' + String(d).padStart(2, '0');
  }
  return str;
}

function loadData(rangeFrom, rangeTo){
  $("loader").classList.add("on");

  if(!rangeFrom || !rangeTo){
    isRangeActive = false;
    rangeDataCache = null;
  } else {
    isRangeActive = true;
  }

  var args = {branch:curBranch};
  var useFrom = rangeFrom || ACTIVE_FROM;
  var useTo   = rangeTo   || ACTIVE_TO;
  if(useFrom && useTo){
    args.from_date = useFrom;
    args.to_date = useTo;
    isRangeActive = true;
    ACTIVE_FROM = useFrom;
    ACTIVE_TO = useTo;
  }

  return frappe.call({ method:"branch_command_center", args:args })
    .then(function(r) {
      var m = r.message;

      if(m && m.range){
        var rd = m.range;
        rangeDataCache = rd;
        isRangeActive = true;

        var dayMap = {};
        if(m.days){
          m.days.forEach(function(x) { dayMap[x.d] = {d:x.d, g:Number(x.g||0), pm:{}}; });
        }
        var days = Object.keys(dayMap).map(function(k){ return dayMap[k]; }).sort(function(a,b){ return a.d < b.d ? -1 : 1; });
        days.forEach(function(d) { PAYMODES.forEach(function(p) { d.pm[p] = d.pm[p]||0; }); });

        D = {
          days: days || [],
          target: +(rd.target||0),
          achieved: +(rd.achieved_final||0),
          mtdVal: +(rd.achieved_gross||0),
          // v17 FIX: these were all set to the WINDOW total, so the
          // "Today's Collected" strip card showed the whole range while
          // still being labelled and dated as today. Use the server's real
          // today figures instead.
          billToday: +(m.paid_today_gross||0),
          paidTodayGross: +(m.paid_today_gross||0),
          paidTodayExGst: +(m.paid_today_exgst||0),
          paidTodayGst: +(m.paid_today_gst||0),
          winGross: +(rd.achieved_gross||0),
          winExGst: +(rd.achieved_ex_gst||0),
          winGst: +(rd.achieved_gst||0),
          paidMtdGross: +(rd.achieved_gross||0),
          paidMtdExGst: +(rd.achieved_ex_gst||0),
          paidMtdGst: +(rd.achieved_gst||0),
          pmToday: (rd.modes||[]).map(function(m){ return {m:m.mode, v:m.gross}; }).sort(function(a,b){ return b.v - a.v; }),
          pmTodayDetail: (rd.modes||[]).map(function(m){ return {m:m.mode, v:m.gross, gst:m.gst, ex_gst:m.ex_gst, is_loan:m.is_loan, cut:m.cut_amt, final:m.final}; }),
          twin: [rd.from, rd.to],
          cycle: [rd.from, rd.to],
          pend: (m.pend||[]).map(function(p){ return {c:p.c, inv:p.inv, pkg:+p.pkg, paid:+p.paid, due:+p.due, days:+p.days}; }),
          pendTotal: m.pend_total||{},
          apBranchSummary: m.ap_branch_summary||[],
          apT: m.ap_today||{},
          apC: m.ap_cycle||{},
          apRows: m.ap_rows||[],
          stockZeroItems: m.stock_zero_items||[],
          emps: (rd.emps||m.emps||[]),
          media: m.media||[],
          leads: m.leads||{},
          leadSrc: m.lead_src||[],
          daily: m.daily||null,
          empList: m.emp_list||[],
          walkins: m.walkins||[],
          att: m.att||[],
          stock: m.stock||{},
          grv: m.grv||{},
          work: m.work||{}
        };

        renderAll();
      } else {
        isRangeActive = false;
        rangeDataCache = null;

        var dayMap = {};
        (m.days||[]).forEach(function(x) { dayMap[x.d] = {d:x.d, g:Number(x.g||0), pm:{}}; });
        (m.pm||[]).forEach(function(x) { 
          if(!dayMap[x.d]) return;
          var k = normPM(x.m); 
          dayMap[x.d].pm[k] = (dayMap[x.d].pm[k]||0) + Number(x.v||0); 
        });
        var days = Object.keys(dayMap).map(function(k){ return dayMap[k]; }).sort(function(a,b){ return a.d < b.d ? -1 : 1; });
        days.forEach(function(d) { PAYMODES.forEach(function(p) { d.pm[p] = d.pm[p]||0; }); });

        D = {
          days: days || [],
          target: +(m.target||0),
          achieved: +(m.achieved||0),
          mtdVal: +(m.paid_mtd_gross||0),
          billToday: +(m.paid_today_gross||0),
          paidTodayGross: +(m.paid_today_gross||0),
          paidTodayExGst: +(m.paid_today_exgst||0),
          paidTodayGst: +(m.paid_today_gst||0),
          paidMtdGross: +(m.paid_mtd_gross||0),
          paidMtdExGst: +(m.paid_mtd_exgst||0),
          paidMtdGst: +(m.paid_mtd_gst||0),
          pmToday: (m.pm_today||[]).slice().sort(function(a,b){ return b.v - a.v; }),
          pmTodayDetail: (m.pm_today_detail||[]),
          apBranchSummary: m.ap_branch_summary||[],
          apT: m.ap_today||{},
          apC: m.ap_cycle||{},
          stockZeroItems: m.stock_zero_items||[],
          twin: m.target_window,
          cycle: m.cycle,
