  extra+'<div class="tile-stats">'+stats.map(s=>'<div class="ts"><b class="num '+(s.c||"")+'">'+s.v+'</b><span>'+s.l+'</span></div>').join("")+'</div>'+
  '<div class="tile-hint">Click for summary \u25B8</div>';
}

function renderTiles(){
  if(!D) return;

  const t = D.days && D.days.length ? D.days[D.days.length-1] : {g:0};
  const ach = D.target ? pct(D.achieved, D.target) : 0;
  const bill = D.billToday || 0, billNet = bill/1.05;

  $("tile-sales").innerHTML = tileHTML("Collections Analysis",ICO.sales,
    inrS(bill)+' <small>/ '+inrS(billNet)+' net collected</small>',
    'Collected today (with GST / ex-GST)',
    [
      {v:inrS(D.mtdVal || 0),l:"MTD Collected (with GST)"},
      {v:inrS((D.mtdVal || 0)/1.05),l:"MTD Collected (ex-GST)"},
      {v:inrS(D.paidMtdGross || 0),l:"MTD Collected (with GST)"},
      {v:inrS(D.paidMtdExGst || 0),l:"MTD Collected (ex-GST)"}
    ],
    spark(D.days.slice(-7).map(d=>d.g)));

  const PT = D.pendTotal || {};
  const totDue = +(PT.due != null ? PT.due : (D.pend ? D.pend.reduce((s,p)=>s+p.due,0) : 0));
  const old = D.pend ? D.pend.filter(p=>p.days>60).length : 0;
  $("tile-pending").innerHTML = tileHTML("Pending Balances",ICO.pending,inrS(totDue),
    (PT.cust != null ? PT.cust : (D.pend?D.pend.length:0))+' clients \u00B7 '
      + (PT.inv != null ? PT.inv : (D.pend ? D.pend.reduce((s,p)=>s+p.inv,0) : 0))+' invoices \u00B7 '+winLabel(),
    [{v:old,l:"60+ Days",c:"r"},{v:inrS((D.pend && D.pend[0]) ? D.pend[0].due||0 : 0),l:"Highest",c:"r"},
     {v:inrS(D.pend ? D.pend.reduce((s,p)=>s+p.paid,0) : 0),l:"Collected"}],"",old);

  // v16: the tile now reports the FIXED monthly cycle against cycle-to-date
  // collections, and leads with what still has to be collected per day.
  // Previously it used the picked range, so choosing a single day showed the
  // full monthly target against one day's money and always read 0%.
  const T = D.daily || null;
  const tAch    = T ? T.pct : ach;
  const tTarget = T ? T.target : (D.target||0);
  const tGot    = T ? T.achieved : (D.achieved||0);
  const tGap    = T ? T.gap : Math.max(tTarget - tGot, 0);
  const perDay  = T ? T.req_per_day : 0;
  const left    = T ? T.days_left : Math.max(daysLeft(), 1);
  const onTrk   = T ? !!T.on_track : false;
  // v17: a cycle wholly in the past is CLOSED - show the settled result,
  // not a "needed per day" forecast for days that already happened.
  const closed  = T ? !!T.is_closed : false;
  const cycLbl  = T ? (frappe.datetime.str_to_user(T.cycle_from)+" \u2192 "
                     + frappe.datetime.str_to_user(T.cycle_to)) : "";

  $("tile-target").innerHTML = tileHTML("Target & Realisation",ICO.target,
    tAch+"%",
    inrS(tGot)+' of '+inrS(tTarget)+' \u00B7 '+(closed ? cycLbl : 'cycle to date'),
    closed
      ? [
          {v:inrS(tGap),l:tGap>0?"Shortfall":"Surplus",c:tGap>0?"r":""},
          {v:T.hit_days,l:"Days Hit"},
          {v:T.miss_days,l:"Days Missed",c:"r"}
        ]
      : [
          {v:inrS(perDay),l:"Needed / day",c:onTrk?"":"r"},
          {v:left,l:"Days Left"},
          {v:inrS(tGap),l:"Gap",c:tAch<70?"r":"a"}
        ],
    '<div style="margin-top:4px">'+bar(tAch, tAch<70?"r":tAch<85?"a":"")+'</div>'
    + (T ? '<div class="tgt-mini '+(closed ? (tAch>=100?"ok":"warn") : (onTrk?"ok":"warn"))+'">'
         + (closed ? ("Closed \u00B7 "+(tAch>=100?"Target met":"Missed by "+inrS(tGap)))
                   : (onTrk ? "On track" : "Behind \u00B7 "+T.miss_days+" missed days"))
         + '</div>' : ''));

  const aT = D.apT || {}, aC = D.apC || {};
  const totT = +(aT.total||0), awaitT = +(aT.booked||0);
  $("tile-appointments").innerHTML = tileHTML("Appointments",ICO.appointments,totT+' <small>Today</small>',
    (+(aT.visited_booked||0))+' visited-booked \u00B7 '+awaitT+' awaiting visit',
    [{v:+(aC.visited_booked||0),l:"Visited Booked"},{v:+(aC.visited_not_booked||0),l:"Vis. Not Bkd",c:"a"},
     {v:+(aC.not_visited||0),l:"Not Visited",c:"r"},{v:+(aC.booked||0),l:"Awaiting Visit",c:"a"}],"",awaitT);

  const M = D.media || [];
  // Headline is COLLECTED, so this tile reconciles with Collections Analysis.
  const mColl  = M.reduce((s,x)=>s + (+x.coll_gross || 0), 0);
  const mCollX = M.reduce((s,x)=>s + (+x.coll_ex_gst || 0), 0);
  const mBill  = M.reduce((s,x)=>s + (+x.inv_gross || 0), 0);
  const cc = M.filter(x=>x.m==="Call Center")[0];
  $("tile-service").innerHTML = tileHTML("Source Wise Collections",ICO.service,
    inrS(mColl)+' <small>/ '+inrS(mCollX)+' ex-GST</small>',
    M.length+' sources \u00B7 collected \u00B7 '+winLabel(),
    [
      {v:inrS(mBill),l:"Billed (with GST)"},
      {v:cc?inrS(cc.coll_gross||0):"\u20B90",l:"Call Center"},
      {v:pct(cc?(cc.coll_gross||0):0,mColl)+"%",l:"CC Share"}
    ]);

  const l = D.leads || {};
  $("tile-leads").innerHTML = tileHTML("Leads & Walk-ins",ICO.leads,(l.t||0)+' <small>Leads</small>',
    (l.w||0)+' walk-ins \u00B7 '+(l.bk||0)+' booked',
    [{v:l.bk||0,l:"Booked"},{v:pct(l.bk,l.w)+"%",l:"Walk-in\u2192Book"},{v:l.fu||0,l:"Follow-ups",c:"a"}]);

  const s = D.stock || {};
  $("tile-stock").innerHTML = tileHTML("Stock",ICO.stock,(s.zero||0)+' <small>Zero Qty</small>',
    (s.items||0)+' items \u00B7 value '+inrS(s.val),
    [{v:s.zero||0,l:"Zero Stock",c:"r"},{v:(s.items||0)-(s.zero||0),l:"In Stock"},{v:inrS(s.val),l:"Value"}]);

  const top = D.emps && D.emps.length ? D.emps[0] : null;
  $("tile-employee").innerHTML = tileHTML("Counselor Performance",ICO.employee,
    top?esc(top.n.split(" ")[0]):"\u2014",
    top?'Top \u00B7 '+inrS(top.net)+' ex-GST (cycle)':"No plans this cycle",
    [{v:D.emps ? D.emps.length : 0,l:"Counselors"},{v:inrS(D.emps ? D.emps.reduce((s,e)=>s+e.net,0) : 0),l:"Team Net"},
     {v:top?top.conv:0,l:"Top Plans"}]);

  const g = D.grv || {};
  $("tile-grievance").innerHTML = tileHTML("Grievances",ICO.grievance,(g.open_||0)+' <small>Open</small>',
    (g.esc||0)+' escalated \u00B7 '+(g.closed||0)+' closed',
    [{v:g.red||0,l:"Red Priority",c:"r"},{v:g.esc||0,l:"Escalated",c:"a"},{v:g.closed||0,l:"Closed"}],"",g.red||0);

  const w = D.work || {};
  $("tile-worklist").innerHTML = tileHTML("My Tasks",ICO.worklist,(w.open_||0)+' <small>Open</small>',
    'Assigned to '+esc(frappe.session.user),
    [{v:w.over_||0,l:"Overdue",c:"r"},{v:w.hi||0,l:"High",c:"a"},{v:w.due||0,l:"Due Today"}],"",w.over_||0);
}

function daysLeft(){
  return D.twin ? Math.max(frappe.datetime.get_day_diff(D.twin[1], frappe.datetime.get_today()),0) : 15;
}

function renderStrip(){
  if(!D) return;

  // v17 FIXES applied here:
  //  - Outstanding summed only the top-25 rows returned for the drawer, so
  //    it disagreed with the Pending tile. Now uses the server total.
  //  - Target Realisation used the picked range, so a one-day range showed
  //    0% against the full monthly target. Now uses the fixed cycle.
  //  - "MTD" labels were wrong whenever a custom range was active.
  const T  = D.daily || null;
  const PT = D.pendTotal || {};
  const rangeOn = !!(ACTIVE_FROM && ACTIVE_TO);
  const winLbl = rangeOn ? winLabel()
    : (D.cycle ? frappe.datetime.str_to_user(D.cycle[0])+" \u2192 "+frappe.datetime.str_to_user(D.cycle[1]) : "");
  const collLbl = rangeOn ? "Collected in range" : "MTD Collected";

  const outDue = +(PT.due != null ? PT.due
    : (D.pend ? D.pend.reduce((s,p)=>s+p.due,0) : 0));
  const outCli = (PT.cust != null ? PT.cust : (D.pend ? D.pend.length : 0));

  const cards=[
    {l:"Today's Collected", v:inrS(D.billToday || 0), s:frappe.datetime.str_to_user(frappe.datetime.get_today())},
    {l:collLbl+" (with GST)", v:inrS(D.mtdVal || 0), s:winLbl},
    {l:collLbl+" (ex-GST)", v:inrS(D.paidMtdExGst || 0), s:"After GST"},
    {l:"Target Realisation",
     v:(T ? T.pct : pct(D.achieved || 0, D.target || 0))+"%",
     s:"of "+inrS(T ? T.target : (D.target || 0))+(T ? " \u00B7 cycle" : "")},
    {l:"Outstanding", v:inrS(outDue), s:outCli+" clients"+(rangeOn?" \u00B7 in range":"")}
  ];
  $("strip").innerHTML = cards.map(c=>'<div class="strip-card"><div class="lbl">'+c.l+'</div>'+
    '<div class="val num">'+c.v+'</div><div class="sub">'+esc(c.s)+'</div></div>').join("");
}

var WK_FROM = null;
var WK_TO = null;

function wkTodayIso(){
  var d = new Date();
  return d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")+"-"+String(d.getDate()).padStart(2,"0");
}

function wkDate(v){
  if(!v) return "—";
  var p = String(v).slice(0,10).split("-");
  var m = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
  return p.length===3 ? p[2]+"-"+m[Number(p[1])-1]+"-"+p[0].slice(-2) : v;
}

function fmtAmPm(v){
  var m = String(v||"").match(/^(\d{1,2}):(\d{2})/);
  if(!m) return "—";
  var h=Number(m[1]), ap=h>=12?"PM":"AM";
  h=h%12||12;
  return h+":"+m[2]+" "+ap;
}

function wkCategory(v){
  var c=String(v||"").toLowerCase();
  var cls=c.indexOf("slim")>-1?"slim":c.indexOf("hair")>-1?"hair":c.indexOf("skin")>-1?"skin":"other";
  return '<span class="wk-cat '+cls+'">'+esc(v||"—")+'</span>';
}

function wkRowClass(st){
  st=String(st||"").toLowerCase();
  if(st==="visited booked" || st==="booked") return "wk-booked";
  if(st==="visited not booked" || st==="not booked" || st==="not visited") return "wk-not-booked";
  return "wk-pending";
}

function wkStatusBadge(st){
  var label=st==="Booked"?"Appointment Booked":(st||"Pending");
  var cls=wkRowClass(st)==="wk-booked"?"ok":wkRowClass(st)==="wk-not-booked"?"no":"wait";
  return '<span class="wk-status '+cls+'">'+esc(label)+'</span>';
}

function loadWalkinsRange(from,to){
  if(!curBranch) return;
  WK_FROM=from||wkTodayIso();
  WK_TO=to||WK_FROM;
  if($("wkFrom")) $("wkFrom").value=WK_FROM;
  if($("wkTo")) $("wkTo").value=WK_TO;
  $("wkList").innerHTML='<div class="wk-loading">Loading walk-ins…</div>';

  return frappe.call({method:"cc_walkins_range",type:"POST",args:{
    branch:curBranch,from_date:WK_FROM,to_date:WK_TO
  }}).then(function(r){
    var msg=(r&&r.message)||{};
    if(!D) D={};
    D.walkins=msg.rows||[];
    D.empList=msg.employees||[];
    renderWalkins();
  }).catch(function(e){
    $("wkList").innerHTML='<div class="wk-empty">Could not load walk-ins.</div>';
    toast("Walk-ins load failed — "+((e&&e.message)||"server error"));
  });
}

function renderWalkins(){
  var W=(D&&D.walkins)||[];
  var pending=W.filter(function(w){return !w.st || w.st==="Booked" || w.st==="Not Booked";}).length;
  $("wkPend").textContent=pending+" to update";
  $("wkNext").textContent=fmtAmPm(frappe.datetime.now_time());
  $("wkTitle").textContent="Walk-ins · "+wkDate(WK_FROM)+(WK_TO!==WK_FROM?" → "+wkDate(WK_TO):"");

  if(!W.length){
    $("wkList").innerHTML='<div class="wk-empty">No appointments found for '+esc(curBranch)+'.</div>';
    return;
  }

  var byDate={};
  W.forEach(function(w,i){ w._index=i; (byDate[w.d]||(byDate[w.d]=[])).push(w); });
  var html="";
  Object.keys(byDate).sort().forEach(function(date){
    var rows=byDate[date];
    html+='<div class="wk-datebar"><b>'+wkDate(date)+'</b>'+
      (date===wkTodayIso()?'<span>TODAY</span>':'')+'<i>'+rows.length+'</i></div>';
    html+='<div class="wk-table-wrap"><table class="wk-table"><thead><tr>'+
      '<th>Client</th><th>PD Form</th><th>Contact</th><th>Category</th>'+
      '<th>Appointment</th><th>Call Center Details</th><th>Branch Details</th>'+
      '<th>Status</th><th>Actions</th></tr></thead><tbody>';

    rows.forEach(function(w){
      var age=w.age!==""?' ('+esc(w.age)+')':'';
      var pdIcon=w.pd_available?'✓':'×';
      var pdCls=w.pd_available?'yes':'no';
      html+='<tr class="'+wkRowClass(w.st)+'">'+
        '<td><b>'+esc(w.n||"Unnamed")+age+'</b><small>'+esc(w.id)+'</small></td>'+
        '<td><div class="wk-pd"><span class="'+pdCls+'">'+pdIcon+'</span>'+
          '<button type="button" data-wkpd="'+w._index+'" '+(!w.pd_image_count?'disabled':'')+
          ' title="View PD Form images">▧</button></div></td>'+
        '<td><b class="num">'+esc(maskMobile(w.mobile))+'</b><small>Alt. No: '+esc(maskMobile(w.alt_mobile))+'</small></td>'+
        '<td>'+wkCategory(w.category)+'</td>'+
        '<td><b>'+wkDate(w.d)+'</b><small>'+fmtAmPm(w.t)+'</small><em>Appointment Date</em></td>'+
        '<td class="wk-callcenter"><b>Lead Owner: '+esc(w.owner||"—")+'</b><small>Source: '+esc(w.source||"—")+'</small></td>'+
        '<td><b>'+esc(w.branch||curBranch)+'</b><small>Consultation: '+esc(w.consultation_employee||"Not assigned")+'</small></td>'+
        '<td>'+wkStatusBadge(w.st)+'</td>'+
        '<td><div class="wk-actions">'+
          wkActionButtons(w,w._index)+
        '</div></td></tr>';
    });
    html+='</tbody></table></div>';
  });
  $("wkList").innerHTML=html;
  wkScheduleStatusExpiryRefresh();
}

var _wkExpiryTimer = null;
function wkScheduleStatusExpiryRefresh(){
  clearTimeout(_wkExpiryTimer);
  if(!D || !D.walkins || !D.walkins.length) return;
  var soonest = null;
  D.walkins.forEach(function(w){
    var rem = wkCorrectionWindowRemaining(w);
    if(rem !== null && rem > 0 && (soonest === null || rem < soonest)) soonest = rem;
  });
  if(soonest !== null){
    _wkExpiryTimer = setTimeout(function(){
      try { renderWalkins(); } catch(e){}
    }, Math.max(250, soonest + 250));
  }
}


function wkIsFinalLocked(w){
  // A row is locked when no further status is offered.
  return wkNextStatuses(w).length === 0;
}
function wkActionButtons(w,i){
  var locked=wkIsFinalLocked(w);
  return '<button type="button" class="wk-action-btn wk-change-status" data-wkedit="'+i+'" '+
      (locked?'disabled aria-disabled="true"':'')+
      ' title="'+(locked?'Final status locked':'Change status')+'">✎</button>'+
    '<button type="button" class="wk-action-btn" data-wkinfo="'+i+'" title="View complete client details">◉</button>'+
    '<button type="button" class="wk-action-btn" data-wkhistory="'+i+'" title="View remarks and status history">i</button>';
}



function wkNextStatuses(w){
  return wkAllowedStatesFor(w, WSTATES_ALL).map(function(x){ return x[0]; });
}
function wkSet(i,status){
  var w=D.walkins[i];
  if(!w || !status) return;
  if(wkNextStatuses(w).indexOf(status)===-1){toast("This status change is not allowed.");return;}
  askStatusUpdate({title:"Update status — "+(w.n||w.id),status:status,walkin:w,
    needReason:["Visited Not Booked","Not Visited"].indexOf(status)>-1,
    reasonLabel:"Remarks / reason",onSave:function(v){wkCommit(i,status,v.reason,v.employee);}});
}


function wkChange(i){
  var w = D.walkins[i];
  if(!w) return;

  // Re-read the Lead's current status from the server before we decide
  // which transitions to offer. A stale w.st causes the modal to offer
  // "Visited Booked" while the server still has the Lead at "Booked",
  // which the cc_walkin_update script correctly rejects.
  frappe.call({
    method: "frappe.client.get_value",
    args: {
      doctype: "Lead",
      filters: { name: w.id },
      fieldname: ["custom_appointment_status"]
    }
  }).then(function(r){
    var fresh =
      (r && r.message && r.message.custom_appointment_status) || "";
    if (fresh) w.st = fresh;
    openChangeModal(i, w);
  }).catch(function(){
    openChangeModal(i, w);
  });
}

function openChangeModal(i, w){
  var next = wkNextStatuses(w);

  if(!next.length){
    toast(wkLockedMessage(w));
    return;
  }

  askStatusUpdate({
    title: "Change status — " + (w.n || w.id),
    status: w.st,
    walkin: w,
    pickStatus: true,
    states: next,
    needReason: false,
    reasonLabel: "Remarks / reason",

    onSave: function(v){
      if(v.status === "Visited"){
        openVisitedClientForm(i, "Visited", v.employee);
        return;
      }
      wkCommit(i, v.status, v.reason, v.employee);
    }
  });
}

function askStatusUpdate(opt){
  // Make sure DIETICIAN staff are in D.empList before we build the
  // Consultation Employee dropdown. On failure we still open the modal
  // with whatever D.empList already holds.
  wkLoadExtraConsultEmployees().then(function(extras){
    wkMergeExtraConsultEmployees(extras);
    wkBuildStatusModal(opt);
  }).catch(function(){
    wkBuildStatusModal(opt);
  });
}

function wkBuildStatusModal(opt){
  wkCloseModal();

  var emps = (D && D.empList) || [];
  var options = '<option value="">— Select Consultation Employee —</option>' + emps.map(function(e){
    return '<option value="' + esc(e.id) + '">' + esc(e.n) + ' · ' + esc(e.dg) + '</option>';
  }).join("");

  var current = String((opt.walkin && opt.walkin.st) || "");

  // Use the full policy list so correction extras appear during the window.
  var states = (opt.states || wkNextStatuses(opt.walkin))
    .filter(function(s){ return s && s !== current; });

  // If a specific status was supplied (wkSet path) and it is not allowed,
  // refuse the modal instead of silently committing.
  if (opt.status && !opt.pickStatus &&
      states.indexOf(opt.status) === -1 &&
      opt.status !== "Visited") {
    toast("This status change is not allowed from “" + (current || "Pending") + "”.");
    return;
  }

  var statusHtml = opt.pickStatus
    ? '<label>Status *</label><select id="wkModalStatus">' +
        states.map(function(s){
          return '<option value="' + s + '">' + s + '</option>';
        }).join("") +
      '</select>'
    : '';

  // Build the correction-window hint BEFORE injecting it into the modal HTML.
  var windowHint = "";
  if (opt.walkin) {
    var rem = wkCorrectionWindowRemaining(opt.walkin);
    if (rem !== null) {
      if (rem > 0) {
        windowHint = '<div style="margin:4px 0 10px;padding:6px 10px;'
                   + 'border-radius:6px;font-size:11px;font-weight:700;'
                   + 'color:#6b5a26;background:#fcf6e6;border:1px solid #e0cb98;">'
                   + 'Correction window closes in '
                   + Math.ceil(rem / 60000) + ' minute(s).</div>';
      } else {
        windowHint = '<div style="margin:4px 0 10px;padding:6px 10px;'
                   + 'border-radius:6px;font-size:11px;font-weight:700;'
                   + 'color:#8a3325;background:#fdf0ed;border:1px solid #e5bcb2;">'
                   + 'Correction window has expired.</div>';
      }
    }
  }

  var ov = document.createElement("div");
  ov.id = "wkModal";
  ov.className = "wk-modal-bg";
  ov.innerHTML =
      '<div class="wk-modal"><header><b>' + esc(opt.title) + '</b><button data-wkclose>×</button></header>'
    + '<section>'
    +   windowHint
    +   '<label>Consultation Employee *</label>'
    +   '<select id="wkModalEmployee">' + options + '</select>'
    +   statusHtml
    +   '<label>Remarks' + (opt.needReason ? ' *' : '') + '</label>'
    +   '<textarea id="wkModalRemarks" maxlength="500" placeholder="Enter remarks"></textarea>'
    +   '<div id="wkPdUploadBlock" class="wk-pd-upload-box" style="display:none">'
    +     '<div class="wk-pd-upload-head"><div><b>PD Form Images *</b>'
    +       '<small>Select both together or add one image at a time</small></div>'
    +       '<span id="wkPdCount">' + Number((opt.walkin && opt.walkin.pd_image_count) || 0) + ' / 5</span></div>'
    +     '<label class="wk-pd-drop" for="wkPdFiles"><span class="wk-pd-plus">＋</span>'
    +       '<b>Select PD Form Images</b>'
    +       '<small>JPG, PNG or WEBP · Minimum 2 · Maximum 5</small>'
    +       '<input id="wkPdFiles" type="file" accept="image/jpeg,image/png,image/webp" multiple></label>'
    +     '<div id="wkPdPreview" class="wk-pd-preview"></div>'
    +     '<div id="wkPdHint" class="wk-upload-hint">Existing images: '
    +       Number((opt.walkin && opt.walkin.pd_image_count) || 0)
    +       '. Add the remaining images required.</div>'
    +   '</div>'
    +   '<div class="wk-modal-error" id="wkModalError"></div>'
    + '</section><footer>'
    +   '<button data-wkclose>Cancel</button>'
    +   '<button class="primary" data-wksave>Save</button>'
    + '</footer></div>';
  document.body.appendChild(ov);

  var pendingPdFiles = [];
  var pdInput   = $("wkPdFiles");
  var pdPreview = $("wkPdPreview");
  var pdCount   = $("wkPdCount");
  var pdHint    = $("wkPdHint");
  var basePdCount = Number((opt.walkin && opt.walkin.pd_image_count) || 0);

  function pdFingerprint(f){ return [f.name, f.size, f.lastModified].join("|"); }

  function renderPdSelection(){
    if (pdCount) pdCount.textContent = (basePdCount + pendingPdFiles.length) + " / 5";
    if (pdHint){
      var total = basePdCount + pendingPdFiles.length;
      pdHint.textContent = total >= 2
        ? total + " images ready."
        : "Add " + (2 - total) + " more image" + ((2 - total) === 1 ? "." : "s.");
      pdHint.classList.toggle("ok", total >= 2);
    }
    if (!pdPreview) return;
    pdPreview.innerHTML = "";
    pendingPdFiles.forEach(function(file, index){
      var card = document.createElement("div"); card.className = "wk-pd-card";
      var img  = document.createElement("img"); img.alt = file.name;
      var rm   = document.createElement("button");
      rm.type = "button"; rm.className = "wk-pd-remove"; rm.textContent = "×"; rm.title = "Remove";
      rm.onclick = function(ev){
        ev.preventDefault(); ev.stopPropagation();
        pendingPdFiles.splice(index, 1);
        renderPdSelection();
      };
      var nm = document.createElement("small"); nm.textContent = file.name;
      card.appendChild(img); card.appendChild(rm); card.appendChild(nm);
      pdPreview.appendChild(card);
      var reader = new FileReader();
      reader.onload = function(ev){ img.src = ev.target.result; };
      reader.readAsDataURL(file);
    });
  }

  if (pdInput){
    pdInput.addEventListener("change", function(){
      var existing = {};
      pendingPdFiles.forEach(function(f){ existing[pdFingerprint(f)] = 1; });
      var chosen = Array.prototype.slice.call(pdInput.files || []);
      for (var fi = 0; fi < chosen.length; fi++){
        var f = chosen[fi];
        if (["image/jpeg","image/png","image/webp"].indexOf(f.type) === -1){
          $("wkModalError").textContent = "Use JPG, PNG or WEBP images only.";
          continue;
        }
        if (f.size > 10 * 1024 * 1024){
          $("wkModalError").textContent = f.name + " is larger than 10 MB.";
          continue;
        }
        var fp = pdFingerprint(f);
        if (existing[fp]) continue;
        if (basePdCount + pendingPdFiles.length >= 5){
          $("wkModalError").textContent = "Maximum 5 PD Form images are allowed.";
          break;
        }
        existing[fp] = 1;
        pendingPdFiles.push(f);
      }
      pdInput.value = "";
      renderPdSelection();
    });
  }
  renderPdSelection();

  ov.onclick = function(e){
    if (e.target.closest("[data-wkclose]") || e.target === ov){
      wkCloseModal();
      return;
    }
    if (!e.target.closest("[data-wksave]")) return;

    var employee = $("wkModalEmployee").value;
    var status   = $("wkModalStatus") ? $("wkModalStatus").value : opt.status;
    var reason   = $("wkModalRemarks").value.trim();

    if (!employee){
      $("wkModalError").textContent = "Select the Consultation Employee.";
      return;
    }
    if (["Visited Not Booked","Not Visited"].indexOf(status) > -1 && !reason){
      $("wkModalError").textContent = "Remarks are required for " + status + ".";
      return;
    }

    var finalPd  = ["Visited Booked","Visited Not Booked"].indexOf(status) > -1;
    var existing = Number((opt.walkin && opt.walkin.pd_image_count) || 0);
    var files    = pendingPdFiles.slice();

    if (finalPd){
      if (!opt.walkin || !opt.walkin.patient){
        $("wkModalError").textContent = "Create the Client/Patient first and enter the PD Form Number.";
        return;
      }
      if (!opt.walkin.pd_number){
        $("wkModalError").textContent = "PD Form Number is missing in the Client/Patient.";
        return;
      }
      if (existing + files.length < 2){
        $("wkModalError").textContent = "At least 2 PD Form images are mandatory.";
        return;
      }
      if (existing + files.length > 5){
        $("wkModalError").textContent = "Maximum 5 PD Form images are allowed.";
        return;
      }
    }

    var done = function(){
      wkCloseModal();
      opt.onSave({ employee: employee, status: status, reason: reason });
    };

    if (files.length){
      var saveBtn = ov.querySelector("[data-wksave]");
      saveBtn.disabled = true;
      saveBtn.textContent = "Uploading…";
      wkUploadPdImages(opt.walkin.patient, files).then(function(){
        opt.walkin.pd_image_count = existing + files.length;
        opt.walkin.pd_available   = 1;
        done();
      }).catch(function(err){
        saveBtn.disabled = false;
        saveBtn.textContent = "Save";
        $("wkModalError").textContent = "Image upload failed: " + ((err && err.message) || "Please retry");
      });
    } else {
      done();
    }
  };

  function togglePdUpload(){
    var st    = $("wkModalStatus") ? $("wkModalStatus").value : opt.status;
    var block = $("wkPdUploadBlock");
    if (block){
      block.style.display = ["Visited Booked","Visited Not Booked"].indexOf(st) > -1 ? "block" : "none";
    }
  }
  if ($("wkModalStatus")) $("wkModalStatus").addEventListener("change", togglePdUpload);
  togglePdUpload();
}

function wkUploadPdImages(patient, files){
  var uploaded = [];
  var chain = Promise.resolve();

  // 1) Upload each file as a plain File row attached to the Patient.
  files.forEach(function(file){
    chain = chain.then(function(){
      var fd = new FormData();
      fd.append("file", file);
      fd.append("doctype", "Patient");
      fd.append("docname", patient);
      fd.append("is_private", "0");
      // No `fieldname` — we are not touching any single Attach field.
      return fetch("/api/method/upload_file", {
        method: "POST", body: fd, credentials: "same-origin",
        headers: { "X-Frappe-CSRF-Token": (frappe.csrf_token || "") }
      })
      .then(function(res){ if(!res.ok) throw new Error("HTTP "+res.status); return res.json(); })
      .then(function(data){
        if(data && data.exc) throw new Error("ERPNext rejected an image");
        var url = (data && data.message && data.message.file_url);
        if(!url) throw new Error("Upload returned no file URL");
        uploaded.push(url);
      });
    });
  });

  // 2) Append a PD Form row per uploaded file with all mandatory fields set.
  return chain.then(function(){
    return frappe.call({
      method: "frappe.client.get",
      args: { doctype: "Patient", name: patient }
    }).then(function(r){
      var doc = r.message;
      if(!doc) throw new Error("Patient not found");

      doc.custom_pd_form = doc.custom_pd_form || [];

      uploaded.forEach(function(url){
        doc.custom_pd_form.push({
          doctype: "PD Form",
          pd_form: url,           // <-- the mandatory field the server complained about
          // If your PD Form doctype has other mandatory fields, add them here:
          // e.g. custom_remarks: ""
        });
      });

      return frappe.call({
        method: "frappe.client.save",
        args: { doc: doc }
      });
    });
  });
}

function wkCommit(i, status, remarks, employee){
  var w = D.walkins[i];
  if(!w) return;
  if(status === "Cancelled"){ toast("Cancelled is not available."); return; }
  if(!wkCanChangeTo(w, status)){ toast(wkLockedMessage(w)); renderWalkins(); return; }

  frappe.call({
    method: "cc_walkin_update",
    type: "POST",
    args: {
      lead: w.id,
      status: status,
      remarks: remarks || "",
      employee: employee || ""
    }
  }).then(function(r){
    var msg = (r && r.message) || {};

    // Cache the anchor locally so the window state updates without a reload.
    if(!w.first_upd_on){
      w.first_upd_on = msg.first_updated_on
                    || msg.first_upd_on
                    || msg.first_status_updated_on
                    || "";
    }

    w.st = status;
    w.rm = remarks || "";
    w.upd_on = msg.updated_on || frappe.datetime.now_datetime();

    toast(status + " — saved \u2713");
    loadWalkinsRange(WK_FROM, WK_TO);
  }).catch(function(e){
    toast("Save failed — " + ((e && e.message) || "server error"));
  });
}

