    }).join(""):'<div class="wk-empty">No PD Form images attached.</div>';
    var history=(d.history||[]).length?(d.history||[]).map(function(x){
      return '<div class="wk-history"><i></i><div><b>'+esc(x.details)+'</b><small>'+esc(x.by)+' · '+esc(x.on)+'</small></div></div>';
    }).join(""):'<div class="wk-empty">No status history recorded yet.</div>';
