      '<div><small>Patient ID</small><b>'+esc(d.patient||w.patient||"Not created")+'</b><span>PD Form: '+esc(d.pd_number||w.pd_number||"Missing")+'</span></div>'+
      '<div><small>Contact</small><b>'+esc(maskMobile(w.mobile))+'</b><span>Alt: '+esc(maskMobile(w.alt_mobile))+'</span></div>'+
      '<div><small>Appointment</small><b>'+wkDate(w.d)+' · '+fmtAmPm(w.t)+'</b><span>'+esc(w.category||"—")+'</span></div>'+
      '<div><small>Call Centre</small><b>'+esc(w.owner||"—")+'</b><span>Source: '+esc(w.source||"—")+'</span></div>'+
      '<div><small>Branch</small><b>'+esc(w.branch||curBranch)+'</b><span>Consultation: '+esc(w.consultation_employee||w.upd_by||"Not assigned")+'</span></div>'+
    '</div>';
    ov.innerHTML='<div class="wk-modal wk-modal-wide"><header><b>'+esc(w.n)+' · Complete Details</b><button data-wkclose>×</button></header>'+
      '<section><div class="wk-tabs"><button data-tab="details" class="'+(tab!=="pd"?'on':'')+'">Remarks & History</button>'+
      '<button data-tab="pd" class="'+(tab==="pd"?'on':'')+'">PD Form Images ('+(d.images||[]).length+')</button></div>'+
      '<div data-panel="details" style="display:'+(tab!=="pd"?'block':'none')+'">'+complete+'<div class="wk-current"><b>Current Status</b><span>'+esc(d.status||"Pending")+'</span><p>'+esc(d.remarks||"No remarks")+'</p></div>'+history+'</div>'+
      '<div class="wk-gallery" data-panel="pd" style="display:'+(tab==="pd"?'grid':'none')+'">'+gallery+'</div></section></div>';
    document.body.appendChild(ov);
    ov.onclick=function(e){
      if(e.target.closest("[data-wkclose]")||e.target===ov){wkCloseModal();return;}
      var b=e.target.closest("[data-tab]"); if(!b)return;
      ov.querySelectorAll("[data-tab]").forEach(function(x){x.classList.toggle("on",x===b);});
      ov.querySelectorAll("[data-panel]").forEach(function(x){x.style.display=x.dataset.panel===b.dataset.tab?(b.dataset.tab==="pd"?"grid":"block"):"none";});
    };
