function salesMatrix(n){
  const ds = D.days ? D.days.slice(-n) : [];
  if(!ds.length) return '<div class="note">No invoices in range.</div>';
  const row=(l,fn,cls)=>{cls=cls||""; const v=ds.map(fn);
    return '<tr class="'+cls+'"><td>'+l+'</td>'+v.map(x=>'<td>'+inr(x)+'</td>').join("")+'<td><b>'+inr(v.reduce((a,b)=>a+b,0))+'</b></td></tr>';};
  return '<div class="mx-wrap"><table class="mx"><thead><tr><th>Particulars</th>'+
    ds.map(d=>'<th>'+fmtD(d.d)+'</th>').join("")+'<th>TOTAL</th></tr></thead><tbody>'
    + row("COLLECTIONS (with GST)",d=>d.g,"tot")
    + row("Less: GST (5%)",d=>Math.round(d.g-d.g/1.05))
    + row("NET COLLECTIONS (ex-GST)",d=>Math.round(d.g/1.05),"net")
    + '</tbody></table></div>';
}

