        + '<td class="num" style="font-weight:800;color:var(--red)">'+inr(p.due)+'</td>'
        + '<td class="num" style="color:var(--red)">'+inr(p.due/1.05)+'</td>'
        + '<td><div style="display:flex;align-items:center;gap:6px">'+bar(pct(p.paid,p.pkg))
          + '<b class="num" style="font-size:11px">'+pct(p.paid,p.pkg)+'%</b></div></td>'
        + '<td><span class="pill '+(p.days>60?"p-r":p.days>30?"p-a":"p-gr")+' num">'+p.days+'d</span></td></tr>';
      }).join('')
    + '<tr style="background:#F1F8E9;font-weight:800">'
      + '<td>TOTAL</td><td class="num">'+nInv+'</td>'
      + '<td class="num">'+inr(totPkg)+'</td>'
      + '<td class="num">'+inr(totPkg/1.05)+'</td>'
      + '<td class="num">'+inr(totPaid)+'</td>'
      + '<td class="num" style="color:var(--red)">'+inr(totDue)+'</td>'
      + '<td class="num" style="color:var(--red)">'+inr(totDue/1.05)+'</td>'
      + '<td></td><td></td></tr>'
    + '</tbody></table>') : '<div class="note">No outstanding invoices for '+esc(curBranch)+' in this range.</div>';

  $("mBody").innerHTML =
      csec("Dues \u2014 highest first ("+esc(curBranch)+")",P.length,tbl,true,true)
    + csec("How this is built",1,'<div class="formula">'
        + 'Source: <b>Sales Invoice</b>, <code>docstatus=1</code>, '
        + '<code>branch=\''+esc(curBranch)+'\'</code>, '
