function mTarget(){
  const T = D.daily || null;

  if(!T || !T.days){
    kpis([{v:"\u2014",l:"Daily tracker unavailable"}]);
    $("mBody").innerHTML = '<div class="note">Update the branch_command_center '
      + 'Server Script to v16 to enable daily target tracking.</div>';
    return;
  }

  const onTrack = !!T.on_track;
  // v17: past cycles are CLOSED - report the settled outcome instead of a
  // "needed per day" forecast for days that have already been and gone.
  const closed = !!T.is_closed;
  const cycLbl = frappe.datetime.str_to_user(T.cycle_from)+" \u2192 "
               + frappe.datetime.str_to_user(T.cycle_to);

  kpis(closed
    ? [
        {v:T.pct+"%",        l:"Final Realisation", c:T.pct<70?"r":T.pct<85?"a":""},
        {v:inrS(T.achieved), l:"Achieved"},
        {v:inrS(T.target),   l:"Target"},
        {v:inrS(T.gap),      l:T.gap>0?"Shortfall":"Surplus", c:T.gap>0?"r":""},
        {v:T.hit_days,       l:"Days Hit"},
        {v:T.miss_days,      l:"Days Missed", c:"r"}
      ]
    : [
        {v:T.pct+"%",           l:"Cycle Realisation", c:T.pct<70?"r":T.pct<85?"a":""},
        {v:inrS(T.achieved),    l:"Achieved (net)"},
        {v:inrS(T.gross||0),    l:"Gross receipts"},
        {v:inrS(T.target),      l:"Monthly Target"},
        {v:inrS(T.gap),         l:"Gap to close",      c:"r"},
        {v:inrS(T.req_per_day), l:"NEEDED PER DAY",    c:"r"},
        {v:T.days_left,         l:"Days Left"}
      ]);

  // ---- Headline ----
  const need = closed
    ? '<div class="tgt-need '+(T.pct>=100?"ok":"warn")+'">'
      + '<div class="tgt-need-l">Closed cycle \u00B7 '+cycLbl+'</div>'
      + '<div class="tgt-need-v">'+T.pct+'%<span> of target</span></div>'
      + '<div class="tgt-need-s">'+inrS(T.achieved)+' collected against '
        + inrS(T.target)+' \u2014 '
        + (T.gap>0 ? "short by "+inrS(T.gap) : "exceeded by "+inrS(T.achieved-T.target))
        + ' \u00B7 '+T.hit_days+' of '+T.total_days+' days hit</div>'
      + '</div>'
    : '<div class="tgt-need '+(onTrack?"ok":"warn")+'">'
      + '<div class="tgt-need-l">To hit '+inrS(T.target)+' by '
        + frappe.datetime.str_to_user(T.cycle_to)+'</div>'
      + '<div class="tgt-need-v">'+inr(T.req_per_day)+'<span> / day</span></div>'
      + '<div class="tgt-need-s">'+inrS(T.gap)+' still to collect across '
        + T.days_left+' remaining day'+(T.days_left===1?"":"s")+'</div>'
      + '</div>';

  // ---- Run rate vs required ----
  const rr = closed
    ? '<div class="tgt-grid">'
      + '<div class="tgt-cell"><span>Average per day</span><b>'+inr(T.run_rate)+' / day</b></div>'
      + '<div class="tgt-cell"><span>Needed per day</span><b>'+inr(T.target/T.total_days)+' / day</b></div>'
      + '<div class="tgt-cell"><span>Result</span><b class="'+(T.pct>=100?"":"r")+'">'
        + (T.pct>=100 ? "TARGET MET" : "MISSED by "+inrS(T.gap))+'</b></div>'
      + '<div class="tgt-cell"><span>Cycle length</span><b>'+T.total_days+' days</b></div>'
      + '<div class="tgt-cell"><span>Days hit</span><b>'+T.hit_days+'</b></div>'
      + '<div class="tgt-cell"><span>Days missed</span><b class="r">'+T.miss_days+'</b></div>'
      + '</div>'
    : '<div class="tgt-grid">'
      + '<div class="tgt-cell"><span>Current run rate</span><b>'+inr(T.run_rate)+' / day</b></div>'
      + '<div class="tgt-cell"><span>Required run rate</span><b class="r">'+inr(T.req_per_day)+' / day</b></div>'
      + '<div class="tgt-cell"><span>Projected at this pace</span><b class="'+(onTrack?"":"r")+'">'
        + inrS(T.projected)+'</b></div>'
      + '<div class="tgt-cell"><span>Status</span><b class="'+(onTrack?"":"r")+'">'
        + (onTrack ? "ON TRACK" : "BEHIND by "+inrS(Math.max(T.target-T.projected,0)))+'</b></div>'
      + '<div class="tgt-cell"><span>Days hit</span><b>'+T.hit_days+'</b></div>'
      + '<div class="tgt-cell"><span>Days missed</span><b class="r">'+T.miss_days+'</b></div>'
      + '</div>';

  // ---- Day by day ----
  const elapsed = T.days.filter(function(d){ return !d.future; });
  const rows = elapsed.slice().reverse();

  // v17: shows the full gross -> GST -> loan cut -> NET build-up, so it is
  // obvious which basis the target is measured on.
  var tbl = rows.length ? ('<div class="mx-wrap"><table class="tbl tgt-tbl"><thead><tr>'
    + '<th>Date</th><th class="num">Gross</th><th class="num">GST</th>'
    + '<th class="num">Loan cut</th><th class="num">Collected (net)</th>'
    + '<th class="num">Target that day</th><th class="num">+/-</th>'
    + '<th class="num">Cumulative</th><th>Result</th>'
    + '</tr></thead><tbody>'
    + rows.map(function(d){
        const ok = d.hit === 1;
        return '<tr class="'+(ok?"tgt-hit":"tgt-miss")+'">'
          + '<td><b>'+frappe.datetime.str_to_user(d.d)+'</b></td>'
          + '<td class="num" style="color:var(--mut)">'+inr(d.gross||0)+'</td>'
          + '<td class="num a">'+inr(d.gst||0)+'</td>'
          + '<td class="num" style="color:'+((d.cut||0)>0?"#C62828":"var(--mut)")+'">'
            + ((d.cut||0)>0 ? "-"+inr(d.cut) : "\u2014")+'</td>'
          + '<td class="num" style="font-weight:800">'+inr(d.got)+'</td>'
          + '<td class="num">'+inr(d.req)+'</td>'
          + '<td class="num" style="color:'+(ok?"#2E7D32":"#C62828")+'">'
            + (d.diff>=0?"+":"")+inr(d.diff)+'</td>'
          + '<td class="num" style="color:var(--mut)">'+inrS(d.cum)+'</td>'
          + '<td><span class="pill '+(ok?"p-g":"p-r")+'">'+(ok?"HIT":"MISS")+'</span></td>'
          + '</tr>';
      }).join('')
    + '<tr style="background:#F1F8E9;font-weight:800">'
      + '<td>TOTAL</td>'
      + '<td class="num">'+inr(T.gross||0)+'</td>'
      + '<td class="num">'+inr(T.gst||0)+'</td>'
      + '<td class="num">'+((T.cut||0)>0?"-"+inr(T.cut):"\u2014")+'</td>'
      + '<td class="num">'+inr(T.achieved)+'</td>'
      + '<td class="num"></td><td class="num"></td>'
      + '<td class="num">'+inrS(T.achieved)+'</td><td></td></tr>'
    + '</tbody></table></div>') : '<div class="note">No elapsed days in this cycle yet.</div>';

  // ---- Mini bar strip: collected vs required per day ----
  const mx = Math.max.apply(null, elapsed.map(function(d){
    return Math.max(d.got, d.req); }).concat([1]));
  const strip = '<div class="tgt-strip">'
    + elapsed.map(function(d){
        const gh = Math.round((d.got/mx)*100);
        const rh = Math.round((d.req/mx)*100);
        return '<div class="tgt-bar" title="'+frappe.datetime.str_to_user(d.d)
          + ' \u2014 collected '+inr(d.got)+' of '+inr(d.req)+'">'
          + '<div class="tgt-bar-wrap">'
          +   '<i class="'+(d.hit?"ok":"no")+'" style="height:'+gh+'%"></i>'
          +   '<u style="bottom:'+rh+'%"></u>'
          + '</div>'
          + '<span>'+d.d.slice(8,10)+'</span></div>';
      }).join('')
    + '</div>'
    + '<div class="tgt-legend">'
    +   '<span><i class="sw ok"></i>Hit</span>'
    +   '<span><i class="sw no"></i>Miss</span>'
    +   '<span><i class="sw line"></i>Required that day</span>'
    + '</div>';

  $("mBody").innerHTML =
      need
    + csec("Pace check",6,rr,true)
    + csec("Daily collections vs required",elapsed.length,strip,true)
    + csec("Day by day \u2014 newest first",rows.length,tbl,true,true)
    + csec("How the daily target works",1,'<div class="formula">'
        + '<b>Basis \u2014 realisation is measured NET, not on gross receipts.</b><br>'
        + 'For every Payment Entry: <code>ex-GST = paid_amount \u00D7 100/105</code>, then '
        + 'loan modes lose a further <code>15% of ex-GST</code>. '
        + '<code>Collected (net) = ex-GST \u2212 loan cut</code>.<br>'
        + 'Loan modes: Bajaj, Sai Roshini, Fibe, Carepay, Savein, Loan Tap / Uno, '
        + 'ShopSE, Liqui Loans. Every other mode (Cash, Card, UPI, Bank, Razorpay) '
        + 'has GST removed but no cut.<br>'
        + 'This cycle: gross <b>'+inr(T.gross||0)+'</b> \u2212 GST <b>'+inr(T.gst||0)
        + '</b> \u2212 loan cut <b>'+inr(T.cut||0)+'</b> = <b>'+inr(T.achieved)+'</b>.<br><br>'
        + 'This uses the <b>deficit method</b>, not a flat daily split.<br><br>'
        + 'Each day: <code>target that day = (monthly target \u2212 collected so far) '
        + '\u00F7 days still remaining</code>.<br><br>'
        + 'So a miss automatically raises the bar for every day after it, and a big day '
        + 'lowers it. Cycle is <b>'+frappe.datetime.str_to_user(T.cycle_from)+' \u2192 '
        + frappe.datetime.str_to_user(T.cycle_to)+'</b> ('+T.total_days+' days, 6th\u21925th).<br><br>'
        + 'This tracker reports on whichever cycle the <b>range start</b> falls in, so the '
        + '<b>Last Month</b> preset shows that cycle\u2019s target and day-by-day result. '
        + 'The target is not pro-rated for a partial range \u2014 it is always the full '
        + 'cycle target of <b>'+inrS(T.target)+'</b>. '
        + 'Collections come from Payment Entry, <code>docstatus=1</code>, branch <b>'
        + esc(curBranch)+'</b>.</div>');
}

