          + '<td class="num">'+(r.visited_not_booked||0)+'</td>'
          + '<td class="num">'+(r.not_visited||0)+'</td></tr>';
      }).join('')
    + '</tbody></table></div>') : '<div class="note">No appointments in this range.</div>';

  // Appointment rows for the selected window.
  var rows = D.apRows || [];
