    + '</tbody></table></div>') : '<div class="note">No appointment rows.</div>';

  $("mBody").innerHTML =
      csec("Today \u2014 "+frappe.datetime.str_to_user(frappe.datetime.get_today()),7,g(aT),true)
    + csec("Selected range \u2014 "+winLabel(),7,g(aC),true)
    + csec("Branch summary \u2014 "+esc(curBranch)+" ("+winLabel()+")",bs.length,bsTable,true)
    + csec("Appointments \u2014 "+winLabel(),rows.length,rowTbl,false)
    + csec("Bucket definitions",1,'<div class="formula">'
        + 'Same buckets as the <b>Branch Wise CC Appointments</b> block.<br><br>'
