function mMedia(){
  const M = (D.media || []).slice().sort(function(a,b){
    return (+b.coll_gross||0) - (+a.coll_gross||0);
  });

  const coll   = M.reduce((s,x)=>s + (+x.coll_gross  || 0), 0);
  const collX  = M.reduce((s,x)=>s + (+x.coll_ex_gst || 0), 0);
  const collG  = M.reduce((s,x)=>s + (+x.coll_gst    || 0), 0);
  const bill   = M.reduce((s,x)=>s + (+x.inv_gross   || 0), 0);
  const billX  = M.reduce((s,x)=>s + (+x.inv_ex_gst  || 0), 0);
  const billG  = M.reduce((s,x)=>s + (+x.inv_gst     || 0), 0);
  const unpaid = bill - coll;

  kpis([
    {v:inrS(coll),l:"Collected (with GST)"},
    {v:inrS(collX),l:"Collected (ex-GST)"},
    {v:inrS(collG),l:"GST on collections",c:"a"},
    {v:inrS(bill),l:"Billed (with GST)"},
    {v:inrS(unpaid),l:"Billed not yet collected",c:unpaid>0?"r":""}
  ]);

  var tbl = M.length ? ('<table class="tbl"><thead><tr>'
    + '<th>Source</th><th class="num">Plans</th><th class="num">Inv</th>'
    + '<th class="num">Billed (with GST)</th>'
    + '<th class="num">Collected (with GST)</th>'
    + '<th class="num">Collected (ex-GST)</th>'
    + '<th class="num">GST</th><th class="num">Share</th></tr></thead><tbody>'
    + M.map(function(x){
        var b = +x.inv_gross   || 0;
        var c = +x.coll_gross  || 0;
        var e = +x.coll_ex_gst || 0;
        var g = +x.coll_gst    || 0;
        return '<tr>'
          + '<td><b>'+esc(x.m)+'</b></td>'
          + '<td class="num">'+(x.c||0)+'</td>'
          + '<td class="num">'+(x.inv_count||0)+'</td>'
          + '<td class="num" style="color:var(--mut)">'+inr(b)+'</td>'
          + '<td class="num" style="font-weight:800">'+inr(c)+'</td>'
          + '<td class="num">'+inr(e)+'</td>'
          + '<td class="num a">'+inr(g)+'</td>'
          + '<td class="num">'+pct(c,coll)+'%</td></tr>';
      }).join('')
    + '<tr style="background:#F1F8E9;font-weight:800">'
      + '<td>TOTAL</td>'
      + '<td class="num">'+M.reduce((s,x)=>s+(+x.c||0),0)+'</td>'
      + '<td class="num">'+M.reduce((s,x)=>s+(+x.inv_count||0),0)+'</td>'
      + '<td class="num">'+inr(bill)+'</td>'
      + '<td class="num">'+inr(coll)+'</td>'
      + '<td class="num">'+inr(collX)+'</td>'
      + '<td class="num">'+inr(collG)+'</td>'
      + '<td class="num">100%</td></tr>'
    + '</tbody></table>') : '<div class="note">No data in this range</div>';

  $("mBody").innerHTML =
      csec("Source wise \u2014 "+winLabel(), M.length, tbl, true)
    + csec("Visual share (collected)", M.length,
        M.map(function(x){
          var c = +x.coll_gross || 0;
          return '<div style="display:flex;align-items:center;gap:12px;padding:6px 2px">'
            + '<span style="width:130px;font-weight:700;font-size:12px">'+esc(x.m)+'</span>'
            + bar(coll ? c/coll*100 : 0)
            + '<b class="num" style="width:140px;text-align:right">'+inrS(c)
            + ' <span style="color:var(--mut)">/ '+inrS(+x.coll_ex_gst||0)+'</span></b></div>';
        }).join(''), true)
    + csec("Why Billed and Collected differ",1,'<div class="formula">'
        + 'These are two different numbers and they are <b>not</b> meant to match:<br><br>'
        + '<b>Collected</b> = Payment Entry money received in this window, split by source via '
        + 'Payment Entry Reference \u2192 Sales Invoice \u2192 Therapy Plan. '
        + 'This total <b>ties exactly</b> to the Collections Analysis tile.<br>'
        + '<b>Billed</b> = Sales Invoice <code>grand_total</code> raised in this window.<br><br>'
        + 'The gap of <b>'+inr(unpaid)+'</b> exists because invoices raised in this window can be '
        + 'part-paid or unpaid (see Pending Balances), while some money collected here settles '
        + 'invoices raised <i>before</i> the window. Use <b>Collected</b> for revenue and target '
        + 'tracking; use <b>Billed</b> for sales performance.</div>');
}

