function mPayMode(){
  const P = D.pmToday||[];
  const idx = MODAL_CTX && MODAL_CTX.pmIdx!=null ? MODAL_CTX.pmIdx : null;
  const tot = P.reduce((s,x)=>s+ +x.v,0);
  if(idx!=null && P[idx]){
    const p=P[idx];
    const isLoan = isLoanMode(p.m);
    kpis([{v:inrS(p.v),l:"Collected Today"},{v:pct(p.v,tot)+"%",l:"Share of Today"},
          {v:esc(p.m||"Unknown")+" "+(isLoan?'🏦':'💳'),l:"Mode"}]);
    $("mBody").innerHTML = csec(esc(p.m||"Unknown")+" \u2014 today",1,
      '<div class="formula">This mode collected '+inr(p.v)+' today, '+pct(p.v,tot)+'% of all collections. Source: Payment Entry, docstatus=1, posting_date=today, branch='+esc(curBranch)+'.</div>',true)
     + csec("All modes today",P.length,'<button class="wbtn" data-pmback="1" style="width:100%;padding:10px">\u2190 View all payment modes</button>',true);
    return;
  }
  kpis([{v:inrS(tot),l:"Total Collected Today"},{v:P.length,l:"Modes Used"}]);

  let pmDetailHTML = '<table class="tbl"><thead><tr><th>Mode</th><th>Type</th><th>Amount</th><th>Share</th><th>Ex-GST</th><th>15% Cut</th><th>Final</th></tr></thead><tbody>';
  let totalExGst = 0, totalFinal = 0;
  P.forEach((p,i) => {
    const amt = p.v || 0;
    const exGst = amt / 1.05;
    const isLoan = isLoanMode(p.m);
    const cut = isLoan ? (exGst * 0.15) : 0;
    const final = isLoan ? (exGst - cut) : exGst;
    totalExGst += exGst;
    totalFinal += final;

    pmDetailHTML += '<tr data-pmdrill="'+i+'" style="cursor:pointer">';
    pmDetailHTML += '<td>'+esc(p.m||"Unknown")+'</td>';
    pmDetailHTML += '<td>'+(isLoan?'🏦 Loan':'💳 Non-Loan')+'</td>';
    pmDetailHTML += '<td class="num">'+inr(amt)+'</td>';
    pmDetailHTML += '<td class="num">'+pct(p.v,tot)+'%</td>';
    pmDetailHTML += '<td class="num">'+inr(exGst)+'</td>';
    pmDetailHTML += '<td class="num" style="color:'+(isLoan?'#D32F2F':'#999')+';">'+(isLoan?inr(cut):'—')+'</td>';
    pmDetailHTML += '<td class="num" style="font-weight:800;color:#2E7D32;">'+inr(final)+'</td>';
    pmDetailHTML += '</tr>';
  });
  pmDetailHTML += '<tr style="border-top:3px solid #2E7D32;font-weight:900;background:#e8f0e8;">';
  pmDetailHTML += '<td>TOTAL</td><td></td>';
  pmDetailHTML += '<td class="num">'+inr(tot)+'</td>';
  pmDetailHTML += '<td class="num">100%</td>';
  pmDetailHTML += '<td class="num">'+inr(totalExGst)+'</td>';
  pmDetailHTML += '<td class="num" style="color:#D32F2F;">—</td>';
  pmDetailHTML += '<td class="num" style="font-weight:900;color:#1B5E20;">'+inr(totalFinal)+'</td>';
  pmDetailHTML += '</tr></tbody></table>';

  $("mBody").innerHTML = csec("Payment modes \u2014 today (click a row for detail)",P.length,pmDetailHTML,true);
}
