          </div>
          <div>
            <label style="display:block;font-size:10px;font-weight:700;color:#666;margin-bottom:1px;">To</label>
            <input type="date" id="grTo" value="${todayStr}" min="1900-01-01" max="2099-12-31" autocomplete="off" style="padding:6px 10px;border:2px solid #c8d6c8;border-radius:6px;font-size:12px;width:145px;font-weight:600;background:white;">
          </div>
          <button class="wbtn" data-globalrangego="1" style="padding:8px 20px;font-size:12px;font-weight:800;border-radius:6px;background:#2E7D32;color:white;border:none;cursor:pointer;margin-top:12px;">Apply</button>
          <button class="wbtn" data-resetrange="1" style="padding:8px 16px;font-size:12px;font-weight:700;border-radius:6px;background:#e0e0e0;color:#333;border:none;cursor:pointer;margin-top:12px;">Reset</button>
