}

// v16: force native date pickers even if the page HTML still ships the
// legacy type="text" boxes, and seed them with this month's cycle.
function upgradeRangeInputs(){
  ["grFrom","grTo"].forEach(function(id){
    var el = $(id);
    if(!el) return;
    if(el.getAttribute("type") !== "date"){
      el.setAttribute("type","date");
      el.style.width = "145px";
      var lab = el.parentElement ? el.parentElement.querySelector("label") : null;
      if(lab) lab.textContent = (id === "grFrom") ? "From" : "To";
    }
    el.setAttribute("min","1900-01-01");
    el.setAttribute("max","2099-12-31");
    el.setAttribute("autocomplete","off");
    // Anything that is not already ISO (e.g. a stale "06-07-26") is discarded.
    if(!/^\d{4}-\d{2}-\d{2}$/.test(el.value || "")){
      el.value = (id === "grFrom") ? defaultFrom() : defaultTo();
    }
  });
}

function bindRangeInputs(){
  ["grFrom","grTo"].forEach(function(id){
    var el = $(id);
    if(!el || el.dataset.lbccBound) return;
    el.dataset.lbccBound = "1";
    ["keydown","keypress","keyup","input","paste","focus","focusin"].forEach(function(ev){
      el.addEventListener(ev, function(e){ e.stopPropagation(); }, true);
    });
    el.addEventListener("click", function(e){ e.stopPropagation(); el.focus(); }, true);
    el.addEventListener("change", function(){
      var f = $("grFrom").value, t = $("grTo").value;
      if(!f || !t) return;
      if(f > t){ toast("From date must be before To date"); return; }
      runGlobalRange();
    });
  });
}

function validateDateFormat(input) {
  const val = input.value.trim();
  if (!val) return;
  const parts = val.split('-');
  if (parts.length === 3) {
    const d = parseInt(parts[0]);
    const m = parseInt(parts[1]);
    const y = parseInt(parts[2]);
    if (!isNaN(d) && !isNaN(m) && !isNaN(y) && d >= 1 && d <= 31 && m >= 1 && m <= 12) {
      input.style.borderColor = '#2E7D32';
      return;
    }
  }
  input.style.borderColor = '#D32F2F';
}

// v17: quick date presets.
// "This Month" / "Last Month" follow the company 6th->5th billing cycle,
// NOT the calendar month, so they line up with how targets are set.
// "This Year" uses the Indian financial year (1 April -> 31 March).
function cycleStartFor(d){
    // Cycle containing date d starts on the 6th.
    if(d.getDate() >= 6) return new Date(d.getFullYear(), d.getMonth(), 6);
    return new Date(d.getFullYear(), d.getMonth() - 1, 6);
}

function presetRange(key){
    var now = new Date();
    var t = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    var from, to;

    if(key === "today"){
        from = t; to = t;
    } else if(key === "yesterday"){
        from = new Date(t.getFullYear(), t.getMonth(), t.getDate() - 1);
        to = from;
    } else if(key === "last7"){
        from = new Date(t.getFullYear(), t.getMonth(), t.getDate() - 6);
        to = t;
    } else if(key === "thismonth"){
        // Current billing cycle start -> today (never a future date).
        from = cycleStartFor(t);
        to = t;
    } else if(key === "lastmonth"){
        // Previous full cycle: 6th of the month before, to the 5th.
        var curStart = cycleStartFor(t);
        from = new Date(curStart.getFullYear(), curStart.getMonth() - 1, 6);
        to = new Date(curStart.getFullYear(), curStart.getMonth(), 5);
    } else if(key === "thisyear"){
        // Financial year: 1 April -> today. Before April, FY started last year.
        var fyYear = (t.getMonth() >= 3) ? t.getFullYear() : t.getFullYear() - 1;
        from = new Date(fyYear, 3, 1);
        to = t;
    } else {
        return null;
    }
    return { from: isoOf(from), to: isoOf(to) };
}

function applyPreset(key){
    var r = presetRange(key);
    if(!r) return;
    if($("grFrom")) $("grFrom").value = r.from;
    if($("grTo"))   $("grTo").value   = r.to;
    ACTIVE_FROM = r.from;
    ACTIVE_TO = r.to;
    markActivePreset(key);
    $("loader").classList.add("on");
    loadData(r.from, r.to);
    syncRosterToBranch();
}

// Highlight whichever preset matches the current window, so the chips stay
// in sync when dates are typed manually or Reset is pressed.
function markActivePreset(key){
    var box = $("grPresets");
    if(!box) return;
    if(key === undefined){
        key = null;
        var keys = ["today","yesterday","last7","thismonth","lastmonth","thisyear"];
        for(var i = 0; i < keys.length; i++){
            var r = presetRange(keys[i]);
            if(r && r.from === ACTIVE_FROM && r.to === ACTIVE_TO){ key = keys[i]; break; }
        }
    }
    var chips = box.querySelectorAll("[data-preset]");
    for(var j = 0; j < chips.length; j++){
        if(chips[j].dataset.preset === key) chips[j].classList.add("on");
        else chips[j].classList.remove("on");
    }
}

function runGlobalRange(){
  const f = $("grFrom") ? $("grFrom").value.trim() : "";
  const t = $("grTo") ? $("grTo").value.trim() : "";
  if(!f || !t){ toast("Pick both From and To dates"); return; }
  if (f > t){ toast("From date must be before To date"); return; }

  ACTIVE_FROM = f;
  ACTIVE_TO = t;
  $("loader").classList.add("on");
  loadData(f, t);
  syncRosterToBranch();
}

function resetRange(){
  // v16: Reset returns to THIS MONTH's cycle (6th -> today), the page default.
  const fromStr = defaultFrom();
  const toStr   = defaultTo();

  if($("grFrom")) $("grFrom").value = fromStr;
  if($("grTo")) $("grTo").value = toStr;

  ACTIVE_FROM = fromStr;
  ACTIVE_TO = toStr;
  rangeDataCache = null;
  markActivePreset();
  loadData(fromStr, toStr);
  syncRosterToBranch();
}

