function formatINR(value) {
    var n = parseFloat(value || 0) || 0;
    return "₹" + INR_FORMAT.format(n);
}

function isoToDisplay(iso) {
    if (!iso) return "No Expiry";
    var s = String(iso).slice(0, 10);
    if (s.length < 10) return "No Expiry";
    var parts = s.split("-");
    var yy = parts[0].slice(2);
    var mon = MON_SHORT[parseInt(parts[1], 10) - 1] || parts[1];
    return parts[2] + "-" + mon + "-" + yy;
}

function getDaysLeft(toDate) {
    if (!toDate) return null;
    var today = new Date(todayIso() + "T00:00:00");
    var expiry = new Date(String(toDate).slice(0, 10) + "T00:00:00");
    return Math.ceil((expiry - today) / (1000 * 60 * 60 * 24));
}

function todayIso() {
    if (typeof frappe !== "undefined" && frappe.datetime && frappe.datetime.get_today) {
        return frappe.datetime.get_today();
    }
    var d = new Date();
    var y = d.getFullYear();
    var m = String(d.getMonth() + 1).padStart(2, "0");
    var day = String(d.getDate()).padStart(2, "0");
    return y + "-" + m + "-" + day;
}

function isOfferCurrentlyValid(offer) {
    var td = todayIso();
    var fromDate = offer.from_date ? String(offer.from_date).slice(0, 10) : "";
    var toDate = offer.to_date ? String(offer.to_date).slice(0, 10) : "";
    if (parseInt(offer.is_active || 0) !== 1) return false;
    if (fromDate && fromDate > td) return false;
    if (toDate && toDate < td) return false;
    return true;
}

function isPricingRuleCurrentlyValid(rule) {
    var td = todayIso();
    var validFrom = rule.valid_from ? String(rule.valid_from).slice(0, 10) : "";
    var validUpto = rule.valid_upto ? String(rule.valid_upto).slice(0, 10) : "";
    if (parseInt(rule.disable || 0) === 1) return false;
    if (parseInt(rule.selling || 0) !== 1) return false;
    if (validFrom && validFrom > td) return false;
    if (validUpto && validUpto < td) return false;
    return true;
}

function isManualOfferCurrentlyValid(offer) {
    var td = todayIso();
    var fromDate = offer.from_date ? String(offer.from_date).slice(0, 10) : "";
    var toDate = offer.to_date ? String(offer.to_date).slice(0, 10) : "";
    if (fromDate && fromDate > td) return false;
    if (toDate && toDate < td) return false;
    return true;
}

function getAmountText(offer) {
    if (offer.source_doctype === "Manual Offer") {
        var rate = parseFloat(offer.rate || 0) || 0;
        return rate ? formatINR(rate) : "Offer";
    }
    if (offer.source_doctype === "Pricing Rule") {
        var rate = parseFloat(offer.rate || 0) || 0;
        var discountAmount = parseFloat(offer.discount_amount || 0) || 0;
        var discountPercentage = parseFloat(offer.discount_percentage || 0) || 0;
        if (rate) return formatINR(rate);
        if (discountAmount) return formatINR(discountAmount) + " OFF";
        if (discountPercentage) return discountPercentage + "% OFF";
        return "Offer";
    }
    if (offer.offer_type === "Fixed Price") {
        var gross = parseFloat(offer.including_gst) || 0;
        var base = parseFloat(offer.offer_price) || 0;
        if (gross) return formatINR(gross);
        if (base) return formatINR(base * 1.05);
        return "₹0";
    }
    if (offer.offer_type === "LIFErise Package") {
        return formatINR(offer.discount_amount) + " OFF";
    }
    return "Offer";
}

function getAmountLabel(offer) {
    if (offer.source_doctype === "Manual Offer") return "PACKAGE PRICE";
    if (offer.source_doctype === "Pricing Rule") {
        if (parseFloat(offer.rate || 0)) return "OFFER RATE";
        if (parseFloat(offer.discount_amount || 0)) return "DISCOUNT";
        if (parseFloat(offer.discount_percentage || 0)) return "DISCOUNT";
        return "PRICING RULE";
    }
    if (offer.offer_type === "Fixed Price") return "OFFER PRICE";
    if (offer.offer_type === "LIFErise Package") return "DISCOUNT";
    return "CURRENT OFFER";
}

function getPricingRuleItems(ruleName) {
    return new Promise(function(resolve) {
        try {
            frappe.call({
                method: "frappe.desk.form.load.getdoc",
                args: { doctype: "Pricing Rule", name: ruleName },
                callback: function(r) {
                    var doc = r.docs && r.docs[0] ? r.docs[0] : null;
                    if (!doc) { resolve(""); return; }
                    var items = (doc.items || []).map(function(row) { return row.item_code; }).filter(Boolean);
                    var itemGroups = (doc.item_groups || []).map(function(row) { return row.item_group; }).filter(Boolean);
                    var allItems = items.concat(itemGroups);
                    resolve(allItems.length ? allItems.join(", ") : "");
                }
            });
        } catch(e) {
            ("Unable to fetch Pricing Rule items for:", ruleName, e, void 0);
            resolve("");
        }
    });
}

