    if (countText) { countText.textContent = OFFERS.length + " active offer" + (OFFERS.length === 1 ? "" : "s") + " running"; }
    track.innerHTML = "";
    OFFERS.forEach(function(offer, index) {
        var slide = document.createElement("div");
        slide.className = "offer-slide";
        var daysLeft = getDaysLeft(offer.to_date);
        var expiryText = "Always Active";
        if (daysLeft !== null) {
            if (daysLeft === 0) { expiryText = "Expires Today"; }
            else if (daysLeft === 1) { expiryText = "Expires Tomorrow"; }
            else { expiryText = "Expires in " + daysLeft + " days"; }
        }
        var offerName = offer.offer_name || "Special Offer";
        var itemText = (offer.source_doctype === "Pricing Rule" || offer.source_doctype === "Manual Offer") ? (offer.item_names || "") : (offer.therapy_plan_template || "");
        var amountText = getAmountText(offer);
        var amountLabel = getAmountLabel(offer);
        var minQty = offer.min_qty ? parseFloat(offer.min_qty) : null;
        slide.innerHTML = 
            '<div class="offer-card">' +
                '<span class="pkg-id">OFFER ' + String(index + 1).padStart(2, "0") + '</span>' +
                '<h4>' + offerName + '</h4>' +
                '<div class="offer-meta-row">' +
                    (itemText ? '<span class="offer-items">' + itemText + '</span>' : '') +
                    (minQty ? '<span class="detail-tag minimum-sessions">Minimum Sessions: ' + minQty + '</span>' : '') +
                    (offer.to_date ? '<span class="detail-tag expiry">' + expiryText + '</span>' : '') +
                '</div>' +
                '<div class="price-box">' +
                    '<span class="val">' + amountText + '</span>' +
                    '<span class="lab">' + amountLabel + '</span>' +
                '</div>' +
            '</div>';
        track.appendChild(slide);
    });
    cur = 0;
    move(0);
}

function move(dir) {
    var track = document.getElementById("offer-track");
    var bar = document.getElementById("progress-bar");
    if (!track) return;
    var total = Math.max(OFFERS.length, 1);
    cur = (cur + dir + total) % total;
    track.style.transform = "translateX(-" + (cur * 100) + "%)";
    if (bar) {
        bar.style.transition = "none";
        bar.style.width = "0%";
        setTimeout(function() {
            bar.style.transition = "width " + SPEED + "ms linear";
            bar.style.width = "100%";
        }, 50);
    }
}

function startAuto() {
    clearInterval(timer);
    var label = document.getElementById("timer-label");
    if (OFFERS.length <= 1) {
        if (label) { label.textContent = OFFERS.length === 1 ? "Only one offer available" : "No offers available"; }
        return;
    }
    if (label) label.textContent = "Next offer in 15s";
    timer = setInterval(function() { move(1); }, SPEED);
}

function bindButtons() {
    var prev = document.getElementById("btn-prev");
    var next = document.getElementById("btn-next");
    if (prev) { prev.onclick = function() { move(-1); startAuto(); }; }
    if (next) { next.onclick = function() { move(1); startAuto(); }; }
}

// v17 FIX: frappe.desk.reportview.get does NOT always return the same shape.
// Sometimes it is {keys:[...], values:[[...]]} (row arrays), sometimes a plain
// array of objects. The old code did (msg.values || []).map(...) - when message
// was an ARRAY, msg.values resolved to Array.prototype.values, the built-in
// iterator FUNCTION, which has no .map. Hence:
//   "TypeError: (pricingMsg.values || []).map is not a function"
// This normalises both shapes to an array of plain objects keyed by fieldname,
// which also removes the fragile positional v[0], v[1]... indexing.
function rvRows(msg){
    if(!msg) return [];
    if(Array.isArray(msg)){
        // Already a list of row objects (or row arrays with no keys).
        return msg.map(function(r){ return Array.isArray(r) ? {} : (r || {}); });
    }
    var vals = msg.values;
    if(!Array.isArray(vals)) return [];
    var keys = Array.isArray(msg.keys) ? msg.keys : [];
    return vals.map(function(row){
        if(!Array.isArray(row)) return row || {};
        var o = {};
        for(var i = 0; i < keys.length; i++){
            // keys can arrive as "tabX.field" or plain "field"
            var k = String(keys[i] || "").split(".").pop().replace(/`/g, "");
            o[k] = row[i];
        }
        return o;
    });
}

function loadOffers() {
