                    "`tabTherapy Plan Offer`.`to_date`", "`tabTherapy Plan Offer`.`is_active`",
                    "`tabTherapy Plan Offer`.`creation`"
                ],
                filters: [["Therapy Plan Offer", "is_active", "=", 1]],
                order_by: "`tabTherapy Plan Offer`.`to_date` asc",
                page_length: 100
            }
        });
        var pricingRuleCall = frappe.call({
            method: "frappe.desk.reportview.get",
            args: {
                doctype: "Pricing Rule",
                fields: [
                    "`tabPricing Rule`.`name`", "`tabPricing Rule`.`title`", "`tabPricing Rule`.`apply_on`",
                    "`tabPricing Rule`.`min_qty`", "`tabPricing Rule`.`rate`", "`tabPricing Rule`.`discount_amount`",
                    "`tabPricing Rule`.`discount_percentage`", "`tabPricing Rule`.`currency`", "`tabPricing Rule`.`valid_from`",
                    "`tabPricing Rule`.`valid_upto`", "`tabPricing Rule`.`disable`", "`tabPricing Rule`.`selling`",
                    "`tabPricing Rule`.`creation`", "`tabPricing Rule`.`modified`"
                ],
                filters: [
                    ["Pricing Rule", "disable", "=", 0],
                    ["Pricing Rule", "selling", "=", 1],
                    ["Pricing Rule", "valid_from", "<=", todayIso()],
                    ["Pricing Rule", "valid_upto", ">=", todayIso()]
                ],
                order_by: "`tabPricing Rule`.`valid_upto` asc",
                start: 0,
                page_length: 100,
                view: "List",
                group_by: null,
                with_comment_count: 0
            }
        });
        Promise.all([therapyOfferCall, pricingRuleCall]).then(function(results) {
            var therapyRes = results[0];
            var pricingRes = results[1];
            var therapyRows = rvRows(therapyRes.message);
            var pricingRows = rvRows(pricingRes.message);
            var therapyOffers = therapyRows.map(function(v) {
                return {
                    source_doctype: "Therapy Plan Offer",
                    name: v.name,
                    offer_name: v.offer_name,
                    therapy_plan_template: v.therapy_plan_template,
                    offer_type: v.offer_type,
                    discount_amount: v.discount_amount,
                    offer_price: v.offer_price,
                    including_gst: v.including_gst,
                    from_date: v.from_date,
                    to_date: v.to_date,
                    is_active: v.is_active,
                    creation: v.creation
                };
            }).filter(isOfferCurrentlyValid);
            var pricingOffers = pricingRows.map(function(v) {
                return {
                    source_doctype: "Pricing Rule",
                    name: v.name,
                    offer_name: v.title || v.name,
                    therapy_plan_template: "",
                    offer_type: "Pricing Rule",
                    apply_on: v.apply_on,
                    min_qty: v.min_qty,
                    rate: v.rate,
                    discount_amount: v.discount_amount,
                    discount_percentage: v.discount_percentage,
                    currency: v.currency,
                    from_date: v.valid_from,
                    to_date: v.valid_upto,
                    valid_from: v.valid_from,
                    valid_upto: v.valid_upto,
                    disable: v.disable,
                    selling: v.selling,
                    creation: v.creation,
                    modified: v.modified,
                    item_names: ""
                };
            }).filter(isPricingRuleCurrentlyValid);
            var promises = pricingOffers.map(function(offer) {
                return getPricingRuleItems(offer.name).then(function(items) {
                    offer.item_names = items;
                    return offer;
                });
            });
            return Promise.all(promises).then(function(updatedPricingOffers) {
                var manualOffers = MANUAL_OFFERS.filter(isManualOfferCurrentlyValid).filter(function(manual) {
                    var manualName = String(manual.offer_name || "").trim().toLowerCase();
                    var alreadyExists = therapyOffers.concat(updatedPricingOffers).some(function(existing) {
                        var existingName = String(existing.offer_name || "").trim().toLowerCase();
                        return existingName && existingName === manualName;
                    });
                    return !alreadyExists;
                });
                OFFERS = therapyOffers.concat(updatedPricingOffers).concat(manualOffers).sort(function(a, b) {
                    var ad = a.to_date || "9999-12-31";
                    var bd = b.to_date || "9999-12-31";
                    return String(ad).localeCompare(String(bd));
                });
                renderOffers();
                startAuto();
            });
        }).catch(function(e) {
            ("Unable to load carousel offers:", e, void 0);
            renderEmpty("Unable to load offers. Please check permissions or field names.");
        });
    } catch(e) {
        ("Unable to load carousel offers:", e, void 0);
        renderEmpty("Unable to load offers. Please check permissions or field names.");
    }
}

