function getMonday(d){
    var date = new Date(d);
    var day = date.getDay();
    var diff = (day === 0 ? -6 : 1) - day;
    date.setDate(date.getDate() + diff);
    date.setHours(0,0,0,0);
    return date;
}

function addDays(d, n){
    var nd = new Date(d); nd.setDate(nd.getDate()+n); return nd;
}

function fmtDate(d){
    return d.getFullYear() + '-' + String(d.getMonth()+1).padStart(2,'0') + '-' + String(d.getDate()).padStart(2,'0');
}

function csrf(){
    return (window.frappe && window.frappe.csrf_token) ? window.frappe.csrf_token : '';
}

function apiGetList(doctype, filters, fields, limit, orderBy){
    var body = {
        doctype: doctype,
        filters: JSON.stringify(filters || []),
        fields: JSON.stringify(fields || ['name']),
        limit_page_length: limit || 1000
    };
    if (orderBy) body.order_by = orderBy;
    return fetch('/api/method/frappe.client.get_list', {
        method: 'POST',
        credentials: 'include',
        headers: {
            'Content-Type': 'application/x-www-form-urlencoded',
            'X-Frappe-CSRF-Token': csrf()
        },
        body: Object.keys(body).map(function(k){
            return encodeURIComponent(k) + '=' + encodeURIComponent(body[k]);
        }).join('&')
    }).then(function(r){ return r.json(); }).then(function(j){
        if (j.exc) throw new Error(j._server_messages || j.exception || j.exc);
        return j.message || [];
    });
}

// v17: fetch employees via permission-bypassing server script so branch
// logins see ALL active staff of the branch (User Permission on `user_id`
// otherwise hides employees whose linked user the login can't see).
// Pass branch='' (or 'ALL') to get every active employee across branches.
function fetchRosterEmployees(branch){
    var qs = '?branch=' + encodeURIComponent(branch || 'ALL');
    return fetch('/api/method/roster_employees' + qs, {
        method: 'GET', credentials: 'include',
        headers: { 'X-Frappe-CSRF-Token': csrf() }
    }).then(function(r){ return r.json(); }).then(function(j){
        if (j.exc) throw new Error(j._server_messages || j.exception || j.exc);
        return j.message || [];
    });
}

