function loadSubmissionStatus(){
    var container = document.querySelector('#lscc-rp-status-cards');
    if (!container) return;
    container.innerHTML = '<div class="lscc-rp-status-loading">Checking branch statuses...</div>';

    var today      = new Date();
    var weekStart  = getMonday(today);
    var weekEnd    = addDays(weekStart, 6);
    var monthStart = new Date(today.getFullYear(), today.getMonth(), 1);
    var monthEnd   = new Date(today.getFullYear(), today.getMonth()+1, 0);
    var wS = fmtDate(weekStart), wE = fmtDate(weekEnd);
    var mS = fmtDate(monthStart), mE = fmtDate(monthEnd);

    var daysUntilFri = (5 - today.getDay() + 7) % 7 || 7;
    var nextFri = addDays(today, daysUntilFri);
    var friLabel = nextFri.toLocaleDateString('en-IN', {day:'numeric', month:'short'});
    var monthEndDay = monthEnd.getDate();

    apiGetList('Branch', [], ['name'], 100, 'name asc').then(function(branches){
        var filteredBranches = branches.filter(function(b){ return EXCLUDED_BRANCHES.indexOf(b.name) === -1; });

        return fetchRosterEmployees('ALL').then(function(allEmps){
            var emps = allEmps.filter(function(e){ return EXCLUDED_BRANCHES.indexOf(e.branch) === -1; });
            var branchEmps = {};
            emps.forEach(function(e){
                if (!branchEmps[e.branch]) branchEmps[e.branch] = [];
                branchEmps[e.branch].push(e.name);
            });
            var allEmpNames = emps.map(function(e){ return e.name; });
            if (!allEmpNames.length){ container.innerHTML = '<div class="lscc-rp-status-loading">No active employees.</div>'; return; }

            return Promise.all([
                apiGetList('Shift Assignment',
                    [['employee','in',allEmpNames],['start_date','>=',wS],['start_date','<=',wE],['docstatus','=',1],['shift_type','!=','Week Off']],
                    ['employee'], 5000),
                apiGetList('Shift Assignment',
                    [['employee','in',allEmpNames],['start_date','>=',mS],['start_date','<=',mE],['docstatus','=',1],['shift_type','!=','Week Off']],
                    ['employee'], 20000)
            ]).then(function(results){
                var wMap = {}, mMap = {};
                results[0].forEach(function(r){ wMap[r.employee] = (wMap[r.employee]||0)+1; });
                results[1].forEach(function(r){ mMap[r.employee] = (mMap[r.employee]||0)+1; });

                container.innerHTML = '';
                filteredBranches.forEach(function(b){
                    var empList = branchEmps[b.name] || [];
                    if (!empList.length) return;
                    var total = empList.length;
                    var wDone = empList.filter(function(e){ return (wMap[e]||0) >= 5; }).length;
                    var mDone = empList.filter(function(e){ return (mMap[e]||0) >= 20; }).length;

                    var card = document.createElement('div');
                    card.className = 'lscc-rp-status-card';
                    card.innerHTML =
                        '<div class="lscc-rp-status-card-name">' + b.name + '</div>' +
                        '<div class="lscc-rp-status-row ' + (wDone===total?'lscc-rp-status-ok':'lscc-rp-status-warn') + '">' +
                            '<span class="lscc-rp-status-icon">' + (wDone===total?'✓':'⚠') + '</span>' +
                            '<span>Weekly Roster: ' + (wDone===total ? 'Submitted' : 'Pending — due '+friLabel) + ' ('+wDone+'/'+total+')</span></div>' +
                        '<div class="lscc-rp-status-row ' + (mDone===total?'lscc-rp-status-ok':'lscc-rp-status-warn') + '">' +
                            '<span class="lscc-rp-status-icon">' + (mDone===total?'✓':'⚠') + '</span>' +
                            '<span>Monthly Roster: ' + (mDone===total ? 'Submitted' : 'Pending — due '+monthEndDay+'th') + ' ('+mDone+'/'+total+')</span></div>';
                    container.appendChild(card);
                });
            });
        });
    }).catch(function(err){
        container.innerHTML = '<div class="lscc-rp-status-loading" style="color:#e87a7a">Error: ' + err.message + '</div>';
    });
}

function initBranchSelect(){
    var sel = document.querySelector('#lscc-rp-branch');
    if(!sel) return;
    sel.addEventListener('change', function(){
        rosterState.branch = sel.value;
        loadWeek();
        loadMonthlySummary();
    });
    apiGetList('Branch', [], ['name'], 100, 'name asc').then(function(rows){
        rows.forEach(function(r){
            if (EXCLUDED_BRANCHES.indexOf(r.name) !== -1) return;
            var opt = document.createElement('option');
            opt.value = r.name; opt.textContent = r.name;
            sel.appendChild(opt);
        });
        // v16: the roster now follows the header branch selector.
        // Hide ONLY the select itself - it is a direct child of
        // .lscc-rp-header, which also holds Prev/Next/Refresh and the week
        // label, so hiding the parent would wipe out the roster controls.
        syncRosterToBranch();
