            var tag = document.createElement('span');
            tag.id = 'lscc-rp-branch-tag';
            tag.className = 'lscc-rp-branch-tag';
            tag.textContent = curBranch || '';
            sel.parentNode.insertBefore(tag, sel);
        }
    }).catch(function(err){ ('[Roster] Branch fetch failed:', err, void 0); });
}

// v16.1: push the header's selected branch into the roster and reload it.
function syncRosterToBranch(){
    if(!curBranch) return;
    var sel = document.querySelector('#lscc-rp-branch');
    if (sel) sel.value = curBranch;
    rosterState.branch = curBranch;
    var tag = document.getElementById('lscc-rp-branch-tag');
