function updateWeekLabel(){
    var end = addDays(rosterState.weekStart, 6);
    var opts = {day:'numeric', month:'short'};
    var label = document.querySelector('#lscc-rp-weeklabel');
    if (label) {
        label.textContent = rosterState.weekStart.toLocaleDateString('en-IN', opts) + ' – ' + end.toLocaleDateString('en-IN', opts) + ', ' + end.getFullYear();
    }
}

function loadWeek(){
    if(!rosterState.branch && curBranch) rosterState.branch = curBranch;
    updateWeekLabel();
    var content = document.querySelector('#lscc-rp-content');
    if (!rosterState.branch){
        content.className = 'lscc-rp-empty';
        content.textContent = 'Select a branch to load the roster.';
        return;
    }
    content.className = 'lscc-rp-empty';
    content.textContent = 'Loading employees...';

    fetchRosterEmployees(rosterState.branch)
    .then(function(emps){
        rosterState.employees = emps;
        if (!emps.length){
            content.className = 'lscc-rp-empty';
            content.textContent = 'No active employees found for ' + rosterState.branch + '.';
            return;
        }
        var empNames = emps.map(function(e){ return e.name; });
        var wS = fmtDate(rosterState.weekStart), wE = fmtDate(addDays(rosterState.weekStart,6));
        return Promise.all([
            apiGetList('Shift Assignment',
                [['employee','in',empNames],['start_date','>=',wS],['start_date','<=',wE],['docstatus','=',1]],
                ['name','employee','start_date','shift_type'], 2000),
            apiGetList('Attendance',
                [['employee','in',empNames],['attendance_date','>=',wS],['attendance_date','<=',wE],['docstatus','!=',2]],
                ['employee','attendance_date','custom_check_in_time','custom_check_out_time','status'], 2000),
            apiGetList('Leave Application',
                [['employee','in',empNames],['from_date','<=',wE],['to_date','>=',wS],['status','=','Approved'],['docstatus','=',1]],
                ['employee','from_date','to_date','leave_type'], 1000)
        ]).then(function(res){ buildShiftMap(res[0]); buildCheckinMap(res[1]); buildLeaveMap(res[2], wS, wE); renderTable(); });
    }).catch(function(err){
        content.className = 'lscc-rp-empty';
        content.textContent = 'Error: ' + err.message;
    });
}

function buildShiftMap(rows){
    var map = {};
    rows.forEach(function(r){
        if (!map[r.employee]) map[r.employee] = {};
        map[r.employee][r.start_date] = { name: r.name, shift_type: r.shift_type };
    });
    rosterState.shiftMap = map;
}

function buildCheckinMap(rows){
    var map = {};
    rows.forEach(function(r){
        if (!map[r.employee]) map[r.employee] = {};
        map[r.employee][r.attendance_date] = {
            in:  r.custom_check_in_time  ? r.custom_check_in_time.slice(11,16)  : null,
            out: r.custom_check_out_time ? r.custom_check_out_time.slice(11,16) : null,
            status: r.status
        };
    });
    rosterState.checkinMap = map;
}

function buildLeaveMap(rows, wS, wE){
    var map = {};
    rows.forEach(function(r){
        var cur = new Date(r.from_date);
        var end = new Date(r.to_date);
        var weekEnd = new Date(wE);
        var weekStart = new Date(wS);
        while (cur <= end){
            if (cur >= weekStart && cur <= weekEnd){
                var ds = fmtDate(cur);
                if (!map[r.employee]) map[r.employee] = {};
                map[r.employee][ds] = r.leave_type || 'Leave';
            }
            cur.setDate(cur.getDate()+1);
        }
    });
    rosterState.leaveMap = map;
}

function buildEmpRow(emp, dayDates){
    var row = document.createElement('tr');
    var ec = document.createElement('td'); ec.className = 'lscc-rp-empcell';
    ec.innerHTML = '<div class="lscc-rp-empname">'+emp.employee_name+'</div>'+
        '<div class="lscc-rp-empmeta">'+emp.name+(emp.designation?' &middot; '+emp.designation:'')+'</div>';
    row.appendChild(ec);

    dayDates.forEach(function(d){
        var dateStr = fmtDate(d);
        var cell = document.createElement('td');
        var existing = (rosterState.shiftMap[emp.name]||{})[dateStr];

        var sel = document.createElement('select'); sel.className = 'lscc-rp-shiftselect';
        SHIFT_OPTIONS.forEach(function(o){
            var op = document.createElement('option'); op.value=o.value; op.textContent=o.label;
            if (existing && existing.shift_type===o.value) op.selected=true;
            if (!existing && o.value==='') op.selected=true;
            sel.appendChild(op);
        });
        var sDiv = document.createElement('div'); sDiv.className='lscc-rp-saving'; sDiv.style.display='none';
        sel.addEventListener('change', function(){ saveShift(emp, dateStr, sel, sDiv); });
        cell.appendChild(sel); cell.appendChild(sDiv);

        var ck       = (rosterState.checkinMap[emp.name]||{})[dateStr];
        var shift    = (rosterState.shiftMap[emp.name]||{})[dateStr];
        var leaveTyp = (rosterState.leaveMap[emp.name]||{})[dateStr];
        var isWeekOff = shift && shift.shift_type === 'Week Off';
        var aDiv = document.createElement('div');
        if (ck && ck.in){
            aDiv.className='lscc-rp-actual present';
            aDiv.textContent = ck.in+(ck.out?' – '+ck.out:' – (no out)');
        } else if (isWeekOff){
            aDiv.className='lscc-rp-actual';
            aDiv.style.background='rgba(170,170,170,.1)';
            aDiv.style.color='#aaaaaa';
            aDiv.textContent='Week Off';
        } else if (leaveTyp){
            aDiv.className='lscc-rp-actual partial';
            aDiv.style.background='rgba(74,144,217,.12)';
            aDiv.style.color='#4a90d9';
            aDiv.textContent=leaveTyp;
        } else if (ck && ck.status && ck.status==='On Leave'){
            aDiv.className='lscc-rp-actual partial';
            aDiv.style.background='rgba(74,144,217,.12)';
            aDiv.style.color='#4a90d9';
            aDiv.textContent='On Leave';
        } else {
            var isFuture = d > new Date();
            if (isFuture){
                aDiv.className='lscc-rp-actual'; aDiv.textContent='--';
            } else {
                aDiv.className='lscc-rp-actual absent'; aDiv.textContent='Absent';
            }
        }
        cell.appendChild(aDiv);
        row.appendChild(cell);
    });
    return row;
}

