function saveShift(emp, dateStr, selectEl, statusDiv){
    var newVal = selectEl.value;
    var existing = (rosterState.shiftMap[emp.name]||{})[dateStr];
    selectEl.disabled=true; statusDiv.style.display='block';
    statusDiv.textContent='Saving...'; statusDiv.style.color='#f4c542';

    var chain = apiGetList('Shift Assignment',
        [['employee','=',emp.name],['start_date','<=',dateStr],['end_date','>=',dateStr],['docstatus','=',1]],
        ['name','start_date','end_date'], 50
    ).then(function(overlapping){
        var cancelChain = Promise.resolve();
        overlapping.forEach(function(r){
            if (r.start_date === r.end_date){
                cancelChain = cancelChain.then(function(){ return apiCancel('Shift Assignment', r.name); });
            } else {
                cancelChain = cancelChain.then(function(){
                    return apiCancel('Shift Assignment', r.name).catch(function(err){
                        var msg = (err && err.message) ? err.message : '';
                        if (msg.indexOf('Employee Checkin') !== -1 || msg.indexOf('linked') !== -1){
                            throw new Error(
                                'Flexible Shift is linked to biometric data and cannot be auto-cancelled. ' +
                                'Please run "04_cancel_flexible_shifts.py" once in System Console, then try again.'
                            );
                        }
                        throw err;
                    });
                });
            }
        });
        return cancelChain;
    });

    if (newVal){
        chain = chain.then(function(){
            return apiInsert({doctype:'Shift Assignment',employee:emp.name,company:emp.company,
                shift_type:newVal,start_date:dateStr,end_date:dateStr,status:'Active'})
            .then(function(ins){ return apiSubmit(ins); })
            .then(function(sub){
                if (!rosterState.shiftMap[emp.name]) rosterState.shiftMap[emp.name]={};
                rosterState.shiftMap[emp.name][dateStr]={name:sub.name,shift_type:newVal};
            });
        });
    } else {
        chain = chain.then(function(){ if (rosterState.shiftMap[emp.name]) delete rosterState.shiftMap[emp.name][dateStr]; });
    }
    chain.then(function(){
        statusDiv.textContent='✓ Saved'; statusDiv.style.color='#5fd584';
        setTimeout(function(){ statusDiv.style.display='none'; }, 1800);
        loadSubmissionStatus();
        loadMonthlySummary();
    }).catch(function(err){
        statusDiv.textContent='Error: '+(err.message||'failed'); statusDiv.style.color='#e87a7a';
    }).finally(function(){ selectEl.disabled=false; });
}

function initMonthNav(){
    var MONTHS = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
    var thisYear = new Date().getFullYear();

    function renderNav(){
        var yearLabel = document.querySelector('#lscc-year-label');
        if (yearLabel) yearLabel.textContent = rosterState.selectedYear;

        var btns = document.querySelectorAll('#lscc-month-btns button');
        btns.forEach(function(btn){
            var m = parseInt(btn.getAttribute('data-m'));
            btn.classList.toggle('active', m === rosterState.selectedMonth);
            var isFuture = rosterState.selectedYear === thisYear && m > new Date().getMonth();
            btn.disabled = isFuture;
        });

        var nextYearBtn = document.querySelector('#lscc-year-next');
        if (nextYearBtn) nextYearBtn.disabled = (rosterState.selectedYear >= thisYear);
    }

    var prevBtn = document.querySelector('#lscc-year-prev');
    var nextBtn = document.querySelector('#lscc-year-next');

    if (prevBtn) {
        prevBtn.addEventListener('click', function(){
            rosterState.selectedYear--;
            renderNav();
            loadMonthlySummary();
        });
    }
    if (nextBtn) {
        nextBtn.addEventListener('click', function(){
            if (rosterState.selectedYear < thisYear){ rosterState.selectedYear++; renderNav(); loadMonthlySummary(); }
        });
    }

    var monthBtns = document.querySelectorAll('#lscc-month-btns button');
    monthBtns.forEach(function(btn){
        btn.addEventListener('click', function(){
            var m = parseInt(btn.getAttribute('data-m'));
            if (btn.disabled) return;
            rosterState.selectedMonth = m;
            renderNav();
            loadMonthlySummary();
        });
    });

    renderNav();
}

function loadMonthlySummary(){
    if (!rosterState.branch) return;
    var wrap = document.querySelector('#lscc-monthly-wrap');
    var content = document.querySelector('#lscc-monthly-content');
    var titleEl = document.querySelector('#lscc-monthly-title');
    if (!wrap || !content) return;

    wrap.style.display = 'block';
    content.className = 'lscc-rp-empty';
    content.textContent = 'Loading monthly summary...';

    var yr = rosterState.selectedYear, mo = rosterState.selectedMonth;
    var mS = fmtDate(new Date(yr, mo, 1));
    var mE = fmtDate(new Date(yr, mo+1, 0));
    var monthName = new Date(yr, mo, 1).toLocaleDateString('en-IN', {month:'long', year:'numeric'});
    if (titleEl) titleEl.textContent = 'Monthly Roster Summary — ' + monthName + ' — ' + rosterState.branch;

    fetchRosterEmployees(rosterState.branch)
    .then(function(emps){
        if (!emps.length){ content.textContent='No active employees.'; return; }
        var empNames = emps.map(function(e){ return e.name; });

        return Promise.all([
            apiGetList('Shift Assignment',
                [['employee','in',empNames],['start_date','>=',mS],['start_date','<=',mE],['docstatus','=',1]],
                ['employee','shift_type'], 10000),
            apiGetList('Attendance',
                [['employee','in',empNames],['attendance_date','>=',mS],['attendance_date','<=',mE],['docstatus','!=',2]],
                ['employee','status','late_entry'], 10000)
        ]).then(function(res){
            var shiftStats = {};
            res[0].forEach(function(r){
                if (!shiftStats[r.employee]) shiftStats[r.employee] = {planned:0, weekoff:0, training:0};
                if (r.shift_type === 'Week Off') shiftStats[r.employee].weekoff++;
                else if (r.shift_type && r.shift_type.toLowerCase().indexOf('training') !== -1) shiftStats[r.employee].training++;
                else shiftStats[r.employee].planned++;
            });

            var attStats = {};
            res[1].forEach(function(r){
                if (!attStats[r.employee]) attStats[r.employee] = {present:0, late:0, absent:0, leave:0};
                var s = r.status;
                if (s === 'Present'){
                    attStats[r.employee].present++;
                    if (r.late_entry) attStats[r.employee].late++;
                } else if (s === 'Absent') attStats[r.employee].absent++;
                else if (s === 'On Leave' || s === 'Half Day') attStats[r.employee].leave++;
            });

            content.className = ''; content.innerHTML = '';
            var table = document.createElement('table');
            table.className = 'lscc-monthly-table';

            var cols = [
                {label:'Employee Details', cls:'lscc-m-empcol'},
                {label:'Planned Working Days', cls:''},
                {label:'Present', cls:''},
                {label:'Late', cls:''},
                {label:'Absent', cls:''},
                {label:'Leave', cls:''},
                {label:'Weekly Off', cls:''},
                {label:'Training', cls:''}
            ];
            var thead = document.createElement('thead');
            var hRow = document.createElement('tr');
            cols.forEach(function(c){
                var th = document.createElement('th');
                if (c.cls) th.className = c.cls;
                th.textContent = c.label;
                hRow.appendChild(th);
            });
            thead.appendChild(hRow); table.appendChild(thead);

            var tbody = document.createElement('tbody');
            emps.forEach(function(emp){
                var ss = shiftStats[emp.name] || {planned:0, weekoff:0, training:0};
                var as = attStats[emp.name]  || {present:0, late:0, absent:0, leave:0};

                var row = document.createElement('tr');

                var ec = document.createElement('td'); ec.className = 'lscc-m-empcell lscc-rp-empcell';
                ec.innerHTML = '<div class="lscc-rp-empname">'+emp.employee_name+'</div>'+
                    '<div class="lscc-rp-empmeta">'+emp.name+(emp.designation?' &middot; '+emp.designation:'')+(emp.branch?' &middot; '+emp.branch:'')+'</div>';
                row.appendChild(ec);

                function mkCell(val, cls){
                    var td = document.createElement('td');
                    td.className = val === 0 ? 'lscc-m-val-zero' : cls;
                    td.textContent = val;
                    return td;
                }

                row.appendChild(mkCell(ss.planned,   ''));
                row.appendChild(mkCell(as.present,   'lscc-m-val-green'));
                row.appendChild(mkCell(as.late,       'lscc-m-val-yellow'));
                row.appendChild(mkCell(as.absent,     'lscc-m-val-red'));
                row.appendChild(mkCell(as.leave,      'lscc-m-val-blue'));
                row.appendChild(mkCell(ss.weekoff,    'lscc-m-val-gray'));
                row.appendChild(mkCell(ss.training,   'lscc-m-val-orange'));

                tbody.appendChild(row);
            });
            table.appendChild(tbody); content.appendChild(table);
        });
    }).catch(function(err){
        content.className='lscc-rp-empty';
        content.textContent='Error loading monthly summary: '+err.message;
    });
}

