/* ===================== VISITED → CREATE CLIENT (merged) ===================== */
/* Shares frappe.ready scope: uses $, esc, toast, D, curBranch, wkCommit, wkSet */


  // Fallbacks in case these helpers are scoped away (they are global on BCC).

  /* ---- mobile normaliser (ported from new-client-registration) ---- */
  function normMobile(raw){
    var m = String(raw||"").replace(/[^\d]/g,"");
    if(/^\d{10}$/.test(m)) return m;
    if(/^91\d{10}$/.test(m)) return m.slice(2);
    return m;
  }
  function fmtName(v){
    v = String(v||"").trim().replace(/[^a-zA-Z\s.']/g,"").replace(/\s+/g," ").trim();
    if(!v) return "";
    return v.split(" ").map(function(p){ return p ? p.charAt(0).toUpperCase()+p.slice(1).toLowerCase() : ""; }).join(" ");
  }

  /* ---- Lead -> Patient field mapping (mirrors saveClient in new-client-registration) ---- */
  function riskToFlag(level){
    if(level==="Normal")          return {flag:"Green Flag",  sev:"Controlled"};
    if(level==="Controlled")      return {flag:"Green Flag",  sev:"Controlled"};
    if(level==="Medical History") return {flag:"Orange Flag", sev:"Controlled"};
    if(level==="Active Condition")return {flag:"Red Flag",    sev:"Serious"};
    if(level==="High Risk")       return {flag:"Red Flag",    sev:"Serious"};
    return {flag:"", sev:""};
  }

