      }).then(function(r){
        var d = (r && r.message) || {};
        buildModal(i, w, d, emp, wantStatus);
      }).catch(function(e){
        toast("Could not load lead \u2014 "+((e&&e.message)||"server error"));
      });
    }

    // Employee was already selected in wkChange: skip the duplicate modal.
    if(selectedEmployee){
      loadLeadAndOpen(selectedEmployee);
      return;
    }

    // Fallback for older/direct callers.
    askStatusUpdate({
      title: wantStatus + " \u2014 " + (w.n || w.id),
      status: wantStatus,
      walkin: w,
      needReason: (wantStatus === "Visited Not Booked"),
      reasonLabel: "Reason",
      onSave: function(res){ loadLeadAndOpen((res && res.employee) || ""); }
    });
  }

