    else if(String(leadEnquiry).toLowerCase().indexOf('skin')>-1) $('vcc-dept').value='Skin';
    var toggle = $('vcc-lead-toggle'), body = $('vcc-lead-body'), caret = $('vcc-lead-caret');
    if(toggle){ toggle.onclick = function(){
