    ov.addEventListener('click', function(e){ if(e.target===ov) close(); });
    $('vcc-cancel').onclick = close;
    $('vcc-mobile').addEventListener('input', function(){ this.value = this.value.replace(/[^\d+]/g,'').slice(0,13); });
    $('vcc-save').onclick = function(){ saveVisitedClient(i, w, close, emp, d); };
