  /* ---- dynamic field renderer for auto-pulled Lead fields ---- */
  function dynFld(df, val){
    var id = 'vccdyn-' + df.fieldname;
    var label = esc(df.label || df.fieldname);
    var ftype = df.fieldtype;
    var full = (ftype === 'Text' || ftype === 'Small Text' || ftype === 'Long Text' || ftype === 'Text Editor' || ftype === 'Code' || ftype === 'Markdown Editor');
    var inner;
    if(ftype === 'Select'){
      var opts = String(df.options || '').split('\n');
      inner = '<select id="'+id+'" data-fn="'+esc(df.fieldname)+'" '+INP+'>'+opts.map(function(o){
        return '<option value="'+esc(o)+'"'+(String(o)===String(val)?' selected':'')+'>'+(o===''?'\u2014 select \u2014':esc(o))+'</option>';
      }).join('')+'</select>';
    } else if(ftype === 'Check'){
      inner = '<select id="'+id+'" data-fn="'+esc(df.fieldname)+'" '+INP+'>'+
        '<option value="0"'+(String(val)==='0'||val===0||!val?' selected':'')+'>No</option>'+
        '<option value="1"'+(String(val)==='1'||val===1?' selected':'')+'>Yes</option></select>';
    } else if(ftype === 'Date'){
      inner = '<input id="'+id+'" data-fn="'+esc(df.fieldname)+'" type="date" value="'+esc(String(val).slice(0,10))+'" '+INP+'>';
    } else if(ftype === 'Datetime'){
      inner = '<input id="'+id+'" data-fn="'+esc(df.fieldname)+'" type="text" value="'+esc(val)+'" placeholder="YYYY-MM-DD HH:MM:SS" '+INP+'>';
    } else if(ftype === 'Int' || ftype === 'Float' || ftype === 'Currency' || ftype === 'Percent'){
      inner = '<input id="'+id+'" data-fn="'+esc(df.fieldname)+'" inputmode="decimal" value="'+esc(val)+'" '+INP+'>';
    } else if(full){
      inner = '<textarea id="'+id+'" data-fn="'+esc(df.fieldname)+'" rows="2" '+INP+'>'+esc(val)+'</textarea>';
    } else {
      var ro = (ftype === 'Read Only') ? ' readonly' : '';
      inner = '<input id="'+id+'" data-fn="'+esc(df.fieldname)+'" value="'+esc(val)+'"'+ro+' '+INP+'>';
    }
    return '<div style="display:flex;flex-direction:column;gap:4px;"'+(full?'grid-column:1/-1;':'')+'">'+
      '<label style="font-size:10px;font-weight:800;letter-spacing:.6px;text-transform:uppercase;color:#5F6F63;">'+label+
      ' <span style="color:#9DB0A2;font-weight:600;text-transform:none;letter-spacing:0;">'+esc(df.fieldname)+'</span></label>'+inner+'</div>';
  }
    /* ---- small HTML builders ---- */
  var INP = 'style="border:1.5px solid #DCE9DE;border-radius:9px;padding:9px 11px;font-size:13px;width:100%;outline:none;background:#fff;"';
  function fld(label, inner){
  var lab = String(label).replace(/\*/g, '<span style="color:#D32F2F;">*</span>');
  return '<div style="display:flex;flex-direction:column;gap:4px;">'+
    '<label style="font-size:10px;font-weight:800;letter-spacing:.6px;text-transform:uppercase;color:#5F6F63;">'+lab+'</label>'+inner+'</div>';
}
function fldFull(label, inner){
  var lab = String(label).replace(/\*/g, '<span style="color:#D32F2F;">*</span>');
  return '<div style="grid-column:1/-1;display:flex;flex-direction:column;gap:4px;">'+
    '<label style="font-size:10px;font-weight:800;letter-spacing:.6px;text-transform:uppercase;color:#5F6F63;">'+lab+'</label>'+inner+'</div>';
}
  function sel(id, opts, cur){
    var o = opts.map(function(x){
      var label = x==="" ? "\u2014 select \u2014" : x;
      return '<option value="'+esc(x)+'"'+(x===cur?" selected":"")+'>'+esc(label)+'</option>';
    }).join("");
    return '<select id="'+id+'" '+INP+'>'+o+'</select>';
  }

  /* ---- department mappers (from new-client-registration) ---- */
  function mapVisitedFor(dept){
    if(dept==="Slimming") return "Slimming";
    if(dept==="Hair") return "Hair";
    if(dept==="Skin") return "Skin";
    if(dept==="Laser") return "Skin";
    return "";
  }
  function mapTreatmentCat(dept){
    if(dept==="Slimming") return "Slimming/Cryo";
    if(dept==="Hair") return "Hair / PRP / GFC";
    if(dept==="Skin"||dept==="Laser") return "Skin/Laser";
    return "";
  }

  /* ---- validate + insert Patient ---- */
  function saveVisitedClient(i, w, close, emp, leadOrig){
    var errEl = $("vcc-err");
    function showErr(m){ errEl.style.display="block"; errEl.textContent=m; }

    var name = fmtName($("vcc-name").value);
    var mob  = normMobile($("vcc-mobile").value);
    var area = String($("vcc-area").value||"").trim();
    var branch = String($("vcc-branch").value||"").trim();
    var risk = $("vcc-risk").value;

    if(!name || name.replace(/[^a-zA-Z]/g,"").length<2){ showErr("Enter a valid client name (min 2 letters)."); return; }
    if(!$("vcc-gender").value){ showErr("Gender is required."); $("vcc-gender").focus(); return; }
    if(!/^\d{10}$/.test(mob) || !/^[6-9]/.test(mob)){ showErr("Mobile must be 10 digits starting 6-9. Please re-check."); $("vcc-mobile").focus(); return; }
    var pdForm = String($("vcc-pdform").value||"").trim();
    if(!pdForm){ showErr("PD Form Number is required."); $("vcc-pdform").focus(); return; }
    if(!area){ showErr("Client area is required."); return; }
    if(!branch){ showErr("Branch is required."); return; }
    if(!risk){ showErr("Select a medical risk level."); return; }
    if($("vcc-apptstatus") && !$("vcc-apptstatus").value){ showErr("Select an appointment status."); $("vcc-apptstatus").focus(); return; }

    var rf = riskToFlag(risk);
    var dept = $("vcc-dept").value;
    var addr = [area, String($("vcc-addr").value||"").trim()].filter(Boolean).join(", ");

    var doc = {
      doctype:"Patient",
      custom_lead: (w && w.id) ? w.id : "",
      custom_pd_form_number: pdForm,
      first_name: name,
      sex: $("vcc-gender").value || "",
      mobile: mob,
      email: String($("vcc-email").value||"").trim(),
      custom_client_address: addr,
      custom_branch: branch,
      branch_name: branch,
      custom_client_visited_for_: mapVisitedFor(dept),
      custom_treatment_category: mapTreatmentCat(dept),
      custom_health_flag: rf.flag,
      custom_severity_update: rf.sev,
      custom_medical_history: (risk==="Normal") ? "Non-Medical" : "Medical",
      medical_history: String($("vcc-med").value||"").trim(),
      occupation: String($("vcc-occ").value||"").trim(),
      marital_status: $("vcc-marital").value || "",
      medication: String($("vcc-medic").value||"").trim(),
      custom_remarks: buildRemarks(w)
    };
    var _altNo = String($("vcc-alt").value||"").trim();
    if(_altNo){ doc.custom_remarks = (doc.custom_remarks?doc.custom_remarks+" | ":"") + "Alt No: " + _altNo; }
    // optional DOB (leave blank if not entered, per requirement)
    if($("vcc-dob").value) doc.dob = $("vcc-dob").value;

    // numeric fields — only send when a valid number is present (Patient uses Float)
    var hVal = parseFloat(String($("vcc-height").value||"").replace(/[^\d.]/g,""));
    if(!isNaN(hVal)) doc.custom_heightin_cm = hVal;
    var wVal = parseFloat(String($("vcc-weight").value||"").replace(/[^\d.]/g,""));
    if(!isNaN(wVal)) doc.custom_weightin_kg = wVal;
    var bVal = parseFloat(String($("vcc-bmi").value||"").replace(/[^\d.]/g,""));
    if(!isNaN(bVal)) doc.custom_bmi = bVal;

    // Link fields — only send when non-empty (blank string on a Link errors)
    var doctorVal = String($("vcc-doctor").value||"").trim();
    if(doctorVal) doc.custom_manager_name = doctorVal;   // Healthcare Practitioner
    var mediaVal = String($("vcc-media").value||"").trim();
    if(mediaVal) doc.custom_media = mediaVal;             // Lead Source

    var btn = $("vcc-save");
    btn.disabled = true; btn.textContent = "Checking\u2026";
    errEl.style.display="none";

    // helper: verify a Link value exists; if not, drop the key so insert won't fail
    function verifyLink(doctypeName, key){
      var val = doc[key];
      if(!val) return Promise.resolve();
      return frappe.call({
        method:"frappe.client.get_value",
        args:{ doctype:doctypeName, filters:{ name: val }, fieldname:"name" }
      }).then(function(r){
        if(!(r.message && r.message.name)){ delete doc[key]; }
      }).catch(function(){ delete doc[key]; });
    }

    // VCC_EXISTING_PATIENT_UPDATE_V2
    // If the mobile already belongs to a Patient:
    // 1. Show a warning.
    // 2. Update that Patient.
    // 3. Link the current Lead.
    // 4. Continue the appointment-status process.
    // 5. Do not create a duplicate Patient.

    frappe.call({
      method: "frappe.client.get_value",
      args: {
        doctype: "Patient",
        filters: {
          mobile: mob
        },
        fieldname: [
          "name",
          "patient_name",
          "custom_lead"
        ]
      }
    }).then(function(dr){

      var patientResult =
        (dr && dr.message)
          ? dr.message
          : {};

      var existingPatientName =
        patientResult.name || "";

      var existingPatientLabel =
        patientResult.patient_name ||
        existingPatientName ||
        "";

      var isExistingPatient =
        Boolean(existingPatientName);

      if(isExistingPatient){
        toast(
          "Warning: Client already exists — " +
          existingPatientLabel +
          ". Existing Client data will be updated."
        );

        errEl.style.display = "block";
        errEl.style.color = "#9A6700";
        errEl.style.background = "#FFF8E1";
        errEl.style.border = "1px solid #F4C430";
        errEl.style.padding = "9px 11px";
        errEl.style.borderRadius = "8px";

        errEl.textContent =
          "Client already exists: " +
          existingPatientLabel +
          ". Updating the existing Client; " +
          "duplicate registration will not be created.";

        btn.textContent =
          "Updating existing Client…";
      } else {
        btn.textContent =
          "Creating Client…";
      }


      // Validate optional Link fields before saving.
      return Promise.all([
        verifyLink(
          "Healthcare Practitioner",
          "custom_manager_name"
        ),
        verifyLink(
          "Lead Source",
          "custom_media"
        )
      ]).then(function(){

        var patientSaveCall;

        if(isExistingPatient){
          var updateValues = {};

          Object.keys(doc).forEach(function(key){
            if(key !== "doctype"){
              updateValues[key] = doc[key];
            }
          });

          // Connect the existing Patient to this walk-in Lead.
          if(w && w.id){
            updateValues.custom_lead = w.id;
          }

          patientSaveCall = frappe.call({
            method: "frappe.client.set_value",
            args: {
              doctype: "Patient",
              name: existingPatientName,
              fieldname: updateValues
            }
          });
        } else {
          patientSaveCall = frappe.call({
            method: "frappe.client.insert",
            args: {
              doc: doc
            }
          });
        }


        return patientSaveCall.then(function(r){

          var pname =
            existingPatientName ||
            (
              r &&
              r.message &&
              r.message.name
                ? r.message.name
                : ""
            );

          if(!pname){
            throw new Error(
              "Patient name was not returned after saving"
            );
          }

          if(w){
            w.patient = pname;
          }

          var apptSt =
            (
              $("vcc-apptstatus") &&
              $("vcc-apptstatus").value
            )
              ? $("vcc-apptstatus").value
              : "Visited";

          if(apptSt === "Cancelled"){
            showErr(
              "Cancelled is not available."
            );

            btn.disabled = false;
            btn.textContent =
              "✓ Save Client";

            return;
          }

          if(
            w &&
            !wkCanChangeTo(w, apptSt)
          ){
            showErr(
              wkLockedMessage(w)
            );

            btn.disabled = false;
            btn.textContent =
              "✓ Save Client";

            return;
          }


          // Capture edits made to Lead fields in the same form.
          var changes = {};

          var nodes =
            document.querySelectorAll(
              "#vcc-lead-body [data-fn]"
            );

          nodes.forEach(function(el){
            var fn =
              el.getAttribute("data-fn");

            if(!fn){
              return;
            }

            var newValue = el.value;

            var oldValue =
              (
                leadOrig &&
                leadOrig[fn] != null
              )
                ? leadOrig[fn]
                : "";

            if(
              String(newValue) !==
              String(oldValue)
            ){
              changes[fn] = newValue;
            }
          });


          function finishPatientSave(){

            var actionText =
              isExistingPatient
                ? "Client updated: "
                : "Client created: ";

