/* ---- rules ------------------------------------------------------------- */
const CLUSTER_MS = 10 * 60 * 1000;
const OUT_DUE_MS = 9 * 60 * 60 * 1000;
const DAY_OPEN = 6, DAY_CLOSE = 23;
const EARN_DAYS = 6;
const SCAN_BACK = 45;
const POLL_MS = 90000;
const PAGE = 5000;

/* ---- host page --------------------------------------------------------- */
