const HOST = branchSel() ? 'branch' : 'coo';

/* ---- helpers ----------------------------------------------------------- */
const esc  = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pad  = n => String(n).padStart(2, '0');
const dayS = d => d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());
const shift = (s, n) => dayS(new Date(new Date(s + 'T00:00:00').getTime() + n * 86400000));
const tms  = v => { const m = String(v || '').match(/(\d{4})-(\d{2})-(\d{2})[ T](\d{1,2}):(\d{2})(?::(\d{2}))?/); return m ? new Date(+m[1], +m[2]-1, +m[3], +m[4], +m[5], +(m[6]||0)).getTime() : null; };
const clock = t => t == null ? '\u2014' : pad(new Date(t).getHours()) + ':' + pad(new Date(t).getMinutes());
const hm = ms => { if (ms == null || ms <= 0) return '\u2014'; const m = Math.round(ms / 60000); return Math.floor(m/60) + 'h ' + pad(m % 60) + 'm'; };
const hDec = ms => (ms == null || ms <= 0) ? '' : Math.round(ms / 36000) / 100;
const span = (a, b) => (a == null || b == null || b <= a) ? '\u2014' : hm(b - a);
const monthKey = d => d.getFullYear() + '-' + pad(d.getMonth() + 1);
const lastDay = ym => new Date(+ym.slice(0,4), +ym.slice(5,7), 0).getDate();
const shortDate = s => new Date(s + 'T00:00:00').toLocaleDateString('en-IN', { day: 'numeric', month: 'short' });
const dowName = s => new Date(s + 'T00:00:00').toLocaleDateString('en-IN', { weekday: 'short' });

function jobAge(doj, refMs) {
  const a = tms((doj || '') + ' 00:00:00'); if (!a) return '';
  const s = new Date(a), e = new Date(refMs);
  let y = e.getFullYear() - s.getFullYear(), m = e.getMonth() - s.getMonth();
  if (e.getDate() - s.getDate() < 0) m--;
  if (m < 0) { m += 12; y--; }
  if (y > 0) return y + 'y ' + m + 'm';
  if (m > 0) return m + 'm';
  return Math.max(0, Math.round((e - a) / 86400000)) + 'd';
}
const initials = n => String(n || '?').trim().split(/\s+/).slice(0, 2).map(w => w[0]).join('').toUpperCase();

/* ---- rank badge -------------------------------------------------------- */
function badgeOf(desig, grade, branch) {
  const d = (desig + ' ' + (grade || '')).toLowerCase();
  if (/\bcoo\b|chief operating/.test(d))            return { s: 'COO', t: 'Chief Operating Officer', c: 'x' };
  if (/\bceo\b|chief executive/.test(d))            return { s: 'CEO', t: 'Chief Executive Officer', c: 'x' };
  if (/chairman|managing director|\bmd\b/.test(d))  return { s: 'MD',  t: 'Chairman / MD', c: 'x' };
  if (/general manager|\bgm\b/.test(d))             return { s: 'GM',  t: 'General Manager', c: 'x' };
  if (/cluster head|cluster manager/.test(d))       return { s: 'CH',  t: 'Cluster Head', c: 'a' };
  if (/area manager|regional manager/.test(d))      return { s: 'AM',  t: 'Area Manager', c: 'a' };
  if (/branch manager/.test(d))                     return { s: 'BM',  t: 'Branch Manager', c: 'b' };
  if (/cent(re|er) manager/.test(d))                return { s: 'CM',  t: 'Centre Manager', c: 'b' };
  if (/operation manager|operations manager/.test(d)) return { s: 'OM', t: 'Operation Manager', c: 'b' };
  if (/head|manager|incharge|in-charge|lead/.test(d)) return { s: 'MGR', t: desig, c: 'b' };
