const phoneKind = s => (s.custom_office_mobile || '').trim() ? 'Office' : ((s.cell_number || '').trim() ? 'Personal' : '');

/* ---- ERP access (read only, current user session) ----------------------- */
async function api(method, params = {}) {
  const q = new URLSearchParams();
  Object.entries(params).forEach(([k, v]) => q.set(k, typeof v === 'object' ? JSON.stringify(v) : String(v)));
  const r = await fetch('/api/method/' + method + '?' + q, { credentials: 'same-origin', headers: { Accept: 'application/json' } });
  if (!r.ok) throw Error(r.status === 403 ? 'ERP permission denied for this data.' : 'ERP request failed (' + r.status + ').');
  const j = await r.json();
  if (j.exc || j.exception) throw Error('ERP could not complete this request.');
  return j.message ?? j.data ?? j;
}
async function rows(doctype, fields, filters = [], order_by = 'name asc') {
  let out = [], start = 0;
  for (;;) {
    const page = await api('frappe.client.get_list', { doctype, fields: [...new Set(['name', ...fields])], filters, order_by, limit_start: start, limit_page_length: PAGE });
    if (!Array.isArray(page)) throw Error(doctype + ': unexpected ERP response.');
    out = out.concat(page);
    if (page.length < PAGE) break;
    start += page.length;
    if (start > 400000) break;
  }
  return out;
}

/* ---- punch engine ------------------------------------------------------ */
function clusterise(times) {
  const s = [...new Set(times.filter(t => t != null))].sort((a, b) => a - b), ev = [];
  s.forEach(t => { const l = ev[ev.length - 1]; if (l && t - l[l.length - 1] <= CLUSTER_MS) l.push(t); else ev.push([t]); });
  return ev;
}
