}
const attTimes = a => [tms(a.custom_check_in_time || a.in_time), tms(a.custom_check_out_time || a.out_time)].filter(v => v != null);
const dayClosed = date => date < dayS(new Date()) || new Date().getHours() >= DAY_CLOSE;

const ST = {
  ON_FLOOR:   { t: 'ON FLOOR',    c: 'on',    p: 1 },
  CHECKED_OUT:{ t: 'Checked out', c: 'out',   p: 1 },
  OUT_MISSING:{ t: 'OUT PUN MIS', c: 'miss',  p: 1 },
  UNVERIFIED: { t: 'Present \u00b7 no time', c: 'miss', p: 1 },
  HALF_DAY:   { t: 'Half day',    c: 'leave', p: 1 },
  LEAVE:      { t: 'On leave',    c: 'leave', p: 0 },
  LEAVE_REQ:  { t: 'Leave pending', c: 'leave', p: 0 },
  WEEK_OFF:   { t: 'Week off',    c: 'wo',    p: 0 },
  ABSENT:     { t: 'ABSENT',      c: 'abs',   p: 0 }
};

const EMP_FIELDS = ['employee_name','branch','designation','department','grade','employment_type',
  'date_of_joining','gender','image','custom_office_mobile','cell_number','attendance_device_id'];

function empFilter() {
