  if (HOST === 'branch') { const b = branchSel() && branchSel().value; if (b) f.push(['branch','=',b]); }
  return f;
}

async function readDay(date) {
  const [staff, punches, marked, offs, leaves] = await Promise.all([
    rows('Employee', EMP_FIELDS, empFilter(), 'employee_name asc'),
    rows('Employee Checkin', ['employee','log_type','time'], [['time','>=',date+' 00:00:00'],['time','<=',date+' 23:59:59']], 'time asc, name asc').catch(() => []),
    rows('Attendance', ['employee','status','in_time','out_time','custom_check_in_time','custom_check_out_time','docstatus','modified'], [['attendance_date','=',date],['docstatus','!=',2]], 'modified desc, name asc'),
    rows('Shift Assignment', ['employee','shift_type'], [['start_date','<=',date],['end_date','>=',date],['docstatus','=',1],['shift_type','=','Week Off']], 'name asc').catch(() => []),
    rows('Leave Application', ['employee','from_date','to_date','leave_type','status'], [['from_date','<=',date],['to_date','>=',date],['docstatus','!=',2]], 'name asc').catch(() => [])
  ]);

  const byPunch = new Map(), byAtt = new Map(), offSet = new Set(offs.map(o => o.employee)), lv = new Map();
  punches.forEach(p => { if (!byPunch.has(p.employee)) byPunch.set(p.employee, []); byPunch.get(p.employee).push(p); });
  marked.forEach(a => { if (!byAtt.has(a.employee)) byAtt.set(a.employee, a); });
  leaves.forEach(l => { const c = lv.get(l.employee); if (!c || (/approved/i.test(l.status) && !/approved/i.test(c.status))) lv.set(l.employee, l); });

  const closed = dayClosed(date), ref = tms(date + ' 23:59:59'), now = Date.now();

  const list = staff.map(s => {
    const a = byAtt.get(s.name), L = lv.get(s.name);
    let raw = (byPunch.get(s.name) || []).map(p => tms(p.time)).filter(v => v != null), src = 'Punch log';
    if (!raw.length && a) { raw = attTimes(a); src = 'Attendance record'; }
    const P = punchPair(raw), erp = String(a && a.status || '');

    let state;
    if (P.ev.length)                              state = P.out != null ? 'CHECKED_OUT' : (closed || now - P.in >= OUT_DUE_MS ? 'OUT_MISSING' : 'ON_FLOOR');
    else if (L && /approved/i.test(L.status))     state = 'LEAVE';
