}

/* ---- week-off entitlement: 6 present days = 1 off, runs count once ------ */
function applyWeekOff(kinds) {
  const present = kinds.filter(x => x.k === 'P' || x.k === 'HD').length;
  let budget = Math.floor(present / EARN_DAYS); const earned = budget;
  let run = 0;
  const out = { P: 0, HD: 0, L: 0, WO: 0, A: 0, earned };
  kinds.forEach(x => {
    if (x.k !== 'OFF') { run = 0; out[x.k]++; x.f = x.k; return; }
    run++;
    if (run === 1 && budget > 0) { budget--; out.WO++; x.f = 'WO'; } else { out.A++; x.f = 'A'; }
  });
  out.left = budget;
  return out;
}

