        if (!p.id) p.id = 'life-section-' + i;
        const h = $('.bcc-panel-head h2', p),
            label = (h?.textContent || p.dataset.bccPanel || 'Section').trim(),
            b = document.createElement('button');
        b.type = 'button';
        b.className = 'life-section-jump';
        b.textContent = label;
        b.dataset.target = p.id;
        b.onclick = () => p.scrollIntoView({
            behavior: 'smooth',
            block: 'start'
        });
        nav.insertBefore(b, reset || null)
    });
    navBusy = false
}

function boot() {
    burger();
    syncNav();
    setTimeout(renderSales, 700);
    const sel = document.getElementById('branchSel') ||
        document.querySelector('#branchSelect') ||
        document.querySelector('select[aria-label="Branch"]');
    if (sel && !sel.dataset.v5) {
        sel.dataset.v5 = '1';
        sel.addEventListener('change', () => setTimeout(renderSales, 600))
    }
    const holder = $('.bcc-panel[data-bcc-panel]')?.parentElement;
    if (holder) new MutationObserver(() => setTimeout(syncNav, 80)).observe(holder, {
        childList: true
    })
}
if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', () => setTimeout(boot, 1000));
else setTimeout(boot, 1000);
})();
